/**
 * GANADERO AD - FICHA ZOOTÉCNICA INDIVIDUAL DEL ANIMAL
 * Visualización completa del ejemplar: genealogía (padre, madre), días de preñez,
 * historial de partos, crías nacidas, pesajes previos, GDP e IEP.
 */



class FichaAnimal {
  constructor({ containerId = 'modal-ficha-animal', onCerrar, onEditar, onEliminar, onTrasladar, onExtraer, onReactivar, getRol }) {
    this.containerId = containerId;
    this.container = typeof document !== 'undefined' ? document.getElementById(containerId) : null;
    this.onCerrar = onCerrar;
    this.onEditar = onEditar;
    this.onEliminar = onEliminar;
    this.onTrasladar = onTrasladar;
    this.onExtraer = onExtraer;
    this.onReactivar = onReactivar;
    this.getRol = getRol;
    this.animal = null;
    this.historialPartos = [];
    this.historialPesajes = [];
    this.historialServicios = [];
    this.modalExtraerAbierto = false;
  }

  abrir(animal, partos = [], pesajes = [], servicios = []) {
    return this.mostrar(animal, partos, pesajes, servicios);
  }

  mostrar(animal, partos = [], pesajes = [], servicios = []) {
    if (!this.container && typeof document !== 'undefined') {
      this.container = document.getElementById(this.containerId || 'modal-ficha-animal');
    }
    this.animal = animal;
    const tag = animal.identificacionTag || animal.numero;
    const tagUpper = String(tag || '').trim().toUpperCase();
    const animalIdStr = String(animal.id || '').trim();

    this.historialPartos = (partos || []).filter((p) => {
      if (!p) return false;
      if (!p.madreTag && !p.madreId) return true; // Si se pasó en la lista sintetizada de este animal
      const pMadreTag = String(p.madreTag || '').trim().toUpperCase();
      const pMadreId = String(p.madreId || '').trim();
      return (tagUpper && pMadreTag === tagUpper) || (animalIdStr && pMadreId === animalIdStr);
    });

    if (Array.isArray(animal.partosPrevios) && animal.partosPrevios.length > 0) {
      animal.partosPrevios.forEach((p) => {
        if (!p) return;
        const yaExiste = this.historialPartos.some((x) => 
          (x.tagCria && p.tagCria && String(x.tagCria).trim().toUpperCase() === String(p.tagCria).trim().toUpperCase()) ||
          ((x.fechaParto || x.fecha) && (p.fechaParto || p.fecha) && (x.fechaParto || x.fecha) === (p.fechaParto || p.fecha))
        );
        if (!yaExiste) {
          this.historialPartos.push(p);
        }
      });
    }

    // Si el animal tiene fechaUltimoParto registrada y no está en historialPartos, incorporarlo
    const fechaUltParto = animal.fechaUltimoParto || animal.ultimoParto;
    if (fechaUltParto) {
      const fNorm = String(fechaUltParto).trim();
      const yaExiste = this.historialPartos.some((x) => String(x.fechaParto || x.fecha || '').trim() === fNorm);
      if (!yaExiste) {
        this.historialPartos.unshift({
          madreId: animal.id,
          madreTag: tag,
          fechaParto: fNorm,
          fecha: fNorm,
          tagCria: animal.tagCria || animal.criaTag || 'Cría Registrada',
          sexoCria: animal.sexoCria || 'hembra',
          pesoAlNacerKg: animal.pesoCria || animal.pesoAlNacerKg || 32,
          tipoParto: animal.tipoParto || 'Normal (Eutócico)',
          observaciones: 'Parto registrado en ficha del animal'
        });
      }
    }
    this.historialPesajes = pesajes.filter(
      (ps) => ps.animalId === animal.id || ps.tag === tag
    );
    this.historialServicios = servicios.filter(
      (s) => s.animalId === animal.id || s.tag === tag || s.animalTag === tag
    );
    if (animal.serviciosReproductivos && animal.serviciosReproductivos.length > 0) {
      animal.serviciosReproductivos.forEach((s) => {
        if (!this.historialServicios.some((x) => x.id === s.id)) {
          this.historialServicios.push(s);
        }
      });
    }
    this.render();
  }

  cerrar() {
    this.animal = null;
    if (this.container) this.container.innerHTML = '';
    if (this.onCerrar) this.onCerrar();
  }

  render() {
    if (!this.container || !this.animal) return;

    const a = this.animal;
    const tag = a.identificacionTag || a.numero;
    const especie = a.especie || 'bovino';
    const edadMeses = calcularEdadMeses(a.fechaNacimiento);
    const edadAnios = (edadMeses / 12).toFixed(1);

    const fParto = a.fechaUltimoParto || a.ultimoParto;
    const diasAbiertos = calcularDiasAbiertos(fParto, a.estadoReproductivo);
    const del = calcularDEL(fParto, a.categoria);
    const iep = calcularIEP(diasAbiertos, especie);

    const estaPrenada = (a.estadoReproductivo || '').toLowerCase().includes('prenad') || (a.estadoReproductivo || '').toLowerCase().includes('preñad');
    const diasG = parseInt(a.diasGestacionActual || a.diasGestacion || 0);

    // Partos y crías registradas
    let partosRegistrados = Array.isArray(this.historialPartos) ? [...this.historialPartos] : [];
    if (fParto) {
      const fPartoNorm = String(fParto).trim();
      const yaExisteParto = partosRegistrados.some((p) => {
        const fp = String(p.fechaParto || p.fecha || '').trim();
        return fp === fPartoNorm;
      });
      if (!yaExisteParto) {
        partosRegistrados.unshift({
          madreId: a.id,
          madreTag: tag,
          fechaParto: fPartoNorm,
          fecha: fPartoNorm,
          tagCria: a.tagCria || a.criaTag || 'Cría Registrada',
          sexoCria: a.sexoCria || 'hembra',
          pesoAlNacerKg: a.pesoCria || a.pesoAlNacerKg || 32,
          tipoParto: a.tipoParto || 'Normal (Eutócico)',
          observaciones: 'Parto registrado en ficha del animal'
        });
        this.historialPartos = partosRegistrados;
      }
    }
    const rol = this.getRol ? this.getRol() : 'consultor';
    const esSoloConsulta = rol === 'consulta' || rol === 'consultor';

    this.container.innerHTML = `
      <div class="fixed inset-0 bg-slate-950/80 backdrop-blur-sm z-50 flex items-center justify-center p-0 sm:p-5 overflow-y-auto">
        <div class="bg-white rounded-none sm:rounded-3xl shadow-2xl border border-slate-200 max-w-4xl w-full h-full sm:h-auto sm:max-h-[92vh] flex flex-col modal-fullscreen-mobile">
          <!-- CABECERA DE LA FICHA -->
          <div class="bg-gradient-to-r from-slate-950 via-slate-900 to-slate-950 text-white p-4 sm:p-6 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 sm:gap-4">
            <div class="flex items-center gap-3 sm:gap-4">
              <div class="w-12 h-12 sm:w-16 sm:h-16 rounded-2xl bg-emerald-600/20 text-emerald-400 border border-emerald-500/30 flex items-center justify-center text-2xl sm:text-3xl font-black shadow-inner shrink-0">
                ${especie === 'bufalino' ? '🦬' : '🐂'}
              </div>
              <div>
                <div class="flex items-center gap-1.5 sm:gap-2 flex-wrap">
                  <span class="text-xl sm:text-2xl font-black font-mono tracking-tight text-white">
                    Arete: ${tag}
                  </span>
                  <span class="px-2 py-0.5 rounded-full text-[10px] sm:text-xs font-bold ${especie === 'bufalino' ? 'bg-amber-500/20 text-amber-300 border border-amber-500/40' : 'bg-blue-500/20 text-blue-300 border border-blue-500/40'}">
                    ${especie === 'bufalino' ? 'Bufalino' : 'Vacuno'}
                  </span>
                  ${a._estaEnOtraFinca ? `
                    <span class="px-2 py-0.5 rounded-full text-[10px] sm:text-xs font-black bg-amber-500/30 text-amber-300 border border-amber-500/50">
                      🏡 En otra finca: ${a._fincaNombre || a.fincaNombre || 'Otra Finca'}
                    </span>
                  ` : ''}
                  ${(a.estadoVida === 'inactivo' || a.estado === 'inactivo' || a.motivoBaja) ? `
                    <span class="px-2 py-0.5 rounded-full text-[10px] sm:text-xs font-black bg-rose-500/30 text-rose-300 border border-rose-500/50">
                      🚪 Extraído (${a.motivoBaja || 'Baja'})
                    </span>
                  ` : ''}
                </div>
                <h3 class="text-sm sm:text-base font-bold text-slate-200 mt-0.5">${a.nombreAlias || a.nombre || 'Sin Alias Asignado'}</h3>
                <p class="text-[11px] sm:text-xs text-slate-400 font-mono mt-0.5">${a.raza} • ${a.categoria} • Lote: ${a.lote}${a._fincaNombre || a.fincaNombre ? ` • 🏡 Finca: ${a._fincaNombre || a.fincaNombre}` : ''}</p>
              </div>
            </div>

            <div class="flex items-center gap-2 w-full sm:w-auto justify-between sm:justify-end shrink-0 flex-wrap pt-2 sm:pt-0 border-t sm:border-t-0 border-slate-800">
              ${!esSoloConsulta ? `
                ${(a.estadoVida === 'inactivo' || a.estado === 'inactivo' || a.motivoBaja) ? `
                  <button id="btn-ficha-reactivar-animal" class="flex-1 sm:flex-none px-3.5 py-2.5 sm:py-2 bg-emerald-600 hover:bg-emerald-500 active:scale-95 text-white font-black text-xs rounded-xl shadow transition flex items-center justify-center gap-1.5 cursor-pointer" title="Activar nuevamente en este hato">
                    <span>🔄</span> Reactivar en el Hato
                  </button>
                ` : `
                  <button id="btn-ficha-extraer-animal" class="flex-1 sm:flex-none px-3.5 py-2.5 sm:py-2 bg-amber-600 hover:bg-amber-500 active:scale-95 text-white font-black text-xs rounded-xl shadow transition flex items-center justify-center gap-1.5 cursor-pointer" title="Extraer animal por venta o muerte">
                    <span>🚪</span> Extraer Animal
                  </button>
                  <button id="btn-ficha-trasladar-animal" class="flex-1 sm:flex-none px-3.5 py-2.5 sm:py-2 bg-purple-600 hover:bg-purple-500 active:scale-95 text-white font-bold text-xs rounded-xl shadow transition flex items-center justify-center gap-1.5 cursor-pointer" title="Trasladar este animal a otra finca">
                    <span>🚚</span> Trasladar Finca
                  </button>
                `}
                <button id="btn-ficha-editar-animal" class="flex-1 sm:flex-none px-3.5 py-2.5 sm:py-2 bg-blue-600 hover:bg-blue-500 active:scale-95 text-white font-bold text-xs rounded-xl shadow transition flex items-center justify-center gap-1.5 cursor-pointer" title="Modificar datos de este ejemplar">
                  <span>✏️</span> Editar
                </button>
                <button id="btn-ficha-eliminar-animal" class="p-2.5 sm:px-3.5 sm:py-2 bg-rose-500/20 hover:bg-rose-500/30 text-rose-300 hover:text-white border border-rose-500/40 font-bold text-xs rounded-xl shadow transition flex items-center justify-center gap-1.5 cursor-pointer" title="Eliminar este animal del inventario">
                  <span>🗑️</span>
                </button>
              ` : ''}
              <button id="btn-cerrar-modal-ficha" class="p-2.5 sm:p-2 rounded-xl bg-slate-800 text-slate-300 hover:text-white hover:bg-slate-700 transition cursor-pointer" title="Cerrar Ficha">
                ✕
              </button>
            </div>
          </div>

          <!-- CONTENIDO SCROLLEABLE -->
          <div class="p-5 sm:p-6 overflow-y-auto space-y-6 flex-1 text-xs">
            ${(a.estadoVida === 'inactivo' || a.estado === 'inactivo' || a.motivoBaja) ? `
              <div class="bg-rose-50 border-2 border-rose-300 rounded-2xl p-4 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3">
                <div>
                  <div class="flex items-center gap-2">
                    <span class="text-sm font-black text-rose-900">🚪 ANIMAL EXTRAÍDO DEL HATO</span>
                    <span class="px-2 py-0.5 rounded-full font-mono text-[10px] font-black uppercase bg-rose-200 text-rose-900">${a.motivoBaja || 'Baja'}</span>
                  </div>
                  <div class="text-xs text-rose-800 font-medium mt-1">
                    ${(a.motivoBaja || '').toLowerCase() === 'venta' ? `
                      Vendido a: <strong>${a.compradorVenta || 'Comprador no registrado'}</strong> • Valor Venta: <strong>$${(parseFloat(a.valorVenta) || 0).toLocaleString('es-CO')} COP</strong> ${a.pesoVenta ? `• Peso: <strong>${a.pesoVenta} Kg</strong>` : ''} • Fecha: <strong>${a.fechaBaja || '-'}</strong>
                    ` : `
                      Motivo / Causa de Muerte: <strong>${a.motivoMuerte || 'Causa no especificada'}</strong> • Fecha: <strong>${a.fechaBaja || '-'}</strong>
                    `}
                  </div>
                </div>
                <button id="btn-ficha-banner-reactivar" class="px-4 py-2 bg-emerald-700 hover:bg-emerald-600 text-white font-black text-xs rounded-xl shadow transition cursor-pointer active:scale-95 shrink-0">
                  <span>🔄</span> Reactivar Ejemplar
                </button>
              </div>
            ` : ''}
            <!-- SECCIÓN 1: DATOS BÁSICOS & GENEALOGÍA -->
            <div>
              <h4 class="font-black text-slate-900 text-sm uppercase tracking-wider mb-3 flex items-center gap-2">
                <span>🧬</span> Identidad y Genealogía (Pedigree)
              </h4>
              <div class="grid grid-cols-2 sm:grid-cols-4 gap-3 bg-slate-50 p-4 rounded-2xl border border-slate-200">
                <div>
                  <span class="block text-slate-400 text-[10px] uppercase font-bold">Fecha Nacimiento</span>
                  <span class="font-bold text-slate-800">${a.fechaNacimiento || 'No registrada'}</span>
                  <span class="text-[10px] text-slate-500 block">Edad: ${edadMeses} meses (${edadAnios} años)</span>
                </div>
                <div>
                  <span class="block text-slate-400 text-[10px] uppercase font-bold">Sexo</span>
                  <span class="font-bold text-slate-800">${a.sexo === 'hembra' ? '♀️ Hembra' : '♂️ Macho'}</span>
                </div>
                <div>
                  <span class="block text-slate-400 text-[10px] uppercase font-bold">Padre (Toro)</span>
                  <span class="font-bold font-mono text-slate-900 bg-white px-2 py-0.5 rounded border border-slate-200 inline-block mt-0.5">
                    ${a.padreTag || a.padre || 'Desconocido'}
                  </span>
                </div>
                <div>
                  <span class="block text-slate-400 text-[10px] uppercase font-bold">Madre (Vaca)</span>
                  <span class="font-bold font-mono text-slate-900 bg-white px-2 py-0.5 rounded border border-slate-200 inline-block mt-0.5">
                    ${a.madreTag || a.madre || 'Desconocida'}
                  </span>
                </div>
              </div>
            </div>

            <!-- SECCIÓN 2: ESTADO REPRODUCTIVO Y DÍAS DE PREÑEZ -->
            <div>
              <h4 class="font-black text-slate-900 text-sm uppercase tracking-wider mb-3 flex items-center gap-2">
                <span>⚡</span> Estado Reproductivo & Indicadores Zootécnicos
              </h4>
              <div class="grid grid-cols-1 sm:grid-cols-3 gap-3">
                <!-- Tarjeta Preñez -->
                <div class="p-4 rounded-2xl border ${estaPrenada ? 'border-emerald-300 bg-emerald-50/60' : 'border-slate-200 bg-slate-50'}">
                  <span class="text-[10px] font-bold uppercase text-slate-500 block">Diagnóstico Actual</span>
                  <div class="text-base font-black ${estaPrenada ? 'text-emerald-800' : 'text-slate-800'} mt-0.5">
                    ${estaPrenada ? '🟢 Preñada (Gestante)' : (a.estadoReproductivo || 'Vacía')}
                  </div>
                  ${estaPrenada ? `
                    <div class="mt-2 pt-2 border-t border-emerald-200">
                      <span class="text-xs font-bold text-emerald-900">Días de Preñez:</span>
                      <div class="text-xl font-black font-mono text-emerald-700">${diasG} días</div>
                      <div class="w-full h-2 bg-emerald-200 rounded-full mt-1.5 overflow-hidden">
                        <div class="h-full bg-emerald-600 rounded-full" style="width: ${Math.min(100, (diasG / 283) * 100)}%"></div>
                      </div>
                      <span class="text-[10px] text-emerald-700 block mt-1">${(diasG / 30.4).toFixed(1)} meses de gestación (~${283 - diasG} días al parto)</span>
                    </div>
                  ` : `
                    <span class="text-[10px] text-slate-400 block mt-1">Días Abiertos: ${diasAbiertos} días</span>
                  `}
                </div>

                <!-- Tarjeta Intervalo Entre Partos -->
                <div class="p-4 rounded-2xl border border-slate-200 bg-slate-50">
                  <span class="text-[10px] font-bold uppercase text-slate-500 block">Intervalo Entre Partos (IEP)</span>
                  <div class="text-base font-black text-slate-900 mt-0.5">
                    ${fParto ? `${iep.dias} Días` : 'Primerizo / Sin registro'}
                  </div>
                  <span class="text-[10px] text-slate-500 block mt-1">
                    ${fParto ? `Proyección: ${iep.meses} Meses entre partos` : 'Sin partos previos'}
                  </span>
                  <div class="mt-2 text-[10px] text-slate-400">
                    Último Parto: <strong>${fParto || 'No registra'}</strong>
                  </div>
                </div>

                <!-- Tarjeta Productiva (Peso & Leche) -->
                <div class="p-4 rounded-2xl border border-slate-200 bg-slate-50">
                  <span class="text-[10px] font-bold uppercase text-slate-500 block">Producción Actual</span>
                  <div class="text-base font-black text-slate-900 mt-0.5">
                    ${a.ultimoPesoKg || a.pesoActual ? `${a.ultimoPesoKg || a.pesoActual} kg` : '-'}
                  </div>
                  <span class="text-[10px] text-emerald-700 font-bold block mt-1">
                    GDP: ${a.gdpPromedioGDia !== undefined ? `${a.gdpPromedioGDia} g/d` : (a.gdpActual ? `${a.gdpActual} g/d` : 'No calculada')}
                  </span>
                  <div class="mt-2 text-[10px] text-slate-500">
                    Leche: <strong>${a.promedioLecheDiariaL || a.produccionLecheDiaria || 0} L/día</strong> ${del > 0 ? `(${del} DEL)` : ''}
                  </div>
                </div>
              </div>
            </div>

            <!-- SECCIÓN 3: HISTORIAL DE PARTOS Y CRÍAS -->
            <div>
              <div class="flex justify-between items-center mb-3">
                <h4 class="font-black text-slate-900 text-sm uppercase tracking-wider flex items-center gap-2">
                  <span>🍼</span> Historial de Partos y Crías (${partosRegistrados.length})
                </h4>
              </div>

              ${partosRegistrados.length > 0 ? `
                <div class="overflow-x-auto border border-slate-200 rounded-2xl">
                  <table class="w-full text-left text-xs">
                    <thead class="bg-slate-100 uppercase font-bold text-slate-700 text-[10px]">
                      <tr>
                        <th class="p-2.5">Fecha de Parto</th>
                        <th class="p-2.5">Tag de la Cría</th>
                        <th class="p-2.5">Sexo Cría</th>
                        <th class="p-2.5 text-right">Peso al Nacer</th>
                        <th class="p-2.5">Tipo de Parto</th>
                        <th class="p-2.5">Observaciones</th>
                      </tr>
                    </thead>
                    <tbody class="divide-y divide-slate-100">
                      ${partosRegistrados.map((p) => `
                        <tr class="hover:bg-slate-50">
                          <td class="p-2.5 font-bold">${p.fechaParto || p.fecha}</td>
                          <td class="p-2.5 font-mono font-black text-emerald-800">${p.tagCria || p.tagCriaGenerado || p.criaId || 'Cría Registrada'}</td>
                          <td class="p-2.5">${(p.sexoCria || '').toLowerCase().includes('hembra') ? '♀️ Hembra' : '♂️ Macho'}</td>
                          <td class="p-2.5 text-right font-mono font-bold">${p.pesoAlNacerKg || p.pesoCria || p.pesoNacimientoKg || 32} kg</td>
                          <td class="p-2.5">${p.tipoParto || 'Normal (Eutócico)'}</td>
                          <td class="p-2.5 text-slate-500">${p.observaciones || 'Sin novedad'}</td>
                        </tr>
                      `).join('')}
                    </tbody>
                  </table>
                </div>
              ` : `
                <div class="p-6 bg-slate-50 rounded-2xl border border-dashed border-slate-200 text-center text-slate-400 text-xs">
                  Este ejemplar no tiene partos o crías registradas en su historial.
                </div>
              `}
            </div>

            <!-- SECCIÓN 4: HISTORIAL DE SERVICIOS REPRODUCTIVOS (IA / TE / MONTA) -->
            ${(a.sexo || '').toLowerCase() === 'hembra' ? `
              <div>
                <div class="flex justify-between items-center mb-3">
                  <h4 class="font-black text-slate-900 text-sm uppercase tracking-wider flex items-center gap-2">
                    <span>🧬</span> Historial de Inseminaciones, Embriones y Montas (${this.historialServicios.length})
                  </h4>
                </div>

                ${this.historialServicios.length > 0 ? `
                  <div class="overflow-x-auto border border-slate-200 rounded-2xl">
                    <table class="w-full text-left text-xs">
                      <thead class="bg-slate-100 uppercase font-bold text-slate-700 text-[10px]">
                        <tr>
                          <th class="p-2.5">Fecha</th>
                          <th class="p-2.5">Modalidad</th>
                          <th class="p-2.5">Toro / Pajilla / Donadora</th>
                          <th class="p-2.5">Técnico / Responsable</th>
                          <th class="p-2.5">Protocolo / Observación</th>
                          <th class="p-2.5">Resultado</th>
                        </tr>
                      </thead>
                      <tbody class="divide-y divide-slate-100">
                        ${this.historialServicios.map((s) => {
                          let badgeTipo = 'bg-indigo-100 text-indigo-800';
                          let nomTipo = '💉 Inseminación Artificial';
                          if (s.tipo === 'transferencia_embriones') {
                            badgeTipo = 'bg-purple-100 text-purple-800';
                            nomTipo = '🔬 Transf. Embriones';
                          } else if (s.tipo === 'monta_natural') {
                            badgeTipo = 'bg-amber-100 text-amber-900';
                            nomTipo = '🐂 Servicio con Toro';
                          }

                          const st = s.resultado || 'Pendiente Chequeo';
                          let badgeSt = 'bg-amber-100 text-amber-800 border-amber-300';
                          if (st === 'Preñada Confirmada') badgeSt = 'bg-emerald-100 text-emerald-800 border-emerald-300';
                          if (st === 'Vacía / Repitió') badgeSt = 'bg-rose-100 text-rose-800 border-rose-300';

                          return `
                            <tr class="hover:bg-slate-50">
                              <td class="p-2.5 font-bold font-mono text-slate-800">${s.fecha}</td>
                              <td class="p-2.5">
                                <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${badgeTipo}">
                                  ${nomTipo}
                                </span>
                              </td>
                              <td class="p-2.5 font-bold text-slate-800">
                                ${s.reproductor || '-'}
                                ${s.donadora ? `<span class="block text-[10px] text-purple-700 font-normal">Donadora: ${s.donadora}</span>` : ''}
                              </td>
                              <td class="p-2.5 text-slate-600">${s.tecnico || '-'}</td>
                              <td class="p-2.5 text-slate-500">${s.protocolo || s.observaciones || '-'}</td>
                              <td class="p-2.5">
                                <span class="px-2 py-0.5 rounded-full text-[10px] font-bold border ${badgeSt}">
                                  ${st}
                                </span>
                              </td>
                            </tr>
                          `;
                        }).join('')}
                      </tbody>
                    </table>
                  </div>
                ` : `
                  <div class="p-6 bg-slate-50 rounded-2xl border border-dashed border-slate-200 text-center text-slate-400 text-xs">
                    No se registran servicios reproductivos (IA, TE o Monta) para esta hembra.
                  </div>
                `}
              </div>
            ` : ''}

            <!-- SECCIÓN 5: HISTORIAL DE PESAJES -->
            <div>
              <div class="flex justify-between items-center mb-3">
                <h4 class="font-black text-slate-900 text-sm uppercase tracking-wider flex items-center gap-2">
                  <span>⚖️</span> Trazabilidad de Pesajes y Ganancia Ponderal (${this.historialPesajes.length})
                </h4>
              </div>

              <div class="bg-slate-50 p-4 rounded-2xl border border-slate-200 mb-3">
                <div class="flex justify-between items-center text-xs text-slate-700">
                  <span>Último Pesaje Registrado: <strong>${a.fechaUltimoPesaje || a.ultimoPesajeFecha || 'Reciente'}</strong></span>
                  <span class="font-mono font-black text-base text-emerald-800">${a.ultimoPesoKg || a.pesoActual || 0} kg</span>
                </div>
                <div class="mt-2 text-[11px] text-slate-500">
                  Condición corporal actual evaluada: <strong>${a.condicionCorporal || '3.5 (Óptima)'}</strong>
                </div>
              </div>

              ${this.historialPesajes.length > 0 ? `
                <div class="overflow-x-auto border border-slate-200 rounded-2xl">
                  <table class="w-full text-left text-xs">
                    <thead class="bg-slate-100 uppercase font-bold text-slate-700 text-[10px]">
                      <tr>
                        <th class="p-2.5">Fecha</th>
                        <th class="p-2.5 text-right">Peso Registrado</th>
                        <th class="p-2.5 text-right">GDP</th>
                        <th class="p-2.5">Lote / Ubicación</th>
                        <th class="p-2.5">Responsable</th>
                        <th class="p-2.5">Observaciones</th>
                      </tr>
                    </thead>
                    <tbody class="divide-y divide-slate-100">
                      ${this.historialPesajes.slice().sort((p1, p2) => (p2.fecha || '').localeCompare(p1.fecha || '')).map((ps) => {
                        const pNum = ps.pesoNuevo || ps.peso || 0;
                        return `
                          <tr class="hover:bg-slate-50">
                            <td class="p-2.5 font-bold font-mono text-slate-800">${ps.fecha || '-'}</td>
                            <td class="p-2.5 text-right font-mono font-black text-emerald-800">${pNum} kg</td>
                            <td class="p-2.5 text-right font-mono font-bold ${ps.gdp ? (Number(ps.gdp) >= 0 ? 'text-emerald-700' : 'text-rose-700') : 'text-slate-400'}">
                              ${ps.gdp ? `${ps.gdp > 0 ? '+' : ''}${ps.gdp} g/d` : '-'}
                            </td>
                            <td class="p-2.5 font-mono text-slate-600">${ps.lote || a.lote || 'General'}</td>
                            <td class="p-2.5 text-slate-600">${ps.responsable || 'Báscula'}</td>
                            <td class="p-2.5 text-slate-500">${ps.observaciones || '-'}</td>
                          </tr>
                        `;
                      }).join('')}
                    </tbody>
                  </table>
                </div>
              ` : ''}
            </div>

            <!-- SECCIÓN 6: HISTORIAL DE PALPACIONES, CONTROLES DE LECHE Y LABORES DE CAMPO -->
            <div>
              <div class="flex justify-between items-center mb-3">
                <h4 class="font-black text-slate-900 text-sm uppercase tracking-wider flex items-center gap-2">
                  <span>🩺</span> Palpaciones, Controles de Leche, Destetes y Bitácora (${(a.historialEventos || []).length})
                </h4>
              </div>

              ${Array.isArray(a.historialEventos) && a.historialEventos.length > 0 ? `
                <div class="overflow-x-auto border border-slate-200 rounded-2xl">
                  <table class="w-full text-left text-xs">
                    <thead class="bg-slate-100 uppercase font-bold text-slate-700 text-[10px]">
                      <tr>
                        <th class="p-2.5">Fecha</th>
                        <th class="p-2.5">Labor / Evento</th>
                        <th class="p-2.5">Resultado / Detalle Zootécnico</th>
                        <th class="p-2.5">Responsable / Profesional</th>
                      </tr>
                    </thead>
                    <tbody class="divide-y divide-slate-100">
                      ${a.historialEventos.map((ev) => {
                        let badgeTipo = 'bg-slate-100 text-slate-800';
                        let tituloTipo = ev.tipo || 'Evento';
                        let detalleEv = '';

                        if (ev.tipo === 'palpacion') {
                          badgeTipo = 'bg-rose-100 text-rose-800 border border-rose-200';
                          tituloTipo = '🩺 Palpación Ginecológica';
                          detalleEv = `<strong>${ev.resultado || 'Diagnóstico'}</strong> ${ev.diasGestacion ? `• ${ev.diasGestacion} días gestación` : ''} ${ev.diagnostico || ev.estructuraOvario ? `(${ev.diagnostico || ev.estructuraOvario})` : ''}`;
                        } else if (ev.tipo === 'pesaje_leche') {
                          badgeTipo = 'bg-cyan-100 text-cyan-800 border border-cyan-200';
                          tituloTipo = '🥛 Control Lechero';
                          detalleEv = `Producción: <strong>${ev.litros || 0} L</strong> ${ev.jornada ? `• Jornada ${ev.jornada}` : ''} ${ev.grasa ? `• Grasa: ${ev.grasa}%` : ''} ${ev.proteina ? `• Proteína: ${ev.proteina}%` : ''}`;
                        } else if (ev.tipo === 'destete') {
                          badgeTipo = 'bg-orange-100 text-orange-800 border border-orange-200';
                          tituloTipo = '🌾 Destete';
                          detalleEv = `Destete completado ${ev.pesoDestete ? `• Peso: <strong>${ev.pesoDestete} kg</strong>` : ''} ${ev.loteDestino ? `• Asignado a: <strong>${ev.loteDestino}</strong>` : ''}`;
                        } else if (ev.tipo === 'parto') {
                          badgeTipo = 'bg-amber-100 text-amber-800 border border-amber-200';
                          tituloTipo = '🍼 Parto';
                          detalleEv = `Cría: <strong>${ev.criaTag || 'S/N'}</strong> (${ev.sexoCria || 'Cría'}) ${ev.pesoAlNacerKg ? `• Peso al nacer: ${ev.pesoAlNacerKg} kg` : ''} ${ev.tipoParto ? `• Parto: ${ev.tipoParto}` : ''}`;
                        } else {
                          detalleEv = ev.detalle || ev.observaciones || '-';
                        }

                        return `
                          <tr class="hover:bg-slate-50">
                            <td class="p-2.5 font-bold font-mono text-slate-800 whitespace-nowrap">${ev.fecha || '-'}</td>
                            <td class="p-2.5 whitespace-nowrap">
                              <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${badgeTipo}">
                                ${tituloTipo}
                              </span>
                            </td>
                            <td class="p-2.5 text-slate-700">${detalleEv}</td>
                            <td class="p-2.5 text-slate-500 whitespace-nowrap">${ev.responsable || ev.veterinario || 'Veterinario / Operario'}</td>
                          </tr>
                        `;
                      }).join('')}
                    </tbody>
                  </table>
                </div>
              ` : `
                <div class="p-6 bg-slate-50 rounded-2xl border border-dashed border-slate-200 text-center text-slate-400 text-xs">
                  No se registran eventos adicionales de campo (palpaciones, leche o destetes) para este ejemplar.
                </div>
              `}
            </div>
          </div>

          <!-- PIE DE LA FICHA -->
          <div class="bg-slate-50 p-4 border-t border-slate-200 flex flex-col sm:flex-row justify-between items-center gap-3">
            <div>
              ${!esSoloConsulta ? `
                <button id="btn-ficha-editar-animal-footer" class="px-4 py-2 bg-blue-600 hover:bg-blue-500 active:scale-95 text-white font-bold text-xs rounded-xl shadow transition flex items-center gap-1.5 cursor-pointer">
                  <span>✏️</span> Modificar Datos de este Animal
                </button>
              ` : '<span class="text-xs text-slate-400 italic">Modo sólo lectura (Consultor)</span>'}
            </div>
            <button id="btn-cerrar-ficha-footer" class="px-5 py-2 bg-slate-900 hover:bg-slate-800 text-white font-bold text-xs rounded-xl shadow transition cursor-pointer">
              Cerrar Ficha
            </button>
          </div>
        </div>

        <!-- MODAL DE EXTRACCIÓN (VENTA O MUERTE) -->
        ${this.modalExtraerAbierto ? this.renderModalExtraer() : ''}
      </div>
    `;

    this.attachEvents();
  }

  renderModalExtraer() {
    const a = this.animal;
    const tag = a.identificacionTag || a.numero;
    const hoy = new Date().toISOString().split('T')[0];

    return `
      <div id="modal-extraer-animal" class="fixed inset-0 bg-slate-950/85 backdrop-blur-sm z-[60] flex items-center justify-center p-3 sm:p-5">
        <div class="bg-white rounded-3xl shadow-2xl border border-slate-200 max-w-lg w-full overflow-hidden animate-fadeIn">
          <div class="bg-gradient-to-r from-amber-900 via-amber-800 to-amber-900 text-white p-5 flex justify-between items-center">
            <div class="flex items-center gap-3">
              <span class="text-2xl">🚪</span>
              <div>
                <h3 class="font-black text-base">Extraer Animal: ${tag}</h3>
                <p class="text-xs text-amber-200 mt-0.5">Registre la salida del ejemplar por venta o muerte.</p>
              </div>
            </div>
            <button id="btn-cerrar-modal-extraer" class="text-amber-200 hover:text-white text-lg font-bold cursor-pointer">✕</button>
          </div>

          <div class="p-5 sm:p-6 space-y-4 text-xs">
            <div>
              <label class="block font-black text-slate-800 uppercase tracking-wider text-[11px] mb-2">Motivo de Extracción:</label>
              <div class="grid grid-cols-2 gap-3">
                <label class="flex items-center justify-center gap-2 p-3 rounded-2xl border-2 border-emerald-500 bg-emerald-50/60 font-black cursor-pointer text-emerald-950">
                  <input type="radio" name="radio-motivo-extraccion" value="Venta" checked class="text-emerald-600">
                  <span>💰 Por Venta</span>
                </label>
                <label class="flex items-center justify-center gap-2 p-3 rounded-2xl border-2 border-slate-200 bg-slate-50 font-black cursor-pointer text-slate-800">
                  <input type="radio" name="radio-motivo-extraccion" value="Muerte" class="text-rose-600">
                  <span>💀 Por Muerte</span>
                </label>
              </div>
            </div>

            <!-- Campos para Venta -->
            <div id="seccion-extraer-venta" class="space-y-3 bg-amber-50/60 p-4 rounded-2xl border border-amber-200">
              <div>
                <label class="block font-bold text-slate-800 mb-1">¿A quién se le vendió? (Comprador):</label>
                <input type="text" id="input-extraer-comprador" placeholder="Ej. Frigorífico, Subasta, Don Carlos..." class="w-full px-3 py-2 bg-white rounded-xl border border-slate-300 font-bold outline-none text-xs">
              </div>
              <div class="grid grid-cols-2 gap-3">
                <div>
                  <label class="block font-bold text-slate-800 mb-1">Valor Venta ($ COP):</label>
                  <input type="number" id="input-extraer-valor" placeholder="Ej. 3500000" class="w-full px-3 py-2 bg-white rounded-xl border border-slate-300 font-bold font-mono text-emerald-800 outline-none text-xs">
                </div>
                <div>
                  <label class="block font-bold text-slate-800 mb-1">Peso Venta (kg):</label>
                  <input type="number" step="0.5" id="input-extraer-peso" value="${a.ultimoPesoKg || ''}" placeholder="Ej. 480" class="w-full px-3 py-2 bg-white rounded-xl border border-slate-300 font-bold font-mono outline-none text-xs">
                </div>
              </div>
              <p class="text-[10px] text-amber-900 font-medium">💡 Este valor se sumará a los ingresos financieros de la finca.</p>
            </div>

            <!-- Campos para Muerte -->
            <div id="seccion-extraer-muerte" class="space-y-3 bg-rose-50/60 p-4 rounded-2xl border border-rose-200 hidden">
              <div>
                <label class="block font-bold text-slate-800 mb-1">Cuadro de Motivo / Causa de la Muerte *:</label>
                <textarea id="input-extraer-causa-muerte" rows="3" placeholder="Describa en este cuadro el motivo o causa de la muerte (ej. Timpanismo agudo, picadura de serpiente, infarto, enfermedad, accidente, diagnóstico veterinario)..." class="w-full px-3 py-2 bg-white rounded-xl border border-slate-300 font-medium outline-none text-xs resize-none focus:border-rose-500"></textarea>
              </div>
            </div>

            <div class="grid grid-cols-2 gap-3">
              <div>
                <label class="block font-bold text-slate-800 mb-1">Fecha del Suceso:</label>
                <input type="date" id="input-extraer-fecha" value="${hoy}" class="w-full px-3 py-2 bg-white rounded-xl border border-slate-300 font-bold outline-none text-xs">
              </div>
              <div>
                <label class="block font-bold text-slate-800 mb-1">Observaciones:</label>
                <input type="text" id="input-extraer-obs" placeholder="Detalles de la baja..." class="w-full px-3 py-2 bg-white rounded-xl border border-slate-300 text-xs outline-none">
              </div>
            </div>

            <div class="flex justify-end gap-2 pt-2 border-t border-slate-100">
              <button id="btn-cancelar-modal-extraer" class="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-xl text-xs transition cursor-pointer">
                Cancelar
              </button>
              <button id="btn-confirmar-modal-extraer" class="px-5 py-2 bg-rose-600 hover:bg-rose-500 text-white font-black rounded-xl text-xs shadow-md transition cursor-pointer active:scale-95">
                Confirmar Extracción
              </button>
            </div>
          </div>
        </div>
      </div>
    `;
  }

  attachEvents() {
    const btnCerrar = this.container.querySelector('#btn-cerrar-modal-ficha');
    if (btnCerrar) btnCerrar.addEventListener('click', () => this.cerrar());

    const btnFooter = this.container.querySelector('#btn-cerrar-ficha-footer');
    if (btnFooter) btnFooter.addEventListener('click', () => this.cerrar());

    const btnEditar = this.container.querySelector('#btn-ficha-editar-animal');
    if (btnEditar) {
      btnEditar.addEventListener('click', () => {
        if (this.onEditar) this.onEditar(this.animal);
      });
    }

    const btnEditarFooter = this.container.querySelector('#btn-ficha-editar-animal-footer');
    if (btnEditarFooter) {
      btnEditarFooter.addEventListener('click', () => {
        if (this.onEditar) this.onEditar(this.animal);
      });
    }

    const btnEliminar = this.container.querySelector('#btn-ficha-eliminar-animal');
    if (btnEliminar) {
      btnEliminar.addEventListener('click', () => {
        const tag = this.animal.identificacionTag || this.animal.numero;
        if (confirm(`¿Estás seguro de eliminar permanentemente al ejemplar ${tag} del inventario?`)) {
          if (this.onEliminar) this.onEliminar(this.animal.id);
        }
      });
    }

    const btnTrasladar = this.container.querySelector('#btn-ficha-trasladar-animal');
    if (btnTrasladar) {
      btnTrasladar.addEventListener('click', () => {
        if (this.onTrasladar) this.onTrasladar(this.animal);
      });
    }

    // Botón abrir modal de extracción
    const btnExtraer = this.container.querySelector('#btn-ficha-extraer-animal');
    if (btnExtraer) {
      btnExtraer.addEventListener('click', () => {
        this.modalExtraerAbierto = true;
        this.render();
      });
    }

    // Botones de reactivación
    const ejecutarReactivacion = () => {
      const tag = this.animal.identificacionTag || this.animal.numero;
      if (confirm(`¿Deseas activar nuevamente al animal ${tag} en este hato?`)) {
        if (this.onReactivar) {
          this.onReactivar(this.animal);
          this.cerrar();
        }
      }
    };

    const btnReactivar = this.container.querySelector('#btn-ficha-reactivar-animal');
    if (btnReactivar) btnReactivar.addEventListener('click', ejecutarReactivacion);

    const btnBannerReactivar = this.container.querySelector('#btn-ficha-banner-reactivar');
    if (btnBannerReactivar) btnBannerReactivar.addEventListener('click', ejecutarReactivacion);

    // Eventos dentro del modal de extracción
    if (this.modalExtraerAbierto) {
      const btnCerrarExtraer = this.container.querySelector('#btn-cerrar-modal-extraer');
      const btnCancelExtraer = this.container.querySelector('#btn-cancelar-modal-extraer');
      const cerrarModalExtraer = () => {
        this.modalExtraerAbierto = false;
        this.render();
      };
      if (btnCerrarExtraer) btnCerrarExtraer.addEventListener('click', cerrarModalExtraer);
      if (btnCancelExtraer) btnCancelExtraer.addEventListener('click', cerrarModalExtraer);

      const secVenta = this.container.querySelector('#seccion-extraer-venta');
      const secMuerte = this.container.querySelector('#seccion-extraer-muerte');
      const radios = this.container.querySelectorAll('input[name="radio-motivo-extraccion"]');

      radios.forEach((r) => {
        r.addEventListener('change', () => {
          if (r.value === 'Venta') {
            if (secVenta) secVenta.classList.remove('hidden');
            if (secMuerte) secMuerte.classList.add('hidden');
          } else {
            if (secVenta) secVenta.classList.add('hidden');
            if (secMuerte) secMuerte.classList.remove('hidden');
          }
        });
      });

      const btnConfirmarExtraer = this.container.querySelector('#btn-confirmar-modal-extraer');
      if (btnConfirmarExtraer) {
        btnConfirmarExtraer.addEventListener('click', () => {
          let motivo = 'Venta';
          radios.forEach((rd) => { if (rd.checked) motivo = rd.value; });

          const fecha = this.container.querySelector('#input-extraer-fecha')?.value || new Date().toISOString().split('T')[0];
          const observaciones = (this.container.querySelector('#input-extraer-obs')?.value || '').trim();

          const datos = {
            motivo,
            fecha,
            observaciones
          };

          if (motivo === 'Venta') {
            const comprador = (this.container.querySelector('#input-extraer-comprador')?.value || '').trim() || 'Cliente Particular';
            const valorVenta = parseFloat(this.container.querySelector('#input-extraer-valor')?.value) || 0;
            const pesoVenta = parseFloat(this.container.querySelector('#input-extraer-peso')?.value) || this.animal.ultimoPesoKg || null;
            datos.comprador = comprador;
            datos.valorVenta = valorVenta;
            datos.pesoVenta = pesoVenta;
          } else {
            const causa = (this.container.querySelector('#input-extraer-causa-muerte')?.value || '').trim() || 'Causa no especificada';
            datos.motivoMuerte = causa;
          }

          if (this.onExtraer) {
            this.onExtraer(this.animal, datos);
          }
          this.modalExtraerAbierto = false;
          this.cerrar();
        });
      }
    }
  }
}


// ============================================================================
// ARCHIVO: frontend/src/components/PanelAlertas.js
// ============================================================================
/**
 * GANADERO AD - PANEL DE ALERTAS ZOOTÉCNICAS E IA
 * Notificaciones destacadas para animales improductivos, sanidad y auditoría.
 */



class PanelAlertas {
  constructor({ containerId, getAnimales, onAccionZootecnica }) {
    this.container = document.getElementById(containerId);
    this.getAnimales = getAnimales;
    this.onAccionZootecnica = onAccionZootecnica;
    this.filtroSeveridad = 'todas'; // 'todas' | 'critica' | 'advertencia' | 'sanidad_preventiva'
    this.alertasResueltas = new Set();
  }

  init() {
    this.render();
  }

  resolverAlerta(id) {
    this.alertasResueltas.add(id);
    this.render();
  }

  obtenerAlertas() {
    const todos = this.getAnimales ? this.getAnimales() : [];
    const lista = detectarAlertasZootecnicas(todos);
    return lista.filter((a) => !this.alertasResueltas.has(a.id));
  }

  render() {
    if (!this.container) return;

    const alertas = this.obtenerAlertas();
    const criticas = alertas.filter((a) => a.severidad === 'critica');
    const advertencias = alertas.filter((a) => a.severidad === 'advertencia');
    const sanidad = alertas.filter((a) => a.severidad === 'sanidad_preventiva');

    let mostradas = alertas;
    if (this.filtroSeveridad !== 'todas') {
      mostradas = alertas.filter((a) => a.severidad === this.filtroSeveridad);
    }

    this.container.innerHTML = `
      <div class="space-y-4">
        <!-- HEADER DE ALERTAS INTELIGENTES -->
        <div class="bg-gradient-to-r from-slate-950 via-slate-900 to-slate-950 text-white p-5 rounded-2xl shadow-xl border border-slate-800">
          <div class="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <div class="flex items-center gap-3">
              <div class="w-12 h-12 rounded-2xl bg-rose-500/20 text-rose-400 border border-rose-500/30 flex items-center justify-center text-2xl shadow">
                🚨
              </div>
              <div>
                <h2 class="text-base sm:text-xl font-black tracking-tight flex items-center gap-2">
                  Panel de Alertas Inteligentes & Auditoría IA
                  <span class="text-[10px] px-2.5 py-0.5 rounded-full bg-rose-600 text-white font-mono font-bold">${alertas.length} ACTIVAS</span>
                </h2>
                <p class="text-xs text-slate-400">Detección de animales improductivos, días abiertos excesivos y vacas próximas al secado.</p>
              </div>
            </div>

            <!-- FILTROS POR SEVERIDAD -->
            <div class="flex items-center gap-1.5 bg-slate-800/80 p-1.5 rounded-xl border border-slate-700 text-xs w-full md:w-auto overflow-x-auto">
              <button class="btn-filtro-alerta px-3 py-1.5 rounded-lg font-bold transition whitespace-nowrap ${this.filtroSeveridad === 'todas' ? 'bg-emerald-600 text-white' : 'text-slate-300 hover:text-white'}" data-sev="todas">
                Todas (${alertas.length})
              </button>
              <button class="btn-filtro-alerta px-3 py-1.5 rounded-lg font-bold transition whitespace-nowrap ${this.filtroSeveridad === 'critica' ? 'bg-rose-600 text-white' : 'text-rose-300 hover:text-white'}" data-sev="critica">
                🔴 Críticas (${criticas.length})
              </button>
              <button class="btn-filtro-alerta px-3 py-1.5 rounded-lg font-bold transition whitespace-nowrap ${this.filtroSeveridad === 'advertencia' ? 'bg-amber-600 text-white' : 'text-amber-300 hover:text-white'}" data-sev="advertencia">
                🟡 Advertencias (${advertencias.length})
              </button>
              <button class="btn-filtro-alerta px-3 py-1.5 rounded-lg font-bold transition whitespace-nowrap ${this.filtroSeveridad === 'sanidad_preventiva' ? 'bg-sky-600 text-white' : 'text-sky-300 hover:text-white'}" data-sev="sanidad_preventiva">
                🔵 Secado 7 Meses (${sanidad.length})
              </button>
            </div>
          </div>

          <!-- RESUMEN DE LOS 4 PILARES ZOOTÉCNICOS REQUERIDOS -->
          <div class="grid grid-cols-2 lg:grid-cols-4 gap-3 mt-5 pt-4 border-t border-slate-800 text-xs">
            <div class="bg-slate-900/80 p-3 rounded-xl border border-slate-800">
              <span class="text-slate-400 block text-[10px] uppercase font-bold">1. Crecimiento (GDP &lt; 300g/d)</span>
              <span class="text-xl font-black text-rose-400">
                ${alertas.filter((a) => a.tipo === 'crecimiento_bajo_gdp').length} <span class="text-xs text-slate-400 font-normal">animales</span>
              </span>
            </div>
            <div class="bg-slate-900/80 p-3 rounded-xl border border-slate-800">
              <span class="text-slate-400 block text-[10px] uppercase font-bold">2. Vacas Vacías (&gt; 200 Días)</span>
              <span class="text-xl font-black text-rose-400">
                ${alertas.filter((a) => a.tipo === 'vaca_vacia_dias_abiertos').length} <span class="text-xs text-slate-400 font-normal">vientres</span>
              </span>
            </div>
            <div class="bg-slate-900/80 p-3 rounded-xl border border-slate-800">
              <span class="text-slate-400 block text-[10px] uppercase font-bold">3. Novillas Vacías (&gt; 36 Meses)</span>
              <span class="text-xl font-black text-amber-400">
                ${alertas.filter((a) => a.tipo === 'novilla_vacia_edad').length} <span class="text-xs text-slate-400 font-normal">novillas</span>
              </span>
            </div>
            <div class="bg-slate-900/80 p-3 rounded-xl border border-slate-800">
              <span class="text-slate-400 block text-[10px] uppercase font-bold">4. Secado Gestación (~7 Meses)</span>
              <span class="text-xl font-black text-sky-400">
                ${alertas.filter((a) => a.tipo === 'secado_7_meses').length} <span class="text-xs text-slate-400 font-normal">vacas</span>
              </span>
            </div>
          </div>
        </div>

        <!-- LISTA DE TARJETAS DE ALERTA -->
        <div class="space-y-3">
          ${mostradas.length > 0 ? mostradas.map((a) => this.renderTarjeta(a)).join('') : `
            <div class="bg-white p-12 rounded-2xl border border-slate-200 text-center shadow-sm">
              <div class="w-16 h-16 mx-auto mb-3 rounded-2xl bg-emerald-100 text-emerald-700 flex items-center justify-center text-3xl">
                ✨
              </div>
              <h3 class="text-base font-black text-slate-800">Sin Alertas en esta Categoría</h3>
              <p class="text-xs text-slate-500 mt-1 max-w-md mx-auto">Los animales cumplen los estándares zootécnicos establecidos.</p>
            </div>
          `}
        </div>
      </div>
    `;

    this.attachEvents();
  }

  renderTarjeta(a) {
    let badge = '';
    let border = 'border-slate-200';
    let bgHeader = 'bg-slate-50';

    if (a.severidad === 'critica') {
      badge = '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase bg-rose-100 text-rose-800 border border-rose-200">Crítica</span>';
      border = 'border-rose-200';
      bgHeader = 'bg-rose-50/50';
    } else if (a.severidad === 'advertencia') {
      badge = '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase bg-amber-100 text-amber-800 border border-amber-200">Advertencia</span>';
      border = 'border-amber-200';
      bgHeader = 'bg-amber-50/50';
    } else {
      badge = '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase bg-sky-100 text-sky-800 border border-sky-200">Preventiva</span>';
      border = 'border-sky-200';
      bgHeader = 'bg-sky-50/50';
    }

    return `
      <div class="bg-white rounded-2xl border ${border} shadow-md hover:shadow-lg transition overflow-hidden">
        <div class="${bgHeader} p-4 border-b border-slate-100 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2">
          <div class="flex items-center gap-3">
            <span class="font-mono font-black text-slate-900 bg-white px-3 py-1.5 rounded-xl border border-slate-200 text-sm shadow-sm">
              Tag: ${a.tag}
            </span>
            <div>
              <div class="flex items-center gap-2">
                <span class="font-bold text-slate-800 text-sm">${a.nombre}</span>
                <span class="text-xs text-slate-400">• ${a.categoria}</span>
                <span class="text-xs text-slate-400">• ${a.lote}</span>
              </div>
              <h4 class="font-black text-slate-900 text-sm mt-0.5">${a.titulo}</h4>
            </div>
          </div>
          <div>${badge}</div>
        </div>

        <div class="p-4 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div class="space-y-1.5 max-w-2xl">
            <p class="text-xs text-slate-600 leading-relaxed">${a.mensaje}</p>
            <div class="flex flex-wrap items-center gap-2 text-xs pt-1">
              <span class="bg-slate-100 px-2 py-0.5 rounded font-mono text-slate-700 font-bold">Detectado: <strong>${a.valorMedido}</strong></span>
              <span class="bg-slate-100 px-2 py-0.5 rounded font-mono text-slate-700 font-bold">Meta: <strong>${a.valorLimite}</strong></span>
              <span class="text-emerald-700 font-medium">💡 ${a.accionRecomendada}</span>
            </div>
          </div>

          <div class="flex items-center gap-2 w-full md:w-auto justify-end border-t md:border-t-0 pt-3 md:pt-0">
            <button class="btn-resolver-alerta px-3.5 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-xl text-xs border border-slate-200 transition" data-id="${a.id}">
              ✓ Marcar Resuelta
            </button>
            <button class="btn-accion-directa px-4 py-2 bg-slate-900 hover:bg-slate-800 text-white font-bold rounded-xl text-xs shadow transition active:scale-95" data-animal="${a.animalId}" data-tipo="${a.tipo}">
              ⚡ Tomar Acción
            </button>
          </div>
        </div>
      </div>
    `;
  }

  attachEvents() {
    this.container.querySelectorAll('.btn-filtro-alerta').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        this.filtroSeveridad = e.currentTarget.getAttribute('data-sev');
        this.render();
      });
    });

    this.container.querySelectorAll('.btn-resolver-alerta').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        this.resolverAlerta(e.currentTarget.getAttribute('data-id'));
      });
    });

    this.container.querySelectorAll('.btn-accion-directa').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const animalId = e.currentTarget.getAttribute('data-animal');
        const tipo = e.currentTarget.getAttribute('data-tipo');
        if (this.onAccionZootecnica) {
          this.onAccionZootecnica({ animalId, tipo });
        }
      });
    });
  }
}


// ============================================================================
// ARCHIVO: frontend/src/components/TablaDinamica.js
// ============================================================================
/**
 * GANADERO AD - TABLA DINÁMICA DE ANÁLISIS ZOOTÉCNICO ANIMAL POR ANIMAL
 * Análisis individualizado ejemplar por ejemplar:
 * Muestra explícitamente y destaca de forma prominente el dato/métrica por el cual se está ordenando
 * (GDP, Leche, Días Abiertos, Peso Corporal, Días de Preñez o IEP) para referencia y análisis comparativo.
 */




class TablaDinamica {
  constructor({ containerId, getAnimales, onVerFicha }) {
    this.container = typeof document !== 'undefined' && containerId ? document.getElementById(containerId) : null;
    this.getAnimales = getAnimales;
    this.onVerFicha = onVerFicha;
    this.filtroEspecie = 'todas'; // 'todas' | 'bovino' | 'bufalino'
    this.filtroRepro = 'todos';
    this.filtroOrden = 'gdp_desc'; // 'gdp_desc' | 'leche_desc' | 'abiertos_desc' | 'peso_desc' | 'prened_desc' | 'iep_desc'
    this.busqueda = '';
  }

  init() {
    this.render();
  }

  obtenerMetaDatoOrden(animal, criterio) {
    const fParto = animal.fechaUltimoParto || animal.ultimoParto;
    const especie = animal.especie || 'bovino';
    const diasAbiertos = calcularDiasAbiertos(fParto, animal.estadoReproductivo);
    const iep = calcularIEP(diasAbiertos, especie);
    const gdp = animal.gdpPromedioGDia !== undefined ? animal.gdpPromedioGDia : (animal.gdpActual || null);
    const leche = animal.promedioLecheDiariaL !== undefined ? animal.promedioLecheDiariaL : (animal.produccionLecheDiaria || 0);
    const peso = animal.ultimoPesoKg || animal.pesoActual || 0;
    const estaPrenada = (animal.estadoReproductivo || '').toLowerCase().includes('prenad') || (animal.estadoReproductivo || '').toLowerCase().includes('preñad');
    const diasG = estaPrenada ? parseInt(animal.diasGestacionActual || animal.diasGestacion || 0) : 0;

    switch (criterio) {
      case 'gdp_desc':
        return {
          criterio: 'gdp_desc',
          tituloColumna: 'Ganancia Diaria (GDP)',
          icono: '⚖️',
          valorNumerico: gdp !== null ? gdp : -9999,
          valorTexto: gdp !== null ? `${gdp > 0 ? '+' : ''}${gdp} g/día` : 'No registrado',
          subtexto: gdp !== null ? (gdp >= 600 ? 'Óptima' : (gdp < 300 ? 'Alerta Crítica' : 'Moderada')) : '-',
          colorBadge: gdp >= 600 ? 'bg-emerald-100 text-emerald-900 border-emerald-300' : (gdp < 300 ? 'bg-rose-100 text-rose-900 border-rose-300 font-black' : 'bg-amber-100 text-amber-900 border-amber-300')
        };

      case 'leche_desc':
        return {
          criterio: 'leche_desc',
          tituloColumna: 'Producción Lechera',
          icono: '🥛',
          valorNumerico: leche || 0,
          valorTexto: leche > 0 ? `${parseFloat(leche).toFixed(1)} L/día` : '0.0 L/día',
          subtexto: leche > 0 ? `~${Math.round(leche * 30)} L/mes` : 'Sin ordeño',
          colorBadge: leche >= 12 ? 'bg-emerald-100 text-emerald-900 border-emerald-300 font-black' : (leche > 5 ? 'bg-blue-100 text-blue-900 border-blue-300' : 'bg-slate-100 text-slate-700 border-slate-300')
        };

      case 'abiertos_desc':
        return {
          criterio: 'abiertos_desc',
          tituloColumna: 'Días Abiertos',
          icono: '⏳',
          valorNumerico: diasAbiertos || 0,
          valorTexto: diasAbiertos > 0 ? `${diasAbiertos} días abiertos` : (estaPrenada ? '0 d (Preñada)' : '0 días'),
          subtexto: diasAbiertos > 200 ? '🔴 Alerta Vacía Crítica' : (diasAbiertos > 120 ? '🟡 En Seguimiento' : '🟢 En Rango Normal'),
          colorBadge: diasAbiertos > 200 ? 'bg-rose-100 text-rose-900 border-rose-300 font-black' : (diasAbiertos > 120 ? 'bg-amber-100 text-amber-900 border-amber-300' : 'bg-slate-100 text-slate-700 border-slate-300')
        };

      case 'peso_desc':
        return {
          criterio: 'peso_desc',
          tituloColumna: 'Peso Corporal Actual',
          icono: '🏋️',
          valorNumerico: peso || 0,
          valorTexto: peso > 0 ? `${peso} kg` : 'Sin pesaje',
          subtexto: animal.categoria || 'Ejemplar',
          colorBadge: 'bg-emerald-100 text-emerald-900 border-emerald-300 font-black'
        };

      case 'prened_desc':
        return {
          criterio: 'prened_desc',
          tituloColumna: 'Días de Preñez',
          icono: '🟢',
          valorNumerico: diasG,
          valorTexto: estaPrenada ? `${diasG} días de gestación` : '0 días (Vacía / No aplica)',
          subtexto: estaPrenada ? `~${(diasG / 30.4).toFixed(1)} meses` : 'No gestante',
          colorBadge: estaPrenada ? (diasG >= 210 ? 'bg-purple-100 text-purple-900 border-purple-300 font-black' : 'bg-emerald-100 text-emerald-900 border-emerald-300') : 'bg-slate-100 text-slate-600 border-slate-200'
        };

      case 'iep_desc':
        return {
          criterio: 'iep_desc',
          tituloColumna: 'IEP Proyectado',
          icono: '📅',
          valorNumerico: fParto ? iep.dias : 0,
          valorTexto: fParto ? `${iep.dias} días (${iep.meses} m)` : 'Primeriza / Sin parto',
          subtexto: fParto ? `Último: ${fParto}` : 'Sin partos previos',
          colorBadge: fParto && iep.dias > 450 ? 'bg-rose-100 text-rose-900 border-rose-300' : 'bg-blue-100 text-blue-900 border-blue-300'
        };

      default:
        return {
          criterio: 'gdp_desc',
          tituloColumna: 'Ganancia Diaria (GDP)',
          icono: '⚖️',
          valorNumerico: gdp !== null ? gdp : 0,
          valorTexto: `${gdp || 0} g/d`,
          subtexto: '',
          colorBadge: 'bg-slate-100 text-slate-800'
        };
    }
  }

  render() {
    if (!this.container) return;

    let animales = (this.getAnimales ? this.getAnimales() : []).filter(
      (a) => a.estadoVida === 'activo' || a.estado === 'activo'
    );

    // Filtro especie
    if (this.filtroEspecie !== 'todas') {
      animales = animales.filter((a) => (a.especie || 'bovino') === this.filtroEspecie);
    }

    // Filtro reproductivo
    if (this.filtroRepro !== 'todos') {
      animales = animales.filter((a) => (a.estadoReproductivo || '').toLowerCase().includes(this.filtroRepro));
    }

    // Búsqueda por número/tag o nombre
    if (this.busqueda.trim().length > 0) {
      const q = this.busqueda.trim().toLowerCase();
      const qDigits = q.replace(/\D/g, '');
      animales = animales.filter((a) => {
        const tag = (a.identificacionTag || a.numero || '').toLowerCase();
        const tagDigits = tag.replace(/\D/g, '');
        const matchTag = tag.includes(q) || (qDigits.length > 0 && tagDigits.includes(qDigits));
        const matchNombre = (a.nombreAlias || a.nombre || '').toLowerCase().includes(q);
        const matchRaza = (a.raza || '').toLowerCase().includes(q);
        return matchTag || matchNombre || matchRaza;
      });
    }

    // Ordenamiento animal por animal según el criterio seleccionado
    animales.sort((a, b) => {
      const metaA = this.obtenerMetaDatoOrden(a, this.filtroOrden);
      const metaB = this.obtenerMetaDatoOrden(b, this.filtroOrden);
      return metaB.valorNumerico - metaA.valorNumerico;
    });

    // Calcular estadísticas globales para el KPI banner del criterio activo
    const valoresValidos = animales
      .map((a) => this.obtenerMetaDatoOrden(a, this.filtroOrden).valorNumerico)
      .filter((v) => v !== -9999 && v > 0);

    const maxVal = valoresValidos.length > 0 ? Math.max(...valoresValidos) : 0;
    const minVal = valoresValidos.length > 0 ? Math.min(...valoresValidos) : 0;
    const avgVal = valoresValidos.length > 0 ? Math.round(valoresValidos.reduce((acc, x) => acc + x, 0) / valoresValidos.length) : 0;

    const infoCriterio = this.obtenerMetaDatoOrden({}, this.filtroOrden);

    this.container.innerHTML = `
      <div class="bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden">
        <!-- HEADER DEL ANÁLISIS ANIMAL X ANIMAL -->
        <div class="bg-gradient-to-r from-slate-950 via-slate-900 to-slate-950 text-white p-5 space-y-4">
          <div class="flex flex-col md:flex-row justify-between items-start md:items-center gap-3">
            <div>
              <h3 class="text-base sm:text-lg font-black tracking-tight flex items-center gap-2">
                <span>🔄</span> Análisis Zootécnico Dinámico: Animal por Animal
                <span class="text-[10px] uppercase font-mono px-2 py-0.5 rounded bg-emerald-500/20 text-emerald-300 border border-emerald-400/30">Individualizado</span>
              </h3>
              <p class="text-xs text-slate-400">Comparativa ejemplar por ejemplar con visualización explícita del dato/métrica de ordenamiento para análisis zootécnico.</p>
            </div>

            <!-- CONTADOR DE REGISTROS -->
            <div id="contador-ejemplares-dinamica" class="text-xs font-mono font-bold bg-slate-800 px-3 py-1.5 rounded-xl border border-slate-700 text-emerald-300">
              ${animales.length} Ejemplares Analizados
            </div>
          </div>

          <!-- CONTROLES Y FILTROS EN TIEMPO REAL -->
          <div class="grid grid-cols-1 sm:grid-cols-4 gap-3 pt-3 border-t border-slate-800 text-xs">
            <div>
              <label class="block font-bold text-slate-400 uppercase text-[10px] mb-1">Buscar por Tag / Arete:</label>
              <input type="text" id="input-filtro-tag" value="${this.busqueda}" placeholder="Ej. BV-401, 102..." class="w-full px-3 py-2 bg-slate-800 border border-slate-700 rounded-xl text-white font-mono font-bold outline-none focus:border-emerald-500" autocomplete="off">
            </div>

            <div>
              <label class="block font-bold text-slate-400 uppercase text-[10px] mb-1">Especie:</label>
              <select id="select-filtro-especie" class="w-full px-3 py-2 bg-slate-800 border border-slate-700 rounded-xl text-white font-bold outline-none cursor-pointer">
                <option value="todas" ${this.filtroEspecie === 'todas' ? 'selected' : ''}>Todas las Especies</option>
                <option value="bovino" ${this.filtroEspecie === 'bovino' ? 'selected' : ''}>🐂 Vacuno (Bovino)</option>
                <option value="bufalino" ${this.filtroEspecie === 'bufalino' ? 'selected' : ''}>🦬 Bufalino (Búfalos)</option>
              </select>
            </div>

            <div>
              <label class="block font-bold text-slate-400 uppercase text-[10px] mb-1">Estado Reproductivo:</label>
              <select id="select-filtro-repro" class="w-full px-3 py-2 bg-slate-800 border border-slate-700 rounded-xl text-white font-bold outline-none cursor-pointer">
                <option value="todos" ${this.filtroRepro === 'todos' ? 'selected' : ''}>Todos los Estados</option>
                <option value="preñad" ${this.filtroRepro === 'preñad' ? 'selected' : ''}>🟢 Preñadas (Gestantes)</option>
                <option value="vacia" ${this.filtroRepro === 'vacia' ? 'selected' : ''}>🔴 Vacías (Abiertas)</option>
              </select>
            </div>

            <div>
              <label class="block font-bold text-emerald-400 uppercase text-[10px] mb-1 flex items-center gap-1">
                <span>🎯</span> Ordenar Por (Métrica Principal):
              </label>
              <select id="select-filtro-orden" class="w-full px-3 py-2 bg-emerald-950 border-2 border-emerald-500 rounded-xl text-emerald-200 font-black outline-none cursor-pointer">
                <option value="gdp_desc" ${this.filtroOrden === 'gdp_desc' ? 'selected' : ''}>⚖️ Ganancia Diaria (GDP Mayor a Menor)</option>
                <option value="leche_desc" ${this.filtroOrden === 'leche_desc' ? 'selected' : ''}>🥛 Producción de Leche (Mayor a Menor)</option>
                <option value="abiertos_desc" ${this.filtroOrden === 'abiertos_desc' ? 'selected' : ''}>⏳ Días Abiertos (Mayor a Menor - Críticos)</option>
                <option value="peso_desc" ${this.filtroOrden === 'peso_desc' ? 'selected' : ''}>🏋️ Peso Corporal Actual (Mayor a Menor)</option>
                <option value="prened_desc" ${this.filtroOrden === 'prened_desc' ? 'selected' : ''}>🟢 Días de Preñez (Mayor a Menor)</option>
                <option value="iep_desc" ${this.filtroOrden === 'iep_desc' ? 'selected' : ''}>📅 IEP Proyectado (Mayor a Menor)</option>
              </select>
            </div>
          </div>
        </div>

        <!-- BANNER DE RESUMEN DEL CRITERIO ACTIVO DE ORDEN -->
        <div class="bg-gradient-to-r from-emerald-900 via-teal-900 to-slate-900 text-white px-5 py-3 border-b border-emerald-800/80 flex flex-wrap items-center justify-between gap-3 text-xs">
          <div class="flex items-center gap-2">
            <span class="text-xl">${infoCriterio.icono}</span>
            <div>
              <span class="text-[10px] uppercase font-bold text-emerald-300 tracking-wider">Criterio de Ordenamiento y Análisis Activo:</span>
              <div class="font-black text-white text-sm flex items-center gap-2">
                <span>${infoCriterio.tituloColumna}</span>
                <span class="px-2 py-0.2 rounded bg-emerald-500/30 text-emerald-200 border border-emerald-400/40 text-[10px] font-mono">Orden Descendente ⬇️</span>
              </div>
            </div>
          </div>

          <div class="flex items-center gap-4 text-xs font-mono">
            <div class="bg-black/30 px-3 py-1 rounded-xl border border-white/10">
              <span class="text-[9px] uppercase text-emerald-300 block">Valor Máximo</span>
              <strong class="text-emerald-400">${maxVal > 0 ? `${maxVal}` : '-'}</strong>
            </div>
            <div class="bg-black/30 px-3 py-1 rounded-xl border border-white/10">
              <span class="text-[9px] uppercase text-emerald-300 block">Promedio Lote</span>
              <strong class="text-white">${avgVal > 0 ? `${avgVal}` : '-'}</strong>
            </div>
            <div class="bg-black/30 px-3 py-1 rounded-xl border border-white/10">
              <span class="text-[9px] uppercase text-emerald-300 block">Valor Mínimo</span>
              <strong class="text-amber-300">${minVal > 0 ? `${minVal}` : '-'}</strong>
            </div>
          </div>
        </div>

        <!-- TABLA DINÁMICA ANIMAL X ANIMAL CON COLUMNA DE REFERENCIA DESTACADA -->
        <div class="overflow-x-auto max-h-[580px] overflow-y-auto">
          <table class="w-full text-left text-xs border-collapse">
            <thead class="bg-slate-100 uppercase font-black tracking-wider text-slate-700 text-[10px] border-b border-slate-300 sticky top-0 z-10">
              <tr>
                <th class="p-3 w-12 text-center bg-slate-200/80"># Rank</th>
                <th class="p-3 w-28">Arete / Tag</th>
                <th class="p-3 w-28">Especie</th>
                <th class="p-3 w-36">Nombre & Raza</th>
                
                <!-- COLUMNA PRINCIPAL DE ORDENAMIENTO (DESTACADA) -->
                <th class="p-3 w-48 bg-emerald-700 text-white font-black shadow-md border-x border-emerald-600 text-center">
                  <div class="flex items-center justify-center gap-1">
                    <span>${infoCriterio.icono}</span>
                    <span>DATO DE ORDEN: ${infoCriterio.tituloColumna} ⬇️</span>
                  </div>
                </th>

                <th class="p-3 w-36">Categoría & Lote</th>
                <th class="p-3 w-36 cursor-pointer hover:bg-slate-200 transition ${this.filtroOrden === 'prened_desc' ? 'bg-emerald-100 text-emerald-950 font-black' : ''}" data-sort="prened_desc" title="Clic para ordenar por preñez">
                  Repro / Días Preñez ${this.filtroOrden === 'prened_desc' ? '⬇️' : ''}
                </th>
                <th class="p-3 text-right cursor-pointer hover:bg-slate-200 transition ${this.filtroOrden === 'abiertos_desc' ? 'bg-emerald-100 text-emerald-950 font-black' : ''}" data-sort="abiertos_desc" title="Clic para ordenar por días abiertos">
                  Días Abiertos ${this.filtroOrden === 'abiertos_desc' ? '⬇️' : ''}
                </th>
                <th class="p-3 text-right cursor-pointer hover:bg-slate-200 transition ${this.filtroOrden === 'iep_desc' ? 'bg-emerald-100 text-emerald-950 font-black' : ''}" data-sort="iep_desc" title="Clic para ordenar por IEP">
                  IEP Proyectado ${this.filtroOrden === 'iep_desc' ? '⬇️' : ''}
                </th>
                <th class="p-3 text-right cursor-pointer hover:bg-slate-200 transition ${this.filtroOrden === 'peso_desc' ? 'bg-emerald-100 text-emerald-950 font-black' : ''}" data-sort="peso_desc" title="Clic para ordenar por peso">
                  Peso Actual ${this.filtroOrden === 'peso_desc' ? '⬇️' : ''}
                </th>
                <th class="p-3 text-center cursor-pointer hover:bg-slate-200 transition ${this.filtroOrden === 'gdp_desc' ? 'bg-emerald-100 text-emerald-950 font-black' : ''}" data-sort="gdp_desc" title="Clic para ordenar por GDP">
                  GDP Promedio ${this.filtroOrden === 'gdp_desc' ? '⬇️' : ''}
                </th>
                <th class="p-3 text-right cursor-pointer hover:bg-slate-200 transition ${this.filtroOrden === 'leche_desc' ? 'bg-emerald-100 text-emerald-950 font-black' : ''}" data-sort="leche_desc" title="Clic para ordenar por leche">
                  Leche L/d ${this.filtroOrden === 'leche_desc' ? '⬇️' : ''}
                </th>
                <th class="p-3 text-center">Rendimiento</th>
                <th class="p-3 w-16 text-center">Ficha</th>
              </tr>
            </thead>
            <tbody id="tbody-tabla-dinamica" class="divide-y divide-slate-200 font-medium">
              ${animales.length > 0 ? animales.map((a, idx) => this.renderFilaAnimal(a, idx)).join('') : `
                <tr>
                  <td colspan="14" class="p-10 text-center text-slate-400">
                    No se encontraron animales con los filtros especificados.
                  </td>
                </tr>
              `}
            </tbody>
          </table>
        </div>
      </div>
    `;

    this.attachEvents();
  }

  renderFilaAnimal(a, idx) {
    const especie = a.especie || 'bovino';
    const tag = a.identificacionTag || a.numero;
    const fParto = a.fechaUltimoParto || a.ultimoParto;
    const diasAbiertos = calcularDiasAbiertos(fParto, a.estadoReproductivo);
    const iep = calcularIEP(diasAbiertos, especie);
    const gdp = a.gdpPromedioGDia !== undefined ? a.gdpPromedioGDia : (a.gdpActual || null);
    const leche = a.promedioLecheDiariaL !== undefined ? a.promedioLecheDiariaL : (a.produccionLecheDiaria || 0);
    const estaPrenada = (a.estadoReproductivo || '').toLowerCase().includes('prenad') || (a.estadoReproductivo || '').toLowerCase().includes('preñad');
    const diasG = estaPrenada ? (a.diasGestacionActual || a.diasGestacion || 0) : 0;

    // Dato activo de ordenamiento para este animal
    const metaOrden = this.obtenerMetaDatoOrden(a, this.filtroOrden);

    // Medallas para los primeros lugares
    let medalla = `<span class="text-slate-400 font-mono text-xs">#${idx + 1}</span>`;
    if (idx === 0) medalla = `<span class="px-1.5 py-0.5 rounded-full bg-amber-400 text-amber-950 font-black text-xs shadow-sm">🥇 #1</span>`;
    else if (idx === 1) medalla = `<span class="px-1.5 py-0.5 rounded-full bg-slate-300 text-slate-900 font-black text-xs shadow-sm">🥈 #2</span>`;
    else if (idx === 2) medalla = `<span class="px-1.5 py-0.5 rounded-full bg-amber-600/30 text-amber-900 font-black text-xs shadow-sm">🥉 #3</span>`;

    // Clasificación de rendimiento zootécnico individual
    let badgeRendimiento = '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-800">Óptimo</span>';
    if (gdp !== null && gdp < 300) {
      badgeRendimiento = '<span class="px-2 py-0.5 rounded-full text-[10px] font-black bg-rose-100 text-rose-800">Baja GDP</span>';
    } else if (diasAbiertos > 200) {
      badgeRendimiento = '<span class="px-2 py-0.5 rounded-full text-[10px] font-black bg-rose-100 text-rose-800">Días Abiertos</span>';
    } else if (gdp !== null && gdp < 600) {
      badgeRendimiento = '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-800">Regular</span>';
    }

    return `
      <tr class="hover:bg-emerald-50/50 transition">
        <!-- RANK -->
        <td class="p-2.5 text-center bg-slate-50/80">${medalla}</td>

        <!-- ARETE -->
        <td class="p-2.5 font-black font-mono text-slate-900 text-sm">${tag}</td>

        <!-- ESPECIE -->
        <td class="p-2.5">
          <span class="px-2 py-0.5 rounded text-[10px] font-bold ${especie === 'bufalino' ? 'bg-amber-100 text-amber-900' : 'bg-blue-100 text-blue-900'}">
            ${especie === 'bufalino' ? '🦬 Bufalino' : '🐂 Vacuno'}
          </span>
        </td>

        <!-- NOMBRE & RAZA -->
        <td class="p-2.5">
          <div class="font-bold text-slate-800">${a.nombreAlias || a.nombre || 'Sin Alias'}</div>
          <div class="text-[10px] text-slate-500">${a.raza || 'Común'}</div>
        </td>

        <!-- ==================================================================== -->
        <!-- COLUMNA PRINCIPAL DE REFERENCIA Y ANÁLISIS (DATO ORDENADO)           -->
        <!-- ==================================================================== -->
        <td class="p-2.5 text-center bg-emerald-50/70 border-x-2 border-emerald-300">
          <div class="inline-flex flex-col items-center">
            <span class="px-3 py-1 rounded-xl text-xs font-black shadow-sm border ${metaOrden.colorBadge}">
              ${metaOrden.valorTexto}
            </span>
            ${metaOrden.subtexto ? `
              <span class="text-[9px] font-bold text-slate-500 mt-0.5">${metaOrden.subtexto}</span>
            ` : ''}
          </div>
        </td>

        <!-- CATEGORÍA & LOTE -->
        <td class="p-2.5">
          <div class="font-bold text-slate-700 text-[11px]">${a.categoria}</div>
          <span class="text-[10px] text-slate-400 block">📍 ${a.lote}</span>
        </td>

        <!-- REPRO / PREÑEZ -->
        <td class="p-2.5 ${this.filtroOrden === 'prened_desc' ? 'bg-emerald-50 font-bold' : ''}">
          <div class="font-bold ${estaPrenada ? 'text-emerald-700' : 'text-slate-700'}">
            ${a.estadoReproductivo || 'Vacía'}
          </div>
          ${estaPrenada ? `<div class="text-[10px] text-emerald-600 font-black font-mono">${diasG} días de preñez</div>` : ''}
        </td>

        <!-- DÍAS ABIERTOS -->
        <td class="p-2.5 text-right font-mono font-bold ${this.filtroOrden === 'abiertos_desc' ? 'bg-emerald-50' : ''} ${diasAbiertos > 200 ? 'text-rose-600' : 'text-slate-700'}">
          ${diasAbiertos > 0 ? `${diasAbiertos} d` : '-'}
        </td>

        <!-- IEP -->
        <td class="p-2.5 text-right font-mono text-slate-600 ${this.filtroOrden === 'iep_desc' ? 'bg-emerald-50 font-bold' : ''}">
          ${fParto ? `${iep.dias} d` : '-'}
        </td>

        <!-- PESO -->
        <td class="p-2.5 text-right font-mono font-bold text-slate-800 ${this.filtroOrden === 'peso_desc' ? 'bg-emerald-50' : ''}">
          ${a.ultimoPesoKg || a.pesoActual ? `${a.ultimoPesoKg || a.pesoActual} kg` : '-'}
        </td>

        <!-- GDP -->
        <td class="p-2.5 text-center ${this.filtroOrden === 'gdp_desc' ? 'bg-emerald-50' : ''}">
          ${gdp !== null ? `
            <span class="inline-flex items-center gap-0.5 px-2 py-0.5 rounded-full text-xs font-bold ${gdp < 300 ? 'bg-rose-100 text-rose-800 font-black' : (gdp < 600 ? 'bg-amber-100 text-amber-800' : 'bg-emerald-100 text-emerald-800')}">
              ${gdp > 0 ? '+' : ''}${gdp} g/d
            </span>
          ` : '<span class="text-slate-300 text-xs">-</span>'}
        </td>

        <!-- LECHE -->
        <td class="p-2.5 text-right font-mono font-bold text-emerald-800 ${this.filtroOrden === 'leche_desc' ? 'bg-emerald-50' : ''}">
          ${leche > 0 ? `${parseFloat(leche).toFixed(1)} L` : '-'}
        </td>

        <!-- RENDIMIENTO -->
        <td class="p-2.5 text-center">
          ${badgeRendimiento}
        </td>

        <!-- ACCIONES -->
        <td class="p-2.5 text-center">
          <button data-action="ver-ficha-animal" data-id="${a.id}" class="px-2 py-1 bg-slate-900 hover:bg-slate-800 text-white text-[10px] font-bold rounded-lg shadow transition" title="Ver Ficha Técnica">
            🔍
          </button>
        </td>
      </tr>
    `;
  }

  attachEvents() {
    const inTag = this.container.querySelector('#input-filtro-tag');
    if (inTag) {
      conectarAutosuggestAnimales({
        inputElement: inTag,
        getAnimales: () => this.getAnimales ? this.getAnimales() : [],
        theme: 'emerald',
        maxResultados: 8,
        onSeleccionar: (animal) => {
          const tag = animal.identificacionTag || animal.numero;
          inTag.value = tag;
          this.busqueda = tag;
          this.filtrarTabla();
        }
      });

      inTag.addEventListener('input', (e) => {
        this.busqueda = e.target.value;
        this.filtrarTabla();
      });
    }

    const selEsp = this.container.querySelector('#select-filtro-especie');
    if (selEsp) {
      selEsp.addEventListener('change', (e) => {
        this.filtroEspecie = e.target.value;
        this.render();
      });
    }

    const selRep = this.container.querySelector('#select-filtro-repro');
    if (selRep) {
      selRep.addEventListener('change', (e) => {
        this.filtroRepro = e.target.value;
        this.render();
      });
    }

    const selOrd = this.container.querySelector('#select-filtro-orden');
    if (selOrd) {
      selOrd.addEventListener('change', (e) => {
        this.filtroOrden = e.target.value;
        this.render();
      });
    }

    // Cabeceras clickeables para ordenar directamente
    this.container.querySelectorAll('th[data-sort]').forEach((th) => {
      th.addEventListener('click', (e) => {
        const criterio = e.currentTarget.getAttribute('data-sort');
        if (criterio) {
          this.filtroOrden = criterio;
          this.render();
        }
      });
    });

    this.enlazarEventosTabla();
  }

  enlazarEventosTabla() {
    if (!this.container) return;
    this.container.querySelectorAll('button[data-action="ver-ficha-animal"]').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const id = e.currentTarget.getAttribute('data-id');
        if (this.onVerFicha) this.onVerFicha(id);
      });
    });
  }

  filtrarTabla() {
    if (!this.container) return;

    let animales = (this.getAnimales ? this.getAnimales() : []).filter(
      (a) => a.estadoVida === 'activo' || a.estado === 'activo'
    );

    if (this.filtroEspecie !== 'todas') {
      animales = animales.filter((a) => (a.especie || 'bovino') === this.filtroEspecie);
    }

    if (this.filtroRepro !== 'todos') {
      animales = animales.filter((a) => (a.estadoReproductivo || '').toLowerCase().includes(this.filtroRepro));
    }

    if (this.busqueda.trim().length > 0) {
      const q = this.busqueda.trim().toLowerCase();
      const qDigits = q.replace(/\D/g, '');
      animales = animales.filter((a) => {
        const tag = (a.identificacionTag || a.numero || '').toLowerCase();
        const tagDigits = tag.replace(/\D/g, '');
        const matchTag = tag.includes(q) || (qDigits.length > 0 && tagDigits.includes(qDigits));
        const matchNombre = (a.nombreAlias || a.nombre || '').toLowerCase().includes(q);
        const matchRaza = (a.raza || '').toLowerCase().includes(q);
        return matchTag || matchNombre || matchRaza;
      });
    }

    animales.sort((a, b) => {
      const metaA = this.obtenerMetaDatoOrden(a, this.filtroOrden);
      const metaB = this.obtenerMetaDatoOrden(b, this.filtroOrden);
      return metaB.valorNumerico - metaA.valorNumerico;
    });

    const contador = this.container.querySelector('#contador-ejemplares-dinamica');
    if (contador) {
      contador.textContent = `${animales.length} Ejemplares Analizados`;
    }

    const tbody = this.container.querySelector('#tbody-tabla-dinamica');
    if (tbody) {
      if (animales.length > 0) {
        tbody.innerHTML = animales.map((a, idx) => this.renderFilaAnimal(a, idx)).join('');
      } else {
        tbody.innerHTML = `
          <tr>
            <td colspan="14" class="p-10 text-center text-slate-400">
              No se encontraron animales con los filtros especificados.
            </td>
          </tr>
        `;
      }
      this.enlazarEventosTabla();
    }
  }
}



// ============================================================================
// ARCHIVO: frontend/src/components/DashboardGrafico.js
// ============================================================================
/**
 * GANADERO AD - DASHBOARD GRÁFICO E INFORMES INTERACTIVOS (100% OFFLINE SVG)
 * Gráficos de Fertilidad, Finanzas (Costos vs Ingresos), Curva de Lactancia e Inventario por Categorías.
 */



class DashboardGrafico {
  constructor({ containerId, getFincaActiva, getFincasPermitidas, getAnimales, getCostosFijos, getInversiones, onCambiarFinca, getVentasGanado }) {
    this.container = document.getElementById(containerId);
    this.getFincaActiva = getFincaActiva;
    this.getFincasPermitidas = getFincasPermitidas;
    this.getAnimales = getAnimales;
    this.getCostosFijos = getCostosFijos;
    this.getInversiones = getInversiones;
    this.onCambiarFinca = onCambiarFinca;
    this.getVentasGanado = getVentasGanado;
  }

  init() {
    this.render();
  }

  render() {
    if (!this.container) return;

    const finca = this.getFincaActiva ? this.getFincaActiva() : null;
    const fincasPermitidas = this.getFincasPermitidas ? this.getFincasPermitidas() : [];
    const animales = (this.getAnimales ? this.getAnimales() : []).filter(
      (a) => a.estadoVida === 'activo' || a.estado === 'activo'
    );
    const costos = this.getCostosFijos ? this.getCostosFijos() : {};
    const inversiones = this.getInversiones ? this.getInversiones() : [];
    const ventasGanado = this.getVentasGanado ? this.getVentasGanado() : 0;

    // 1. Fertilidad
    const vientres = animales.filter((a) => a.sexo === 'hembra' && !(a.categoria || '').toLowerCase().includes('cria'));
    const prenadas = vientres.filter((a) => (a.estadoReproductivo || '').toLowerCase().includes('prenad') || (a.estadoReproductivo || '').toLowerCase().includes('preñad')).length;
    const vacias = vientres.filter((a) => (a.estadoReproductivo || '').toLowerCase().includes('vacia') || (a.estadoReproductivo || '').toLowerCase().includes('vacía')).length;
    const servidas = Math.max(0, vientres.length - prenadas - vacias);
    const tasaPrenez = vientres.length > 0 ? ((prenadas / vientres.length) * 100).toFixed(1) : 0;

    // 2. Finanzas Dinámicas Basadas en los Animales Reales de esta Finca
    const vacasOrdeno = animales.filter((a) => 
      (a.categoria || '').toLowerCase().includes('ordeño') || 
      (a.categoria || '').toLowerCase().includes('lact') ||
      (parseFloat(a.promedioLecheDiariaL) || 0) > 0
    );
    let litrosLecheMensuales = vacasOrdeno.reduce((sum, a) => sum + (parseFloat(a.promedioLecheDiariaL) || 0), 0) * 30;
    if (litrosLecheMensuales === 0 && vacasOrdeno.length > 0) {
      litrosLecheMensuales = vacasOrdeno.length * 12 * 30;
    }

    const animalesCarne = animales.filter((a) => 
      (a.categoria || '').toLowerCase().includes('ceba') || 
      (a.categoria || '').toLowerCase().includes('levante') || 
      (a.categoria || '').toLowerCase().includes('novillo') || 
      (a.categoria || '').toLowerCase().includes('macho')
    );
    let kilosCarneMensuales = animalesCarne.reduce((sum, a) => {
      const gdpGramos = parseFloat(a.gdpPromedioGDia) || 450;
      return sum + (gdpGramos / 1000) * 30;
    }, 0);
    if (kilosCarneMensuales === 0 && animales.length > 0 && vacasOrdeno.length === 0) {
      kilosCarneMensuales = animales.length * 15;
    }

    const balance = computarRendimientoFinanciero({
      finca,
      costosFijos: costos,
      inversiones,
      litrosLecheMensuales: Math.round(litrosLecheMensuales),
      kilosCarneMensuales: Math.round(kilosCarneMensuales),
      ingresosVentasAnimales: ventasGanado
    });

    // 3. Distribución Categorías
    const categorias = {};
    animales.forEach((a) => {
      const c = a.categoria || 'Sin Categoría';
      categorias[c] = (categorias[c] || 0) + 1;
    });

    this.container.innerHTML = `
      <div class="space-y-6">
        <!-- ENCABEZADO Y SELECTOR DE PREDIO -->
        <div class="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 bg-white p-4 sm:p-5 rounded-3xl border border-slate-200 shadow-sm">
          <div class="flex items-center gap-3.5">
            <div class="w-12 h-12 rounded-2xl bg-emerald-50 text-emerald-700 flex items-center justify-center text-2xl border border-emerald-200 shadow-inner">
              🏡
            </div>
            <div>
              <div class="flex items-center gap-2 flex-wrap">
                <h3 class="font-black text-slate-900 text-base sm:text-lg tracking-tight">${finca?.nombre || 'Predio Ganadero'}</h3>
                <span class="px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-800 text-[10px] font-mono font-black uppercase">Finca Activa</span>
              </div>
              <div class="text-xs text-slate-500 font-mono mt-0.5">
                Código: <strong>${finca?.codigo || finca?.id || 'S/C'}</strong> • Área: <strong>${finca?.areaHa || 0} Ha</strong> • 📍 ${finca?.ubicacion || 'Colombia'}
              </div>
            </div>
          </div>

          ${fincasPermitidas.length > 1 ? `
            <div class="flex items-center gap-2 w-full sm:w-auto shrink-0 bg-slate-50 p-2 rounded-2xl border border-slate-200">
              <span class="text-xs font-bold text-slate-600 pl-1 whitespace-nowrap">Predio:</span>
              <select id="select-finca-dashboard" class="w-full sm:w-56 px-3 py-1.5 text-xs font-black rounded-xl border border-slate-300 bg-white shadow-sm outline-none cursor-pointer focus:border-emerald-600">
                ${fincasPermitidas.map((f) => `<option value="${f.id}" ${f.id === finca?.id ? 'selected' : ''}>${f.nombre} (${f.areaHa || 0} Ha)</option>`).join('')}
              </select>
            </div>
          ` : ''}
        </div>
        <!-- KPIS PRINCIPALES -->
        <div class="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
          <div class="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between">
            <div>
              <span class="text-[11px] font-bold text-slate-500 uppercase">Tasa de Preñez</span>
              <div class="text-2xl font-black text-emerald-800 mt-1">${tasaPrenez}%</div>
              <span class="text-[10px] text-emerald-600 font-bold">${prenadas} de ${vientres.length} vientres</span>
            </div>
            <div class="w-11 h-11 rounded-xl bg-emerald-50 text-emerald-700 flex items-center justify-center text-xl">
              🧬
            </div>
          </div>

          <div class="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between">
            <div>
              <span class="text-[11px] font-bold text-slate-500 uppercase">Total Hato Activo</span>
              <div class="text-2xl font-black text-slate-900 mt-1">${animales.length}</div>
              <span class="text-[10px] text-slate-500 font-medium">${finca?.nombre || 'Predio activo'}</span>
            </div>
            <div class="w-11 h-11 rounded-xl bg-slate-100 text-slate-700 flex items-center justify-center text-xl">
              🐂
            </div>
          </div>

          <div class="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between">
            <div>
              <span class="text-[11px] font-bold text-slate-500 uppercase">Margen Neto Mes</span>
              <div class="text-2xl font-black ${balance.indicadores.margenNeto >= 0 ? 'text-emerald-700' : 'text-rose-700'} mt-1">
                $${(balance.indicadores.margenNeto / 1000000).toFixed(2)}M
              </div>
              <span class="text-[10px] font-bold ${balance.indicadores.roiPct >= 0 ? 'text-emerald-600' : 'text-rose-600'}">ROI: ${balance.indicadores.roiPct}%</span>
            </div>
            <div class="w-11 h-11 rounded-xl bg-emerald-50 text-emerald-700 flex items-center justify-center text-xl">
              💵
            </div>
          </div>

          <div class="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between">
            <div>
              <span class="text-[11px] font-bold text-slate-500 uppercase">Amortización Diferida</span>
              <div class="text-2xl font-black text-purple-700 mt-1">
                $${(balance.costos.cuotaInversionesDiferidas / 1000).toFixed(0)}k
              </div>
              <span class="text-[10px] text-purple-600 font-medium">Cuota mensual diferida</span>
            </div>
            <div class="w-11 h-11 rounded-xl bg-purple-50 text-purple-700 flex items-center justify-center text-xl">
              🏗️
            </div>
          </div>
        </div>

        <!-- FILA DE GRÁFICOS: FERTILIDAD & FINANZAS -->
        <div class="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <!-- GRÁFICO 1: DONUT FERTILIDAD -->
          <div class="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col justify-between">
            <div class="flex justify-between items-center mb-4">
              <div>
                <h3 class="font-black text-slate-900 text-sm flex items-center gap-2">
                  <span>🧬</span> Dinámica Reproductiva y Fertilidad
                </h3>
                <p class="text-xs text-slate-500">Distribución de vientres gestantes, vacíos y servidos.</p>
              </div>
              <span class="text-xs font-mono font-bold px-2 py-0.5 rounded bg-emerald-50 text-emerald-800 border border-emerald-200">
                ${tasaPrenez}% Preñez
              </span>
            </div>

            <div class="flex flex-col sm:flex-row items-center justify-around gap-4 py-2">
              <div class="relative w-44 h-44">
                ${this.renderDonut(prenadas, vacias, servidas)}
                <div class="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                  <span class="text-2xl font-black text-slate-900">${tasaPrenez}%</span>
                  <span class="text-[10px] uppercase font-bold text-slate-400">Preñadas</span>
                </div>
              </div>

              <div class="space-y-2 text-xs w-full sm:w-auto">
                <div class="flex items-center justify-between sm:justify-start gap-3 p-2 rounded-xl bg-emerald-50/60 border border-emerald-100">
                  <span class="flex items-center gap-2 font-bold text-emerald-900">
                    <span class="w-3 h-3 rounded-full bg-emerald-600 inline-block"></span> Preñadas
                  </span>
                  <span class="font-mono font-bold text-emerald-800">${prenadas} (${tasaPrenez}%)</span>
                </div>
                <div class="flex items-center justify-between sm:justify-start gap-3 p-2 rounded-xl bg-rose-50/60 border border-rose-100">
                  <span class="flex items-center gap-2 font-bold text-rose-900">
                    <span class="w-3 h-3 rounded-full bg-rose-500 inline-block"></span> Vacías (Abiertas)
                  </span>
                  <span class="font-mono font-bold text-rose-800">${vacias}</span>
                </div>
                <div class="flex items-center justify-between sm:justify-start gap-3 p-2 rounded-xl bg-amber-50/60 border border-amber-100">
                  <span class="flex items-center gap-2 font-bold text-amber-900">
                    <span class="w-3 h-3 rounded-full bg-amber-500 inline-block"></span> Servidas / Sospecha
                  </span>
                  <span class="font-mono font-bold text-amber-800">${servidas}</span>
                </div>
              </div>
            </div>
          </div>

          <!-- GRÁFICO 2: BARRAS FINANCIERAS -->
          <div class="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col justify-between">
            <div class="flex justify-between items-center mb-4">
              <div>
                <h3 class="font-black text-slate-900 text-sm flex items-center gap-2">
                  <span>📈</span> Rendimiento Financiero (Costos vs Ingresos)
                </h3>
                <p class="text-xs text-slate-500">Cruce de costos fijos, cuotas amortizables e ingresos de leche y carne.</p>
              </div>
              <span class="text-xs font-mono font-bold px-2 py-0.5 rounded bg-emerald-50 text-emerald-800 border border-emerald-200">
                Margen: ${balance.indicadores.margenPct}%
              </span>
            </div>

            ${this.renderFinanzasBars(balance)}
          </div>
        </div>

        <!-- FILA DE GRÁFICOS: CURVA DE LACTANCIA & INVENTARIO -->
        <div class="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <div class="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
            <div class="flex justify-between items-center mb-4">
              <div>
                <h3 class="font-black text-slate-900 text-sm flex items-center gap-2">
                  <span>🥛</span> Curva de Lactancia Promedio (Litros vs DEL)
                </h3>
                <p class="text-xs text-slate-500">Comportamiento de producción según días en lactancia.</p>
              </div>
              <span class="text-xs font-bold text-slate-500">Pico: Día 60</span>
            </div>
            ${this.renderCurvaLactancia()}
          </div>

          <div class="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
            <div class="flex justify-between items-center mb-4">
              <div>
                <h3 class="font-black text-slate-900 text-sm flex items-center gap-2">
                  <span>🏷️</span> Estructura Demográfica del Hato
                </h3>
                <p class="text-xs text-slate-500">Distribución por categorías zootécnicas.</p>
              </div>
              <span class="text-xs font-bold text-emerald-800 font-mono">${animales.length} Cabezas</span>
            </div>
            ${this.renderCategorias(categorias, animales.length)}
          </div>
        </div>
      </div>
    `;

    this.attachEvents();
  }

  renderDonut(p, v, s) {
    const total = p + v + s;
    if (total === 0) return '<div class="text-xs text-slate-400">Sin datos</div>';

    const r = 58;
    const c = 2 * Math.PI * r;
    const sp = (p / total) * c;
    const sv = (v / total) * c;
    const ss = (s / total) * c;

    return `
      <svg class="w-44 h-44 transform -rotate-90" viewBox="0 0 160 160">
        <circle cx="80" cy="80" r="${r}" fill="transparent" stroke="#f1f5f9" stroke-width="22" />
        <circle cx="80" cy="80" r="${r}" fill="transparent" stroke="#059669" stroke-width="22" stroke-dasharray="${sp} ${c}" stroke-dashoffset="0" stroke-linecap="round" />
        <circle cx="80" cy="80" r="${r}" fill="transparent" stroke="#f43f5e" stroke-width="22" stroke-dasharray="${sv} ${c}" stroke-dashoffset="-${sp}" />
        <circle cx="80" cy="80" r="${r}" fill="transparent" stroke="#f59e0b" stroke-width="22" stroke-dasharray="${ss} ${c}" stroke-dashoffset="-${sp + sv}" stroke-linecap="round" />
      </svg>
    `;
  }

  renderFinanzasBars(b) {
    const maxVal = Math.max(b.costos.total, b.ingresos.total, 1);
    const hFijos = (b.costos.fijos / maxVal) * 110;
    const hAmort = (b.costos.cuotaInversionesDiferidas / maxVal) * 110;
    const hLeche = (b.ingresos.leche / maxVal) * 110;
    const hCarne = (b.ingresos.carne / maxVal) * 110;
    const hVentas = ((b.ingresos.ventasGanado || 0) / maxVal) * 110;

    return `
      <div class="h-44 flex items-end justify-around gap-2 sm:gap-4 pt-4 px-3 bg-slate-50 rounded-xl border border-slate-100">
        <div class="flex flex-col items-center gap-1 flex-1">
          <span class="text-[10px] font-bold text-slate-700 font-mono">$${(b.costos.fijos / 1000000).toFixed(1)}M</span>
          <div class="w-full max-w-[42px] bg-slate-700 rounded-t-lg transition-all" style="height: ${Math.max(6, hFijos)}px"></div>
          <span class="text-[9px] font-bold text-slate-500 uppercase">Costos Fijos</span>
        </div>
        <div class="flex flex-col items-center gap-1 flex-1">
          <span class="text-[10px] font-bold text-purple-700 font-mono">$${(b.costos.cuotaInversionesDiferidas / 1000).toFixed(0)}k</span>
          <div class="w-full max-w-[42px] bg-purple-600 rounded-t-lg transition-all" style="height: ${Math.max(6, hAmort)}px"></div>
          <span class="text-[9px] font-bold text-purple-600 uppercase">Amortización</span>
        </div>
        <div class="flex flex-col items-center gap-1 flex-1">
          <span class="text-[10px] font-bold text-emerald-700 font-mono">$${(b.ingresos.leche / 1000000).toFixed(1)}M</span>
          <div class="w-full max-w-[42px] bg-emerald-600 rounded-t-lg transition-all" style="height: ${Math.max(6, hLeche)}px"></div>
          <span class="text-[9px] font-bold text-emerald-700 uppercase">Leche</span>
        </div>
        <div class="flex flex-col items-center gap-1 flex-1">
          <span class="text-[10px] font-bold text-teal-700 font-mono">$${(b.ingresos.carne / 1000000).toFixed(1)}M</span>
          <div class="w-full max-w-[42px] bg-teal-500 rounded-t-lg transition-all" style="height: ${Math.max(6, hCarne)}px"></div>
          <span class="text-[9px] font-bold text-teal-700 uppercase">Carne</span>
        </div>
        ${(b.ingresos.ventasGanado || 0) > 0 ? `
        <div class="flex flex-col items-center gap-1 flex-1">
          <span class="text-[10px] font-bold text-amber-700 font-mono">$${(b.ingresos.ventasGanado / 1000000).toFixed(1)}M</span>
          <div class="w-full max-w-[42px] bg-amber-500 rounded-t-lg transition-all" style="height: ${Math.max(6, hVentas)}px"></div>
          <span class="text-[9px] font-bold text-amber-700 uppercase">Ventas</span>
        </div>
        ` : ''}
      </div>
    `;
  }

  renderCurvaLactancia() {
    return `
      <div class="h-44 flex flex-col justify-end bg-slate-50 p-2.5 rounded-xl border border-slate-100">
        <svg viewBox="0 0 380 120" class="w-full h-full">
          <line x1="30" y1="20" x2="360" y2="20" stroke="#e2e8f0" stroke-dasharray="2,2" />
          <line x1="30" y1="60" x2="360" y2="60" stroke="#e2e8f0" stroke-dasharray="2,2" />
          <line x1="30" y1="95" x2="360" y2="95" stroke="#cbd5e1" />
          <text x="24" y="24" font-size="8" fill="#94a3b8" text-anchor="end">18L</text>
          <text x="24" y="64" font-size="8" fill="#94a3b8" text-anchor="end">12L</text>
          <text x="24" y="98" font-size="8" fill="#94a3b8" text-anchor="end">6L</text>
          <path d="M 40 80 C 70 35, 100 20, 130 25 C 180 35, 250 65, 350 90" fill="none" stroke="#059669" stroke-width="3" stroke-linecap="round" />
          <circle cx="115" cy="22" r="4" fill="#f59e0b" stroke="#fff" stroke-width="1.5" />
          <text x="40" y="112" font-size="8" fill="#64748b" text-anchor="middle">Parto</text>
          <text x="115" y="112" font-size="8" fill="#64748b" text-anchor="middle">60 DEL</text>
          <text x="200" y="112" font-size="8" fill="#64748b" text-anchor="middle">150 DEL</text>
          <text x="280" y="112" font-size="8" fill="#64748b" text-anchor="middle">210 DEL (Secado)</text>
          <text x="350" y="112" font-size="8" fill="#64748b" text-anchor="middle">305 DEL</text>
        </svg>
      </div>
    `;
  }

  renderCategorias(catMap, total) {
    const entries = Object.entries(catMap).sort((a, b) => b[1] - a[1]);
    return `
      <div class="space-y-2 py-1">
        ${entries.map(([c, n]) => {
          const pct = total > 0 ? ((n / total) * 100).toFixed(0) : 0;
          return `
            <div>
              <div class="flex justify-between text-xs font-bold text-slate-700 mb-0.5">
                <span>${c}</span>
                <span class="font-mono text-slate-500">${n} (${pct}%)</span>
              </div>
              <div class="w-full h-2 bg-slate-100 rounded-full overflow-hidden">
                <div class="h-full bg-emerald-600 rounded-full" style="width: ${pct}%"></div>
              </div>
            </div>
          `;
        }).join('')}
      </div>
    `;
  }

  attachEvents() {
    if (!this.container) return;
    const sel = this.container.querySelector('#select-finca-dashboard');
    if (sel) {
      sel.addEventListener('change', (e) => {
        if (this.onCambiarFinca) {
          this.onCambiarFinca(e.target.value);
        }
      });
    }
  }
}


