// ============================================================================
/**
 * GANADERO AD - MÓDULO INTEGRAL DE SERVICIOS REPRODUCTIVOS
 * Registro y seguimiento de:
 * 1. Inseminación Artificial (IA / IATF)
 * 2. Transferencia de Embriones (TE / FIV)
 * 3. Servicios con Toro (Monta Natural / Dirigida)
 * Incluye proyecciones zootécnicas de chequeo (ecografía/palpación) y parto.
 */





class ModuloReproduccion {
  constructor({ containerId, getAnimales, getAnimalesBusqueda, getServicios, onRegistrarServicio, onActualizarServicio, onEliminarServicio, onTrasladarAFinca, onReactivarAnimal }) {
    this.container = document.getElementById(containerId);
    this.getAnimales = getAnimales;
    this.getAnimalesBusqueda = getAnimalesBusqueda;
    this.getServicios = getServicios;
    this.onRegistrarServicio = onRegistrarServicio;
    this.onActualizarServicio = onActualizarServicio;
    this.onEliminarServicio = onEliminarServicio;
    this.onTrasladarAFinca = onTrasladarAFinca;
    this.onReactivarAnimal = onReactivarAnimal;

    this.subvistaActiva = 'formulario'; // 'formulario' | 'historial' | 'kpis'
    this.tipoServicioSeleccionado = 'inseminacion_artificial';
    this.filtroTipoHistorial = 'todos';
    this.filtroEstadoHistorial = 'todos';
    this.busquedaHistorial = '';

    this.animalSeleccionado = null;
  }

  init() {
    this.render();
  }

  render() {
    if (!this.container) return;

    const animales = (this.getAnimales ? this.getAnimales() : []).filter(
      (a) => a.estadoVida === 'activo' || a.estado === 'activo'
    );
    const hembras = animales.filter((a) => (a.sexo || '').toLowerCase() === 'hembra');
    const servicios = this.getServicios ? this.getServicios() : [];

    this.container.innerHTML = `
      <div class="space-y-6">
        <!-- CABECERA PRINCIPAL DEL MÓDULO -->
        <div class="bg-gradient-to-r from-slate-950 via-slate-900 to-slate-950 text-white p-5 rounded-3xl shadow-xl border border-slate-800 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div class="flex items-center gap-3.5">
            <div class="w-12 h-12 rounded-2xl bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center text-white text-2xl shadow-lg">
              🧬
            </div>
            <div>
              <h2 class="text-xl font-black tracking-tight flex items-center gap-2">
                <span>Reproducción & Servicios Genéticos</span>
                <span class="text-[10px] uppercase font-mono px-2 py-0.5 rounded bg-indigo-500/20 text-indigo-300 border border-indigo-400/30">IA • TE • Monta</span>
              </h2>
              <p class="text-xs text-slate-400 mt-0.5">Control de inseminaciones artificiales, transferencia de embriones y servicios con toro.</p>
            </div>
          </div>

          <!-- SELECTOR DE SUBPESTAÑAS -->
          <div class="flex bg-slate-900/90 p-1.5 rounded-2xl border border-slate-800 w-full md:w-auto overflow-x-auto text-xs gap-1">
            <button id="tab-repro-form" class="btn-subtab-repro px-4 py-2 rounded-xl font-bold transition flex items-center gap-1.5 ${this.subvistaActiva === 'formulario' ? 'bg-indigo-600 text-white shadow' : 'text-slate-400 hover:text-white'}">
              <span>➕</span> Registrar Servicio
            </button>
            <button id="tab-repro-hist" class="btn-subtab-repro px-4 py-2 rounded-xl font-bold transition flex items-center gap-1.5 ${this.subvistaActiva === 'historial' ? 'bg-indigo-600 text-white shadow' : 'text-slate-400 hover:text-white'}">
              <span>📋</span> Historial (${servicios.length})
            </button>
            <button id="tab-repro-kpis" class="btn-subtab-repro px-4 py-2 rounded-xl font-bold transition flex items-center gap-1.5 ${this.subvistaActiva === 'kpis' ? 'bg-indigo-600 text-white shadow' : 'text-slate-400 hover:text-white'}">
              <span>📊</span> Indicadores
            </button>
          </div>
        </div>

        <!-- CONTENIDO DINÁMICO DE SUBPESTAÑA -->
        <div id="contenedor-subvista-repro">
          ${this.renderSubvista(hembras, servicios)}
        </div>
      </div>
    `;

    this.enlazarEventos(hembras, servicios);
  }

  renderSubvista(hembras, servicios) {
    if (this.subvistaActiva === 'formulario') {
      return this.renderFormularioRegistro(hembras);
    } else if (this.subvistaActiva === 'historial') {
      return this.renderHistorial(servicios);
    } else if (this.subvistaActiva === 'kpis') {
      return this.renderKPIs(servicios);
    }
    return '';
  }

  renderFormularioRegistro(hembras) {
    const hoy = new Date().toISOString().split('T')[0];

    return `
      <div class="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <!-- SELECTOR DE TIPO DE SERVICIO -->
        <div class="p-5 bg-slate-50 border-b border-slate-200">
          <label class="block text-xs font-black uppercase text-slate-500 tracking-wider mb-2.5">
            Selecciona la Modalidad de Servicio Reproductivo:
          </label>
          <div class="grid grid-cols-1 sm:grid-cols-3 gap-3">
            <button type="button" class="btn-tipo-srv p-4 rounded-2xl border-2 text-left transition flex items-center gap-3 ${this.tipoServicioSeleccionado === 'inseminacion_artificial' ? 'border-indigo-600 bg-indigo-50/50 shadow-sm' : 'border-slate-200 hover:border-slate-300 bg-white'}" data-tipo="inseminacion_artificial">
              <span class="text-3xl">💉</span>
              <div>
                <div class="font-black text-slate-900 text-sm">Inseminación Artificial</div>
                <div class="text-[11px] text-slate-500 font-medium">IA Convencional / IATF con Pajilla</div>
              </div>
            </button>

            <button type="button" class="btn-tipo-srv p-4 rounded-2xl border-2 text-left transition flex items-center gap-3 ${this.tipoServicioSeleccionado === 'transferencia_embriones' ? 'border-purple-600 bg-purple-50/50 shadow-sm' : 'border-slate-200 hover:border-slate-300 bg-white'}" data-tipo="transferencia_embriones">
              <span class="text-3xl">🔬</span>
              <div>
                <div class="font-black text-slate-900 text-sm">Transferencia de Embriones</div>
                <div class="text-[11px] text-slate-500 font-medium">TE / FIV Receptora + Donadora</div>
              </div>
            </button>

            <button type="button" class="btn-tipo-srv p-4 rounded-2xl border-2 text-left transition flex items-center gap-3 ${this.tipoServicioSeleccionado === 'monta_natural' ? 'border-amber-600 bg-amber-50/50 shadow-sm' : 'border-slate-200 hover:border-slate-300 bg-white'}" data-tipo="monta_natural">
              <span class="text-3xl">🐂</span>
              <div>
                <div class="font-black text-slate-900 text-sm">Servicio con Toro</div>
                <div class="text-[11px] text-slate-500 font-medium">Monta Natural / Monta Dirigida</div>
              </div>
            </button>
          </div>
        </div>

        <!-- FORMULARIO DETALLADO -->
        <form id="form-servicio-reproductivo" class="p-5 sm:p-7 space-y-6">
          <div class="grid grid-cols-1 md:grid-cols-3 gap-4 sm:gap-5">
            <!-- 1. SELECCIÓN DE HEMBRA -->
            <div class="md:col-span-2">
              <label class="block text-xs font-bold text-slate-700 mb-1.5 flex justify-between">
                <span>🏷️ Hembra Servida (Arete / Tag):</span>
                <span class="text-slate-400 font-normal">Solo hembras activas</span>
              </label>
              <div class="flex flex-col sm:flex-row gap-2">
                <select id="select-hembra-servicio" class="w-full bg-slate-50 border border-slate-300 rounded-xl px-3 py-2.5 text-xs font-bold text-slate-800 outline-none focus:border-indigo-500">
                  <option value="">-- Seleccionar Hembra del Inventario --</option>
                  ${hembras.map((h) => {
                    const tag = h.identificacionTag || h.numero;
                    const st = h.estadoReproductivo || 'Vacía';
                    const icon = h.especie === 'bufalino' ? '🦬' : '🐂';
                    return `<option value="${tag}">${icon} Arete ${tag} - ${h.nombreAlias || 'Sin Nombre'} (${h.raza} | ${st})</option>`;
                  }).join('')}
                </select>
                <input type="text" id="input-tag-manual-repro" placeholder="O digita arete..." class="w-full sm:w-48 bg-slate-50 border border-slate-300 rounded-xl px-3 py-2.5 text-xs font-mono font-bold uppercase outline-none focus:border-indigo-500 shadow-sm" />
              </div>
            </div>

            <!-- 2. FECHA Y HORA -->
            <div>
              <label class="block text-xs font-bold text-slate-700 mb-1.5">📅 Fecha del Servicio:</label>
              <input type="date" id="input-fecha-servicio" value="${hoy}" class="w-full bg-slate-50 border border-slate-300 rounded-xl px-3 py-2.5 text-xs font-bold text-slate-800 outline-none focus:border-indigo-500" required />
            </div>
          </div>

          <!-- TARJETA INFORMATIVA ANIMAL SELECCIONADO (SI EXISTE) -->
          <div id="card-antecedentes-hembra" class="hidden p-4 rounded-2xl bg-indigo-50/70 border border-indigo-200 text-xs"></div>

          <!-- CAMPOS DINÁMICOS POR MODALIDAD -->
          <div class="bg-slate-50/80 p-5 rounded-2xl border border-slate-200 space-y-4">
            <h4 class="font-black text-slate-900 text-xs uppercase tracking-wider flex items-center gap-2">
              <span>🧬</span> Parámetros Genéticos y Operativos: ${this.getTituloModalidad()}
            </h4>

            ${this.renderCamposDinamicosPorModalidad()}
          </div>

          <!-- PROYECCIONES ZOOTÉCNICAS ESTIMADAS EN VIVO -->
          <div id="panel-proyeccion-repro" class="p-4 rounded-2xl bg-emerald-50 border border-emerald-200">
            <div class="flex items-center gap-2 font-black text-xs text-emerald-900 uppercase tracking-wider mb-2.5">
              <span>⏱️</span> Proyecciones Zootécnicas Estimadas (Calculadas Automáticamente):
            </div>
            <div class="grid grid-cols-1 sm:grid-cols-3 gap-3 text-xs">
              <div class="bg-white p-3 rounded-xl border border-emerald-200 shadow-xs">
                <span class="block text-[10px] font-bold text-slate-500 uppercase">Ecografía Temprana (30-35 d)</span>
                <span id="proj-ecografia" class="text-sm font-black font-mono text-emerald-800 mt-0.5 block">-</span>
                <span class="text-[10px] text-slate-400">Detección de vesícula embrionaria</span>
              </div>
              <div class="bg-white p-3 rounded-xl border border-emerald-200 shadow-xs">
                <span class="block text-[10px] font-bold text-slate-500 uppercase">Palpación Confirmatoria (60 d)</span>
                <span id="proj-palpacion" class="text-sm font-black font-mono text-emerald-800 mt-0.5 block">-</span>
                <span class="text-[10px] text-slate-400">Chequeo manual ginecológico</span>
              </div>
              <div class="bg-white p-3 rounded-xl border border-emerald-200 shadow-xs">
                <span class="block text-[10px] font-bold text-slate-500 uppercase">Fecha Probable de Parto</span>
                <span id="proj-parto" class="text-sm font-black font-mono text-emerald-800 mt-0.5 block">-</span>
                <span class="text-[10px] text-slate-400">283 d bovino / 310 d bufalino</span>
              </div>
            </div>
          </div>

          <!-- ALERTAS DE AUDITORÍA CON IA -->
          <div id="alertas-ia-servicio" class="hidden p-3 rounded-2xl bg-rose-50 border border-rose-200 text-xs text-rose-800 space-y-1"></div>

          <!-- BOTONES DE ACCIÓN -->
          <div class="flex flex-col sm:flex-row justify-end items-stretch sm:items-center gap-2.5 sm:gap-3 pt-2">
            <button type="reset" class="w-full sm:w-auto px-5 py-3 sm:py-2.5 rounded-xl border border-slate-300 text-slate-700 font-bold text-xs hover:bg-slate-100 transition active:scale-95 cursor-pointer text-center">
              Limpiar Formulario
            </button>
            <button type="submit" class="w-full sm:w-auto px-6 py-3.5 sm:py-2.5 rounded-xl bg-gradient-to-r from-indigo-600 to-purple-600 active:scale-95 text-white font-black text-xs shadow-lg hover:from-indigo-700 hover:to-purple-700 transition flex items-center justify-center gap-2 cursor-pointer">
              <span>💾</span> Guardar Servicio Reproductivo
            </button>
          </div>
        </form>
      </div>
    `;
  }

  getTituloModalidad() {
    if (this.tipoServicioSeleccionado === 'inseminacion_artificial') return 'Inseminación Artificial (IA / IATF)';
    if (this.tipoServicioSeleccionado === 'transferencia_embriones') return 'Transferencia de Embriones (TE / FIV)';
    return 'Servicio con Toro (Monta)';
  }

  renderCamposDinamicosPorModalidad() {
    if (this.tipoServicioSeleccionado === 'inseminacion_artificial') {
      return `
        <div class="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">Toro / Código de Pajilla (*):</label>
            <input type="text" id="input-reproductor-ia" placeholder="Ej. TORO-GIR-08 (Pajilla #4082)" class="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-xs font-bold outline-none focus:border-indigo-500" required />
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">Raza del Semen:</label>
            <input type="text" id="input-raza-semen" placeholder="Ej. Gyr Lechero / Angus Negro" class="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-xs outline-none focus:border-indigo-500" />
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">Técnico / Inseminador (*):</label>
            <input type="text" id="input-tecnico-ia" placeholder="Nombre del inseminador" class="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-xs font-bold outline-none focus:border-indigo-500" required />
          </div>
        </div>

        <div class="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">Protocolo de Sincronización:</label>
            <select id="select-protocolo-ia" class="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-xs font-bold text-slate-700 outline-none focus:border-indigo-500">
              <option value="IATF (Dispositivo Progesterona + Benzoato)">IATF (Dispositivo P4 + Benzoato Estradiol)</option>
              <option value="IATF (Ovsynch / Doble Ovsynch)">IATF (Ovsynch / Doble Ovsynch)</option>
              <option value="Celo Natural Detectado (AM-PM)">Celo Natural Detectado (Regla AM-PM)</option>
              <option value="Sincronización con Prostaglandina (PGF2α)">Sincronización con Prostaglandina (PGF2α)</option>
              <option value="Otro">Otro Protocolo</option>
            </select>
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">Turno / Hora del Servicio:</label>
            <select id="select-hora-ia" class="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-xs font-bold text-slate-700 outline-none focus:border-indigo-500">
              <option value="Mañana (AM)">Mañana (AM)</option>
              <option value="Tarde (PM)">Tarde (PM)</option>
            </select>
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">Condición Corporal (1.0 - 5.0):</label>
            <input type="number" id="input-cc-ia" min="1" max="5" step="0.25" value="3.0" class="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-xs font-bold outline-none focus:border-indigo-500" />
          </div>
        </div>
      `;
    } else if (this.tipoServicioSeleccionado === 'transferencia_embriones') {
      return `
        <div class="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">Donadora Genética (Madre Biológica) (*):</label>
            <input type="text" id="input-donadora-te" placeholder="Ej. VACA-DON-101 (Gyr Plus)" class="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-xs font-bold outline-none focus:border-purple-500" required />
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">Toro Padre Genético (*):</label>
            <input type="text" id="input-toro-padre-te" placeholder="Ej. TORO-HOLSTEIN-ELITE" class="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-xs font-bold outline-none focus:border-purple-500" required />
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">Veterinario / Embriólogo (*):</label>
            <input type="text" id="input-veterinario-te" placeholder="Médico Veterinario responsable" class="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-xs font-bold outline-none focus:border-purple-500" required />
          </div>
        </div>

        <div class="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">Estadio y Calidad del Embrión:</label>
            <select id="select-calidad-embrio" class="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-xs font-bold text-slate-700 outline-none focus:border-purple-500">
              <option value="Blastocisto Día 7 - Grado 1 (Excelente)">Blastocisto Día 7 - Grado 1 (Excelente)</option>
              <option value="Mórula Día 7 - Grado 1 (Excelente)">Mórula Día 7 - Grado 1 (Excelente)</option>
              <option value="Blastocisto Expandido - Grado 2 (Bueno)">Blastocisto Expandido - Grado 2 (Bueno)</option>
              <option value="Embrión Vitrificado / Congelado">Embrión Vitrificado / Congelado</option>
              <option value="Embrión en Fresco (FIV)">Embrión en Fresco (FIV)</option>
            </select>
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">Cuerno Uterino Implantado:</label>
            <select id="select-cuerno-te" class="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-xs font-bold text-slate-700 outline-none focus:border-purple-500">
              <option value="Cuerno Derecho (Ipsilateral CL)">Cuerno Derecho (Ipsilateral CL)</option>
              <option value="Cuerno Izquierdo (Ipsilateral CL)">Cuerno Izquierdo (Ipsilateral CL)</option>
            </select>
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">Cuerpo Lúteo Receptora (CL):</label>
            <input type="text" id="input-cl-te" placeholder="Ej. CL Compacto > 18mm" class="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-xs outline-none focus:border-purple-500" />
          </div>
        </div>
      `;
    } else {
      return `
        <div class="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">Toro Reproductor / Padrote (*):</label>
            <input type="text" id="input-toro-monta" placeholder="Ej. TORO-PADROTE-01 (Titán)" class="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-xs font-bold outline-none focus:border-amber-500" required />
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">Modalidad de Monta:</label>
            <select id="select-modalidad-monta" class="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-xs font-bold text-slate-700 outline-none focus:border-amber-500">
              <option value="Monta Dirigida (Corral / Asistida)">Monta Dirigida (Corral / Asistida)</option>
              <option value="Monta en Lote (Toro con vacas a campo)">Monta en Lote (Toro con vacas a campo)</option>
            </select>
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">Lote / Potrero:</label>
            <input type="text" id="input-lote-monta" placeholder="Ej. Potrero 4 - Lote Reproductivo" class="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-xs outline-none focus:border-amber-500" />
          </div>
        </div>

        <div>
          <label class="block text-xs font-bold text-slate-700 mb-1">Observaciones de la Cópula / Conducta de Celo:</label>
          <input type="text" id="input-obs-monta" placeholder="Ej. Servicio observado a las 7:00 AM con aceptación plena del celo" class="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-xs outline-none focus:border-amber-500" />
        </div>
      `;
    }
  }

  renderHistorial(servicios) {
    let filtrados = [...servicios];

    if (this.filtroTipoHistorial !== 'todos') {
      filtrados = filtrados.filter((s) => s.tipo === this.filtroTipoHistorial);
    }

    if (this.filtroEstadoHistorial !== 'todos') {
      filtrados = filtrados.filter((s) => (s.resultado || 'Pendiente Chequeo') === this.filtroEstadoHistorial);
    }

    if (this.busquedaHistorial.trim()) {
      const q = this.busquedaHistorial.trim().toUpperCase();
      filtrados = filtrados.filter((s) =>
        (s.tag || s.animalTag || '').toUpperCase().includes(q) ||
        (s.reproductor || '').toUpperCase().includes(q) ||
        (s.donadora || '').toUpperCase().includes(q) ||
        (s.tecnico || '').toUpperCase().includes(q)
      );
    }

    // Ordenar por fecha descendente
    filtrados.sort((a, b) => new Date(b.fecha) - new Date(a.fecha));

    return `
      <div class="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden space-y-4 p-5">
        <!-- BARRA DE FILTROS -->
        <div class="flex flex-col md:flex-row justify-between items-start md:items-center gap-3 bg-slate-50 p-3.5 rounded-2xl border border-slate-200">
          <div class="flex items-center gap-2 w-full md:w-auto">
            <span class="text-xs font-bold text-slate-600">🔍 Buscar:</span>
            <input type="text" id="input-buscar-hist-repro" value="${this.busquedaHistorial}" placeholder="Buscar por arete, toro, pajilla..." class="bg-white border border-slate-300 rounded-xl px-3 py-1.5 text-xs font-bold outline-none w-full md:w-64" />
          </div>

          <div class="flex flex-wrap items-center gap-2 w-full md:w-auto">
            <select id="select-filtro-tipo-hist" class="bg-white border border-slate-300 rounded-xl px-3 py-1.5 text-xs font-bold text-slate-700 outline-none">
              <option value="todos" ${this.filtroTipoHistorial === 'todos' ? 'selected' : ''}>Todas las Modalidades</option>
              <option value="inseminacion_artificial" ${this.filtroTipoHistorial === 'inseminacion_artificial' ? 'selected' : ''}>💉 Inseminación Artificial</option>
              <option value="transferencia_embriones" ${this.filtroTipoHistorial === 'transferencia_embriones' ? 'selected' : ''}>🔬 Transferencia de Embriones</option>
              <option value="monta_natural" ${this.filtroTipoHistorial === 'monta_natural' ? 'selected' : ''}>🐂 Servicio con Toro</option>
            </select>

            <select id="select-filtro-estado-hist" class="bg-white border border-slate-300 rounded-xl px-3 py-1.5 text-xs font-bold text-slate-700 outline-none">
              <option value="todos" ${this.filtroEstadoHistorial === 'todos' ? 'selected' : ''}>Todos los Estados</option>
              <option value="Pendiente Chequeo" ${this.filtroEstadoHistorial === 'Pendiente Chequeo' ? 'selected' : ''}>⏳ Pendiente Chequeo</option>
              <option value="Preñada Confirmada" ${this.filtroEstadoHistorial === 'Preñada Confirmada' ? 'selected' : ''}>🟢 Preñada Confirmada</option>
              <option value="Vacía / Repitió" ${this.filtroEstadoHistorial === 'Vacía / Repitió' ? 'selected' : ''}>🔴 Vacía / Repitió Celo</option>
            </select>
          </div>
        </div>

        <!-- TABLA DE HISTORIAL -->
        ${filtrados.length === 0 ? `
          <div class="p-10 text-center text-slate-400">
            <span class="text-4xl block mb-2">🧬</span>
            <span class="font-bold">No se encontraron registros de servicios con los filtros aplicados.</span>
          </div>
        ` : `
          <div class="overflow-x-auto border border-slate-200 rounded-2xl">
            <table class="w-full text-left text-xs">
              <thead class="bg-slate-100 uppercase font-bold text-slate-700 text-[10px] tracking-wider">
                <tr>
                  <th class="p-3">Fecha Servicio</th>
                  <th class="p-3">Hembra</th>
                  <th class="p-3">Modalidad</th>
                  <th class="p-3">Reproductor / Pajilla / Donadora</th>
                  <th class="p-3">Técnico / Responsable</th>
                  <th class="p-3">Días Post-Servicio</th>
                  <th class="p-3">Diagnóstico / Estado</th>
                  <th class="p-3 text-right">Acciones</th>
                </tr>
              </thead>
              <tbody class="divide-y divide-slate-100">
                ${filtrados.map((s) => {
                  const hoy = new Date();
                  const fServ = new Date(s.fecha);
                  const diasPost = Math.max(0, Math.floor((hoy.getTime() - fServ.getTime()) / (1000 * 60 * 60 * 24)));
                  const st = s.resultado || 'Pendiente Chequeo';

                  let badgeColor = 'bg-amber-100 text-amber-800 border-amber-300';
                  if (st === 'Preñada Confirmada') badgeColor = 'bg-emerald-100 text-emerald-800 border-emerald-300';
                  if (st === 'Vacía / Repitió') badgeColor = 'bg-rose-100 text-rose-800 border-rose-300';

                  let badgeTipo = 'bg-indigo-100 text-indigo-800';
                  let nombreTipo = '💉 Inseminación Artificial';
                  if (s.tipo === 'transferencia_embriones') {
                    badgeTipo = 'bg-purple-100 text-purple-800';
                    nombreTipo = '🔬 Transf. Embriones';
                  } else if (s.tipo === 'monta_natural') {
                    badgeTipo = 'bg-amber-100 text-amber-900';
                    nombreTipo = '🐂 Servicio con Toro';
                  }

                  return `
                    <tr class="hover:bg-slate-50 transition">
                      <td class="p-3 font-bold font-mono text-slate-800">${s.fecha}</td>
                      <td class="p-3">
                        <span class="font-mono font-black text-slate-900 px-2 py-0.5 rounded bg-slate-100 border border-slate-200">
                          ${s.tag || s.animalTag}
                        </span>
                      </td>
                      <td class="p-3">
                        <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${badgeTipo}">
                          ${nombreTipo}
                        </span>
                      </td>
                      <td class="p-3 font-bold text-slate-800">
                        ${s.reproductor || '-'}
                        ${s.donadora ? `<span class="block text-[10px] text-purple-700 font-normal">Donadora: ${s.donadora}</span>` : ''}
                      </td>
                      <td class="p-3 text-slate-600">${s.tecnico || '-'}</td>
                      <td class="p-3 font-mono font-bold text-slate-700">${diasPost} días</td>
                      <td class="p-3">
                        <span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold border ${badgeColor}">
                          ${st}
                        </span>
                      </td>
                      <td class="p-3 text-right whitespace-nowrap space-x-1">
                        ${st === 'Pendiente Chequeo' ? `
                          <button class="btn-confirmar-prenez px-2 py-1 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded-lg text-[10px] transition" data-id="${s.id}" data-tag="${s.tag || s.animalTag}" data-dias="${diasPost}" title="Confirmar Preñez">
                            ✓ Preñada
                          </button>
                          <button class="btn-declarar-vacia px-2 py-1 bg-rose-600 hover:bg-rose-700 text-white font-bold rounded-lg text-[10px] transition" data-id="${s.id}" data-tag="${s.tag || s.animalTag}" title="Declarar Vacía / Repitió Celo">
                            ✗ Vacía
                          </button>
                        ` : ''}
                        <button class="btn-eliminar-srv px-2 py-1 bg-slate-100 hover:bg-rose-100 text-slate-500 hover:text-rose-700 font-bold rounded-lg text-[10px] transition" data-id="${s.id}" title="Eliminar Registro">
                          🗑️
                        </button>
                      </td>
                    </tr>
                  `;
                }).join('')}
              </tbody>
            </table>
          </div>
        `}
      </div>
    `;
  }

  renderKPIs(servicios) {
    const total = servicios.length;
    const iaCount = servicios.filter((s) => s.tipo === 'inseminacion_artificial').length;
    const teCount = servicios.filter((s) => s.tipo === 'transferencia_embriones').length;
    const montaCount = servicios.filter((s) => s.tipo === 'monta_natural').length;

    const prenadas = servicios.filter((s) => s.resultado === 'Preñada Confirmada').length;
    const vacias = servicios.filter((s) => s.resultado === 'Vacía / Repitió').length;
    const pendientes = servicios.filter((s) => !s.resultado || s.resultado === 'Pendiente Chequeo').length;

    const evaluados = prenadas + vacias;
    const tasaConcepcion = evaluados > 0 ? ((prenadas / evaluados) * 100).toFixed(1) : 0;

    return `
      <div class="space-y-5">
        <!-- TARJETAS PRINCIPALES -->
        <div class="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
          <div class="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm">
            <span class="text-[10px] font-bold text-slate-400 uppercase">Total Servicios Registrados</span>
            <div class="text-2xl font-black text-slate-900 mt-1 font-mono">${total}</div>
            <span class="text-[10px] text-indigo-600 font-bold">En el predio activo</span>
          </div>

          <div class="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm">
            <span class="text-[10px] font-bold text-slate-400 uppercase">Tasa de Concepción Evaluada</span>
            <div class="text-2xl font-black text-emerald-600 mt-1 font-mono">${tasaConcepcion}%</div>
            <span class="text-[10px] text-slate-500">${prenadas} preñadas de ${evaluados} evaluadas</span>
          </div>

          <div class="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm">
            <span class="text-[10px] font-bold text-slate-400 uppercase">Pendientes de Chequeo</span>
            <div class="text-2xl font-black text-amber-600 mt-1 font-mono">${pendientes}</div>
            <span class="text-[10px] text-amber-700">Ecografía / Palpación en espera</span>
          </div>

          <div class="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm">
            <span class="text-[10px] font-bold text-slate-400 uppercase">Repetición de Celo / Vacías</span>
            <div class="text-2xl font-black text-rose-600 mt-1 font-mono">${vacias}</div>
            <span class="text-[10px] text-rose-600">Servicios fallidos</span>
          </div>
        </div>

        <!-- DESGLOSE POR MODALIDAD -->
        <div class="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div class="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-4">
            <div class="w-12 h-12 rounded-xl bg-indigo-50 text-indigo-700 flex items-center justify-center text-2xl font-bold">
              💉
            </div>
            <div>
              <span class="text-xs font-bold text-slate-500 block">Inseminación Artificial (IA)</span>
              <span class="text-xl font-black text-slate-900 font-mono">${iaCount}</span>
              <span class="text-[10px] text-slate-400 block">${total > 0 ? ((iaCount / total) * 100).toFixed(0) : 0}% del total</span>
            </div>
          </div>

          <div class="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-4">
            <div class="w-12 h-12 rounded-xl bg-purple-50 text-purple-700 flex items-center justify-center text-2xl font-bold">
              🔬
            </div>
            <div>
              <span class="text-xs font-bold text-slate-500 block">Transferencia de Embriones (TE)</span>
              <span class="text-xl font-black text-slate-900 font-mono">${teCount}</span>
              <span class="text-[10px] text-slate-400 block">${total > 0 ? ((teCount / total) * 100).toFixed(0) : 0}% del total</span>
            </div>
          </div>

          <div class="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-4">
            <div class="w-12 h-12 rounded-xl bg-amber-50 text-amber-700 flex items-center justify-center text-2xl font-bold">
              🐂
            </div>
            <div>
              <span class="text-xs font-bold text-slate-500 block">Servicios con Toro (Monta)</span>
              <span class="text-xl font-black text-slate-900 font-mono">${montaCount}</span>
              <span class="text-[10px] text-slate-400 block">${total > 0 ? ((montaCount / total) * 100).toFixed(0) : 0}% del total</span>
            </div>
          </div>
        </div>
      </div>
    `;
  }

  enlazarEventos(hembras, servicios) {
    // 1. Selector de subpestañas
    const btnForm = document.getElementById('tab-repro-form');
    if (btnForm) {
      btnForm.addEventListener('click', () => {
        this.subvistaActiva = 'formulario';
        this.render();
      });
    }

    const btnHist = document.getElementById('tab-repro-hist');
    if (btnHist) {
      btnHist.addEventListener('click', () => {
        this.subvistaActiva = 'historial';
        this.render();
      });
    }

    const btnKpis = document.getElementById('tab-repro-kpis');
    if (btnKpis) {
      btnKpis.addEventListener('click', () => {
        this.subvistaActiva = 'kpis';
        this.render();
      });
    }

    // 2. Botones de tipo de servicio (IA, TE, Monta)
    document.querySelectorAll('.btn-tipo-srv').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const tipo = e.currentTarget.getAttribute('data-tipo');
        if (tipo) {
          this.tipoServicioSeleccionado = tipo;
          this.render();
        }
      });
    });

    // 3. Selección de hembra y antecedentes
    const selH = document.getElementById('select-hembra-servicio');
    const inputTagManual = document.getElementById('input-tag-manual-repro');

    const actualizarAnimalSeleccionado = (tag) => {
      if (!tag) {
        this.animalSeleccionado = null;
        this.actualizarCardAntecedentes(null);
        return;
      }
      const cleanTag = tag.trim().toUpperCase();
      const todosHembras = (this.getAnimalesBusqueda ? this.getAnimalesBusqueda() : (this.getAnimales ? this.getAnimales() : []))
        .filter((a) => (a.sexo || '').toLowerCase() === 'hembra');
      const match = todosHembras.find((h) => (h.identificacionTag || h.numero || '').toUpperCase() === cleanTag);
      this.animalSeleccionado = match || null;
      this.actualizarCardAntecedentes(match);
      this.actualizarProyeccionesEnVivo();
      this.validarConIA();
    };

    if (selH) {
      selH.addEventListener('change', (e) => {
        if (inputTagManual) inputTagManual.value = e.target.value;
        actualizarAnimalSeleccionado(e.target.value);
      });
    }

    if (inputTagManual) {
      conectarAutosuggestAnimales({
        inputElement: inputTagManual,
        getAnimales: () => {
          const base = this.getAnimalesBusqueda ? this.getAnimalesBusqueda() : (this.getAnimales ? this.getAnimales() : []);
          return base.filter((a) => (a.sexo || '').toLowerCase() === 'hembra');
        },
        theme: 'indigo',
        maxResultados: 8,
        onTrasladarAFinca: (animal) => {
          if (this.onTrasladarAFinca) this.onTrasladarAFinca(animal);
        },
        onReactivarAnimal: (animal) => {
          if (this.onReactivarAnimal) this.onReactivarAnimal(animal);
        },
        onSeleccionar: (animal) => {
          const tag = animal.identificacionTag || animal.numero;
          inputTagManual.value = tag;
          if (selH) selH.value = tag;
          actualizarAnimalSeleccionado(tag);
        }
      });

      inputTagManual.addEventListener('input', (e) => {
        if (selH) selH.value = e.target.value.toUpperCase();
        actualizarAnimalSeleccionado(e.target.value);
      });
    }

    // Autosuggest para Donadora Genética (TE)
    const inDonadora = document.getElementById('input-donadora-te');
    if (inDonadora) {
      conectarAutosuggestAnimales({
        inputElement: inDonadora,
        getAnimales: () => {
          const base = this.getAnimalesBusqueda ? this.getAnimalesBusqueda() : (this.getAnimales ? this.getAnimales() : []);
          return base.filter((a) => (a.sexo || '').toLowerCase() === 'hembra');
        },
        theme: 'purple',
        maxResultados: 6,
        onTrasladarAFinca: (animal) => {
          if (this.onTrasladarAFinca) this.onTrasladarAFinca(animal);
        },
        onReactivarAnimal: (animal) => {
          if (this.onReactivarAnimal) this.onReactivarAnimal(animal);
        },
        onSeleccionar: (animal) => {
          inDonadora.value = (animal.identificacionTag || animal.numero) + (animal.nombreAlias ? ` (${animal.nombreAlias})` : '');
        }
      });
    }

    // Autosuggest para Toro Padre (TE)
    const inToroTE = document.getElementById('input-toro-padre-te');
    if (inToroTE) {
      conectarAutosuggestAnimales({
        inputElement: inToroTE,
        getAnimales: () => {
          const base = this.getAnimalesBusqueda ? this.getAnimalesBusqueda() : (this.getAnimales ? this.getAnimales() : []);
          return base.filter((a) => (a.sexo || '').toLowerCase() === 'macho');
        },
        theme: 'purple',
        maxResultados: 6,
        onTrasladarAFinca: (animal) => {
          if (this.onTrasladarAFinca) this.onTrasladarAFinca(animal);
        },
        onReactivarAnimal: (animal) => {
          if (this.onReactivarAnimal) this.onReactivarAnimal(animal);
        },
        onSeleccionar: (animal) => {
          inToroTE.value = (animal.identificacionTag || animal.numero) + (animal.nombreAlias ? ` (${animal.nombreAlias})` : '');
        }
      });
    }

    // Autosuggest para Toro Padrote (Monta Natural)
    const inToroMonta = document.getElementById('input-toro-monta');
    if (inToroMonta) {
      conectarAutosuggestAnimales({
        inputElement: inToroMonta,
        getAnimales: () => {
          const base = this.getAnimalesBusqueda ? this.getAnimalesBusqueda() : (this.getAnimales ? this.getAnimales() : []);
          return base.filter((a) => (a.sexo || '').toLowerCase() === 'macho');
        },
        theme: 'amber',
        maxResultados: 6,
        onTrasladarAFinca: (animal) => {
          if (this.onTrasladarAFinca) this.onTrasladarAFinca(animal);
        },
        onReactivarAnimal: (animal) => {
          if (this.onReactivarAnimal) this.onReactivarAnimal(animal);
        },
        onSeleccionar: (animal) => {
          inToroMonta.value = (animal.identificacionTag || animal.numero) + (animal.nombreAlias ? ` (${animal.nombreAlias})` : '');
        }
      });
    }

    // 4. Cambio de fecha para proyecciones
    const inputFecha = document.getElementById('input-fecha-servicio');
    if (inputFecha) {
      inputFecha.addEventListener('change', () => {
        this.actualizarProyeccionesEnVivo();
        this.validarConIA();
      });
      // Calcular proyecciones iniciales
      this.actualizarProyeccionesEnVivo();
    }

    // 5. Envío de formulario
    const form = document.getElementById('form-servicio-reproductivo');
    if (form) {
      form.addEventListener('submit', (e) => {
        e.preventDefault();
        this.manejarEnvioFormulario();
      });
    }

    // 6. Eventos de Historial (Filtros y Búsqueda)
    const inputBuscar = document.getElementById('input-buscar-hist-repro');
    if (inputBuscar) {
      inputBuscar.addEventListener('input', (e) => {
        this.busquedaHistorial = e.target.value;
        const cont = document.getElementById('contenedor-subvista-repro');
        if (cont) cont.innerHTML = this.renderHistorial(this.getServicios ? this.getServicios() : []);
        this.enlazarEventosHistorial();
      });
    }

    const selFiltroTipo = document.getElementById('select-filtro-tipo-hist');
    if (selFiltroTipo) {
      selFiltroTipo.addEventListener('change', (e) => {
        this.filtroTipoHistorial = e.target.value;
        const cont = document.getElementById('contenedor-subvista-repro');
        if (cont) cont.innerHTML = this.renderHistorial(this.getServicios ? this.getServicios() : []);
        this.enlazarEventosHistorial();
      });
    }

    const selFiltroEstado = document.getElementById('select-filtro-estado-hist');
    if (selFiltroEstado) {
      selFiltroEstado.addEventListener('change', (e) => {
        this.filtroEstadoHistorial = e.target.value;
        const cont = document.getElementById('contenedor-subvista-repro');
        if (cont) cont.innerHTML = this.renderHistorial(this.getServicios ? this.getServicios() : []);
        this.enlazarEventosHistorial();
      });
    }

    this.enlazarEventosHistorial();
  }

  enlazarEventosHistorial() {
    // Confirmar preñez
    document.querySelectorAll('.btn-confirmar-prenez').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const id = e.currentTarget.getAttribute('data-id');
        const tag = e.currentTarget.getAttribute('data-tag');
        const dias = parseInt(e.currentTarget.getAttribute('data-dias')) || 60;
        if (confirm(`¿Confirmar diagnóstico de preñez para la hembra ${tag}? Pasará a estado "Preñada" con ${dias} días de gestación estimados.`)) {
          if (this.onActualizarServicio) {
            this.onActualizarServicio({ id, tag, nuevoEstado: 'Preñada Confirmada', diasGestacion: dias });
          }
          this.render();
        }
      });
    });

    // Declarar vacía / repitió celo
    document.querySelectorAll('.btn-declarar-vacia').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const id = e.currentTarget.getAttribute('data-id');
        const tag = e.currentTarget.getAttribute('data-tag');
        if (confirm(`¿Registrar repetición de celo / vacía para la hembra ${tag}? Pasará a estado "Vacía".`)) {
          if (this.onActualizarServicio) {
            this.onActualizarServicio({ id, tag, nuevoEstado: 'Vacía / Repitió', diasGestacion: 0 });
          }
          this.render();
        }
      });
    });

    // Eliminar servicio
    document.querySelectorAll('.btn-eliminar-srv').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const id = e.currentTarget.getAttribute('data-id');
        if (confirm('¿Seguro que deseas eliminar este registro de servicio?')) {
          if (this.onEliminarServicio) {
            this.onEliminarServicio(id);
          }
          this.render();
        }
      });
    });
  }

  actualizarCardAntecedentes(animal) {
    const card = document.getElementById('card-antecedentes-hembra');
    if (!card) return;

    if (!animal) {
      card.classList.add('hidden');
      card.innerHTML = '';
      return;
    }

    const tag = animal.identificacionTag || animal.numero;
    const st = animal.estadoReproductivo || 'Vacía';
    const especie = animal.especie === 'bufalino' ? 'Bufalino 🦬' : 'Vacuno 🐂';

    card.classList.remove('hidden');
    card.innerHTML = `
      <div class="flex items-center justify-between">
        <div>
          <span class="font-black text-indigo-900 text-sm">Hembra Seleccionada: ${tag} (${animal.nombreAlias || 'Sin Nombre'})</span>
          <p class="text-[11px] text-indigo-700 mt-0.5">${especie} • Raza: ${animal.raza} • Lote: ${animal.lote} • Estado Reproductivo: <strong>${st}</strong></p>
        </div>
        <div class="text-right">
          <span class="text-[10px] text-indigo-800 uppercase font-bold block">Último Parto</span>
          <span class="font-mono font-bold text-slate-800">${animal.fechaUltimoParto || 'Primeriza / Sin Partos'}</span>
        </div>
      </div>
    `;
  }

  actualizarProyeccionesEnVivo() {
    const inputFecha = document.getElementById('input-fecha-servicio');
    if (!inputFecha || !inputFecha.value) return;

    const especie = this.animalSeleccionado ? this.animalSeleccionado.especie || 'bovino' : 'bovino';
    const proy = calcularProyeccionServicio(inputFecha.value, especie);

    const elEco = document.getElementById('proj-ecografia');
    const elPalp = document.getElementById('proj-palpacion');
    const elParto = document.getElementById('proj-parto');

    if (elEco && proy) elEco.textContent = proy.fechaEcografiaEstimada;
    if (elPalp && proy) elPalp.textContent = proy.fechaPalpacionEstimada;
    if (elParto && proy) elParto.textContent = `${proy.fechaPartoEstimada} (${proy.diasGestacionMedia} d)`;
  }

  validarConIA() {
    const panel = document.getElementById('alertas-ia-servicio');
    if (!panel) return;

    const tag = (document.getElementById('input-tag-manual-repro')?.value || '').trim();
    const fecha = document.getElementById('input-fecha-servicio')?.value;
    let reproductor = '';

    if (this.tipoServicioSeleccionado === 'inseminacion_artificial') {
      reproductor = document.getElementById('input-reproductor-ia')?.value;
    } else if (this.tipoServicioSeleccionado === 'transferencia_embriones') {
      reproductor = document.getElementById('input-toro-padre-te')?.value;
    } else {
      reproductor = document.getElementById('input-toro-monta')?.value;
    }

    if (!this.animalSeleccionado && tag) {
      const animales = this.getAnimales ? this.getAnimales() : [];
      this.animalSeleccionado = animales.find((a) => (a.identificacionTag || a.numero || '').toUpperCase() === tag.toUpperCase());
    }

    const anomalías = auditarServicioInput(this.animalSeleccionado, this.tipoServicioSeleccionado, fecha, reproductor);

    if (anomalías.length > 0) {
      panel.classList.remove('hidden');
      panel.innerHTML = anomalías.map((a) => `<div class="${a.tipo === 'error' ? 'font-black text-rose-700' : 'text-amber-800'}">• ${a.mensaje}</div>`).join('');
    } else {
      panel.classList.add('hidden');
      panel.innerHTML = '';
    }

    return anomalías.filter((a) => a.tipo === 'error');
  }

  manejarEnvioFormulario() {
    const inputTag = document.getElementById('input-tag-manual-repro');
    const selTag = document.getElementById('select-hembra-servicio');
    const tag = (inputTag?.value || selTag?.value || '').trim().toUpperCase();

    if (!tag) {
      alert('Debes seleccionar o digitar el arete de la hembra.');
      return;
    }

    const fecha = document.getElementById('input-fecha-servicio')?.value;
    if (!fecha) {
      alert('Debes ingresar la fecha del servicio.');
      return;
    }

    const errores = this.validarConIA();
    if (errores && errores.length > 0) {
      alert(`No se puede guardar el servicio debido a errores biológicos:\n${errores.map((e) => e.mensaje).join('\n')}`);
      return;
    }

    let reproductor = '';
    let donadora = '';
    let tecnico = '';
    let protocolo = '';
    let observaciones = '';

    if (this.tipoServicioSeleccionado === 'inseminacion_artificial') {
      reproductor = document.getElementById('input-reproductor-ia')?.value || '';
      tecnico = document.getElementById('input-tecnico-ia')?.value || '';
      protocolo = document.getElementById('select-protocolo-ia')?.value || '';
      const razaSemen = document.getElementById('input-raza-semen')?.value || '';
      const cc = document.getElementById('input-cc-ia')?.value || '';
      observaciones = `Raza Semen: ${razaSemen} | CC: ${cc}`;
    } else if (this.tipoServicioSeleccionado === 'transferencia_embriones') {
      donadora = document.getElementById('input-donadora-te')?.value || '';
      reproductor = document.getElementById('input-toro-padre-te')?.value || '';
      tecnico = document.getElementById('input-veterinario-te')?.value || '';
      protocolo = document.getElementById('select-calidad-embrio')?.value || '';
      const cuerno = document.getElementById('select-cuerno-te')?.value || '';
      const cl = document.getElementById('input-cl-te')?.value || '';
      observaciones = `Embrión: ${protocolo} | Cuerno: ${cuerno} | CL: ${cl}`;
    } else {
      reproductor = document.getElementById('input-toro-monta')?.value || '';
      protocolo = document.getElementById('select-modalidad-monta')?.value || '';
      const lote = document.getElementById('input-lote-monta')?.value || '';
      const obs = document.getElementById('input-obs-monta')?.value || '';
      tecnico = 'Monta Natural / Operario';
      observaciones = `Modalidad: ${protocolo} | Lote: ${lote} | ${obs}`;
    }

    const especie = this.animalSeleccionado ? this.animalSeleccionado.especie || 'bovino' : 'bovino';
    const proyeccion = calcularProyeccionServicio(fecha, especie);

    const nuevoServicio = {
      id: `SRV-${Date.now()}-${Math.random().toString(36).substr(2, 4)}`,
      tag,
      animalTag: tag,
      tipo: this.tipoServicioSeleccionado,
      fecha,
      reproductor,
      donadora,
      tecnico,
      protocolo,
      observaciones,
      resultado: 'Pendiente Chequeo',
      fechaEcografiaEstimada: proyeccion?.fechaEcografiaEstimada,
      fechaPalpacionEstimada: proyeccion?.fechaPalpacionEstimada,
      fechaPartoEstimada: proyeccion?.fechaPartoEstimada
    };

    if (this.onRegistrarServicio) {
      this.onRegistrarServicio(nuevoServicio);
    }

    alert(`✓ Servicio reproductivo guardado con éxito para la hembra ${tag}.\nEstado actualizado a "Servida".`);
    this.subvistaActiva = 'historial';
    this.render();
  }
}


// ============================================================================
// ARCHIVO: frontend/src/components/PestanaAnimales.js
// ============================================================================
/**
 * GANADERO AD - PESTAÑA DEDICADA DE ANIMALES
 * Muestra el inventario completo de la finca con todos sus datos:
 * Tag/Arete, Especie (Vacuno/Bufalino), Nombre/Alias, Sexo, Raza, Categoría, Lote,
 * Padre, Madre, Fecha de Nacimiento, Edad, Estado Reproductivo (con Días de Preñez),
 * Días Abiertos, Último Parto, IEP proyectado, Peso Actual y GDP.
 * Incluye búsqueda en vivo, filtros combinados, modal de "+ Nuevo Animal" y apertura de Ficha Técnica.
 */




class PestanaAnimales {
  constructor({
    containerId,
    getAnimales,
    getAnimalesBusqueda,
    getLotes,
    getRol,
    onVerFicha,
    onCrearAnimal,
    onActualizarAnimal,
    onEliminarAnimal,
    onTrasladar,
    onAbrirModuloTraslados,
    onExtraerAnimal,
    onReactivarAnimal,
    onTrasladarAFinca
  }) {
    this.container = typeof document !== 'undefined' && containerId ? document.getElementById(containerId) : null;
    this.getAnimales = getAnimales;
    this.getAnimalesBusqueda = getAnimalesBusqueda;
    this.getLotes = getLotes;
    this.getRol = getRol;
    this.onVerFicha = onVerFicha;
    this.onCrearAnimal = onCrearAnimal;
    this.onActualizarAnimal = onActualizarAnimal;
    this.onEliminarAnimal = onEliminarAnimal;
    this.onTrasladar = onTrasladar;
    this.onAbrirModuloTraslados = onAbrirModuloTraslados;
    this.onExtraerAnimal = onExtraerAnimal;
    this.onReactivarAnimal = onReactivarAnimal;
    this.onTrasladarAFinca = onTrasladarAFinca || onTrasladar;

    this.filtroBusqueda = '';
    this.filtroEspecie = 'todas'; // 'todas' | 'bovino' | 'bufalino'
    this.filtroLote = 'todos';
    this.filtroRepro = 'todos';
    this.filtroSexo = 'todos';
    this.filtroRaza = 'todas';
    this.filtroEstadoVida = 'activos'; // 'activos' | 'vendidos' | 'muertos' | 'todos'

    this.modalNuevoAbierto = false;
    this.animalEditando = null;
  }

  abrirModalEditar(animal) {
    this.animalEditando = animal;
    this.render();
  }

  init() {
    this.render();
  }

  render() {
    if (!this.container) return;

    const rol = this.getRol ? this.getRol() : 'administrador';
    const esSoloConsulta = rol === 'consulta' || rol === 'propietario' || rol === 'consultor';

    const todosAnimales = this.getAnimales ? this.getAnimales() : [];
    const lotes = this.getLotes ? this.getLotes() : [];
    const razas = [...new Set(todosAnimales.map((a) => (a.raza || '').trim()).filter(Boolean))]
      .sort((a, b) => a.localeCompare(b, 'es', { sensitivity: 'base' }));

    // Aplicar filtros
    let lista = todosAnimales;
    if (this.filtroEstadoVida === 'activos') {
      lista = lista.filter((a) => a.estadoVida === 'activo' || a.estado === 'activo');
    } else if (this.filtroEstadoVida === 'vendidos') {
      lista = lista.filter((a) => (a.motivoBaja || '').toLowerCase() === 'venta');
    } else if (this.filtroEstadoVida === 'muertos') {
      lista = lista.filter((a) => (a.motivoBaja || '').toLowerCase() === 'muerte');
    }

    if (this.filtroEspecie !== 'todas') {
      lista = lista.filter((a) => (a.especie || 'bovino').toLowerCase() === this.filtroEspecie);
    }

    if (this.filtroLote !== 'todos') {
      lista = lista.filter((a) => (a.lote || 'General') === this.filtroLote);
    }

    if (this.filtroRepro !== 'todos') {
      lista = lista.filter((a) => {
        const est = (a.estadoReproductivo || '').toLowerCase();
        if (this.filtroRepro === 'prenada') return est.includes('prenad') || est.includes('preñad');
        if (this.filtroRepro === 'vacia') return est.includes('vaci') || est.includes('vací');
        if (this.filtroRepro === 'no_aplica') return est.includes('no');
        return true;
      });
    }

    if (this.filtroSexo !== 'todos') {
      lista = lista.filter((a) => (a.sexo || '').toLowerCase() === this.filtroSexo);
    }

    if (this.filtroRaza !== 'todas') {
      const fRaza = this.filtroRaza.toLowerCase();
      lista = lista.filter((a) => {
        const r = (a.raza || '').trim().toLowerCase();
        return r === fRaza || r.includes(fRaza) || fRaza.includes(r);
      });
    }

    if (this.filtroBusqueda.trim().length > 0) {
      const q = this.filtroBusqueda.trim().toLowerCase();
      lista = lista.filter(
        (a) =>
          (a.identificacionTag || a.numero || '').toLowerCase().includes(q) ||
          (a.nombreAlias || a.nombre || '').toLowerCase().includes(q) ||
          (a.padreTag || a.padre || '').toLowerCase().includes(q) ||
          (a.madreTag || a.madre || '').toLowerCase().includes(q) ||
          (a.raza || '').toLowerCase().includes(q)
      );
    }

    this.container.innerHTML = `
      <div class="bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden">
        <!-- HEADER PESTAÑA -->
        <div class="bg-gradient-to-r from-slate-950 via-slate-900 to-slate-950 text-white p-4 sm:p-5 space-y-4">
          <div class="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3">
            <div class="flex items-center gap-3">
              <div class="w-11 h-11 rounded-2xl bg-emerald-600/20 text-emerald-400 border border-emerald-500/30 flex items-center justify-center text-2xl shadow-inner">
                🏷️
              </div>
              <div>
                <h2 class="text-base sm:text-lg font-black tracking-tight flex items-center gap-2">
                  <span>Inventario General de Animales</span>
                  <span id="contador-animales-pestana" class="text-[10px] uppercase font-mono px-2 py-0.5 rounded bg-emerald-500/20 text-emerald-300 border border-emerald-400/30 font-bold">
                    ${lista.length} de ${todosAnimales.length} Ejemplares
                  </span>
                </h2>
                <p class="text-xs text-slate-400 mt-0.5">Listado detallado con genealogía (padre, madre), especie, días de preñez, partos y trazabilidad.</p>
              </div>
            </div>

            <!-- BOTÓN TRASLADAR Y AGREGAR ANIMAL (Oculto en Solo Consulta) -->
            ${!esSoloConsulta ? `
              <div class="flex items-center gap-2 flex-wrap w-full sm:w-auto">
                <button id="btn-abrir-traslados-pestana" class="flex-1 sm:flex-none px-3.5 py-2.5 bg-purple-600 hover:bg-purple-500 active:scale-95 text-white font-black text-xs rounded-xl shadow-lg transition flex items-center justify-center gap-1.5 cursor-pointer" title="Módulo de traslado de animales entre predios">
                  <span>🚚</span> Trasladar
                </button>
                <button id="btn-abrir-modal-nuevo-animal" class="flex-1 sm:flex-none px-3.5 py-2.5 bg-emerald-600 hover:bg-emerald-500 active:scale-95 text-white font-black text-xs rounded-xl shadow-lg transition flex items-center justify-center gap-1.5 cursor-pointer">
                  <span>➕</span> Nuevo Animal
                </button>
              </div>
            ` : `
              <div class="text-[11px] font-bold text-amber-300 bg-amber-950/60 px-3 py-1.5 rounded-xl border border-amber-500/40 flex items-center gap-1.5">
                <span>👁️</span> Modo Consulta: Modificaciones Deshabilitadas
              </div>
            `}
          </div>
        </div>

        <!-- SECCIÓN DE BÚSQUEDA RÁPIDA EXACTA A LA CUADRÍCULA MASIVA -->
        <div class="p-3.5 sm:p-5 bg-emerald-50/50 border-b border-emerald-100">
          <div class="max-w-3xl mx-auto space-y-3">
            <!-- BUSCADOR RÁPIDO DE ARETE CON BOTÓN BUSCAR QUE ABRE FICHA -->
            <form id="form-buscar-animal-directo" class="flex flex-col sm:flex-row items-center gap-2.5 sm:gap-3">
              <div class="relative w-full">
                <span class="absolute left-3.5 top-3.5 text-slate-400 text-sm">🔍</span>
                <input 
                  type="text" 
                  id="input-tag-animal-directo" 
                  placeholder="Digite o escanee No. de animal (Ej. BV-401, 102)..." 
                  value="${this.filtroBusqueda || ''}"
                  class="w-full pl-10 pr-4 py-3 bg-white text-slate-900 font-mono font-black text-base rounded-xl border-2 border-emerald-500 focus:ring-4 focus:ring-emerald-500/20 outline-none uppercase shadow-sm"
                  autocomplete="off"
                >
              </div>
              <button 
                type="submit" 
                id="btn-buscar-animal-directo" 
                class="w-full sm:w-auto px-7 py-3 bg-emerald-600 hover:bg-emerald-500 text-white font-black text-sm rounded-xl shadow transition whitespace-nowrap active:scale-95 flex items-center justify-center gap-2 cursor-pointer"
              >
                <span>🔍</span> Buscar
              </button>
            </form>

            <!-- FILTROS COMPLEMENTARIOS Y RESET -->
            <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2.5 text-xs pt-1 text-slate-600">
              <div class="grid grid-cols-2 sm:flex sm:flex-wrap items-center gap-1.5 sm:gap-2">
                <select id="select-filtro-estado-pestana" class="w-full sm:w-auto px-2 py-2 sm:py-1 bg-white border border-slate-300 rounded-xl text-xs font-bold text-slate-700 outline-none cursor-pointer">
                  <option value="activos" ${this.filtroEstadoVida === 'activos' ? 'selected' : ''}>🟢 Activos (En Hato)</option>
                  <option value="vendidos" ${this.filtroEstadoVida === 'vendidos' ? 'selected' : ''}>💰 Vendidos</option>
                  <option value="muertos" ${this.filtroEstadoVida === 'muertos' ? 'selected' : ''}>☠️ Muertes</option>
                  <option value="todos" ${this.filtroEstadoVida === 'todos' ? 'selected' : ''}>📋 Todos (Histórico)</option>
                </select>
                <select id="select-filtro-especie-pestana" class="w-full sm:w-auto px-2 py-2 sm:py-1 bg-white border border-slate-300 rounded-xl text-xs font-bold text-slate-700 outline-none cursor-pointer">
                  <option value="todas" ${this.filtroEspecie === 'todas' ? 'selected' : ''}>Todas Especies</option>
                  <option value="bovino" ${this.filtroEspecie === 'bovino' ? 'selected' : ''}>🐂 Vacunos</option>
                  <option value="bufalino" ${this.filtroEspecie === 'bufalino' ? 'selected' : ''}>🦬 Bufalinos</option>
                </select>
                <select id="select-filtro-lote-pestana" class="w-full sm:w-auto px-2 py-2 sm:py-1 bg-white border border-slate-300 rounded-xl text-xs font-bold text-slate-700 outline-none cursor-pointer">
                  <option value="todos" ${this.filtroLote === 'todos' ? 'selected' : ''}>Todos Lotes</option>
                  ${lotes.map((l) => `<option value="${l}" ${this.filtroLote === l ? 'selected' : ''}>${l}</option>`).join('')}
                </select>
                <select id="select-filtro-repro-pestana" class="w-full sm:w-auto px-2 py-2 sm:py-1 bg-white border border-slate-300 rounded-xl text-xs font-bold text-slate-700 outline-none cursor-pointer">
                  <option value="todos" ${this.filtroRepro === 'todos' ? 'selected' : ''}>Todos Estados</option>
                  <option value="prenada" ${this.filtroRepro === 'prenada' ? 'selected' : ''}>🟢 Preñadas</option>
                  <option value="vacia" ${this.filtroRepro === 'vacia' ? 'selected' : ''}>⚪ Vacías</option>
                  <option value="no_aplica" ${this.filtroRepro === 'no_aplica' ? 'selected' : ''}>⚪ Machos</option>
                </select>
                <select id="select-filtro-raza-pestana" class="w-full sm:w-auto px-2 py-2 sm:py-1 bg-white border border-slate-300 rounded-xl text-xs font-bold text-slate-700 outline-none cursor-pointer">
                  <option value="todas" ${this.filtroRaza === 'todas' ? 'selected' : ''}>Todas Razas</option>
                  ${razas.map((r) => `<option value="${r}" ${this.filtroRaza.toLowerCase() === r.toLowerCase() ? 'selected' : ''}>🧬 ${r}</option>`).join('')}
                </select>
              </div>

              <div class="flex items-center justify-between sm:justify-end gap-2">
                ${this.filtroBusqueda ? `
                  <button id="btn-limpiar-busqueda-pestana" class="text-xs font-bold text-rose-600 hover:underline flex items-center gap-1 cursor-pointer">
                    ✕ Limpiar ("${this.filtroBusqueda}")
                  </button>
                ` : `
                  <span id="subtexto-contador-pestana" class="text-[11px] text-slate-500 font-medium">Mostrando ${lista.length} ejemplares</span>
                `}
              </div>
            </div>
          </div>
        </div>

        <!-- TABLA DE ANIMALES (DESKTOP) -->
        <div class="hidden md:block overflow-x-auto">
          <table class="w-full text-left text-xs">
            <thead class="bg-slate-100 text-slate-700 uppercase font-black text-[10px] border-b border-slate-200">
              <tr>
                <th class="p-3">Arete / Especie</th>
                <th class="p-3">Nombre & Raza</th>
                <th class="p-3">Categoría & Lote</th>
                <th class="p-3">Padre & Madre (Pedigree)</th>
                <th class="p-3">Nacimiento & Edad</th>
                <th class="p-3">Estado Reproductivo</th>
                <th class="p-3">Último Parto & IEP</th>
                <th class="p-3 text-right">Peso & GDP</th>
                <th class="p-3 text-center">Acciones</th>
              </tr>
            </thead>
            <tbody id="tbody-animales-pestana" class="divide-y divide-slate-100 font-medium">
              ${lista.length > 0 ? lista.map((a) => this.renderFilaAnimal(a, esSoloConsulta)).join('') : this.renderFilaVacia()}
            </tbody>
          </table>
        </div>

        <!-- LISTADO DE TARJETAS MÓVILES (CELULARES) -->
        <div id="contenedor-tarjetas-mobile" class="md:hidden divide-y divide-slate-100 p-2.5 sm:p-3 space-y-2.5">
          ${lista.length > 0 ? lista.map((a) => this.renderTarjetaAnimalMobile(a, esSoloConsulta)).join('') : this.renderTarjetaVaciaMobile()}
        </div>

        <!-- MODAL "+ NUEVO ANIMAL" -->
        ${this.modalNuevoAbierto ? this.renderModalNuevoAnimal(lotes) : ''}
        <!-- MODAL "✏️ EDITAR ANIMAL" -->
        ${this.animalEditando ? this.renderModalEditarAnimal(lotes) : ''}
      </div>
    `;

    this.attachEvents();
  }

  renderFilaAnimal(a, esSoloConsulta) {
    const tag = a.identificacionTag || a.numero;
    const especie = (a.especie || 'bovino').toLowerCase();
    const esBufalo = especie === 'bufalino';
    const edadMeses = calcularEdadMeses(a.fechaNacimiento);
    const edadAnios = (edadMeses / 12).toFixed(1);

    const fParto = a.fechaUltimoParto || a.ultimoParto;
    const diasAbiertos = calcularDiasAbiertos(fParto, a.estadoReproductivo);
    const iep = calcularIEP(diasAbiertos, especie);
    const estaPrenada = (a.estadoReproductivo || '').toLowerCase().includes('prenad') || (a.estadoReproductivo || '').toLowerCase().includes('preñad');
    const diasG = parseInt(a.diasGestacionActual || a.diasGestacion || 0);

    const esInactivo = (a.estadoVida || a.estado) === 'inactivo' || Boolean(a.motivoBaja);
    const motivoBaja = (a.motivoBaja || '').toLowerCase();

    return `
      <tr class="${esInactivo ? 'opacity-65 bg-slate-50/80 text-slate-500' : 'hover:bg-slate-50'} transition items-center">
        <!-- Arete & Especie -->
        <td class="p-3">
          <div class="flex items-center gap-2">
            <span class="text-lg">${esBufalo ? '🦬' : '🐂'}</span>
            <div>
              <span class="font-black font-mono text-slate-900 text-sm block">${tag}</span>
              <div class="flex items-center gap-1 mt-0.5">
                <span class="text-[9px] font-bold px-1.5 py-0.2 rounded ${esBufalo ? 'bg-amber-100 text-amber-800' : 'bg-blue-100 text-blue-800'}">
                  ${esBufalo ? 'Bufalino' : 'Vacuno'}
                </span>
                ${esInactivo ? `
                  <span class="text-[9px] font-bold px-1.5 py-0.2 rounded bg-rose-100 text-rose-800 border border-rose-200">
                    🚪 ${motivoBaja === 'venta' ? 'Vendido' : (motivoBaja === 'muerte' ? 'Muerto' : 'Extraído')}
                  </span>
                ` : ''}
              </div>
            </div>
          </div>
        </td>

        <!-- Nombre & Raza -->
        <td class="p-3">
          <div class="font-bold text-slate-800">${a.nombreAlias || a.nombre || 'Sin Alias'}</div>
          <div class="text-[10px] text-slate-500">${a.raza || 'Común'} • ${a.sexo === 'hembra' ? '♀️ Hembra' : '♂️ Macho'}</div>
        </td>

        <!-- Categoría & Lote -->
        <td class="p-3">
          <div class="font-bold text-slate-700">${a.categoria || 'Sin Categoría'}</div>
          <span class="inline-block mt-0.5 px-2 py-0.5 rounded text-[10px] bg-slate-100 text-slate-600 font-medium">
            📍 ${a.lote || 'General'}
          </span>
        </td>

        <!-- Genealogía: Padre & Madre -->
        <td class="p-3">
          <div class="text-[11px] font-mono">
            <span class="text-slate-400 font-bold">P:</span> <strong class="text-slate-800">${a.padreTag || a.padre || 'Desc.'}</strong>
          </div>
          <div class="text-[11px] font-mono mt-0.5">
            <span class="text-slate-400 font-bold">M:</span> <strong class="text-slate-800">${a.madreTag || a.madre || 'Desc.'}</strong>
          </div>
        </td>

        <!-- Nacimiento & Edad -->
        <td class="p-3">
          <div class="font-bold text-slate-800">${a.fechaNacimiento || '-'}</div>
          <div class="text-[10px] text-slate-500">${edadMeses > 0 ? `${edadMeses} m (${edadAnios} a)` : 'Sin fecha'}</div>
        </td>

        <!-- Estado Reproductivo & Días de Preñez -->
        <td class="p-3">
          ${estaPrenada ? `
            <div class="inline-flex flex-col">
              <span class="px-2 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800 border border-emerald-300 flex items-center gap-1 w-fit">
                <span>🟢</span> Preñada
              </span>
              <span class="text-xs font-black font-mono text-emerald-700 mt-1">
                ${diasG} Días de Preñez
              </span>
              <span class="text-[9px] text-slate-400">~${Math.round(diasG / 30.4)} meses</span>
            </div>
          ` : `
            <div class="inline-flex flex-col">
              <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${a.estadoReproductivo === 'No Aplica' ? 'bg-slate-100 text-slate-600' : 'bg-rose-100 text-rose-800 border border-rose-200'} w-fit">
                ${a.estadoReproductivo || 'Vacía'}
              </span>
              ${a.sexo === 'hembra' && diasAbiertos > 0 ? `
                <span class="text-[10px] font-mono text-slate-500 mt-0.5">${diasAbiertos} Días Abiertos</span>
              ` : ''}
            </div>
          `}
        </td>

        <!-- Último Parto & IEP -->
        <td class="p-3">
          <div class="font-bold text-slate-800">${fParto || 'Sin partos'}</div>
          <div class="text-[10px] text-slate-500 mt-0.5">
            ${fParto ? `IEP: <strong class="text-slate-700">${iep.dias}d</strong> (${iep.meses}m)` : 'Primeriza'}
          </div>
        </td>

        <!-- Peso Actual & GDP -->
        <td class="p-3 text-right">
          <span class="font-black font-mono text-slate-900 text-sm">
            ${a.ultimoPesoKg || a.pesoActual ? `${a.ultimoPesoKg || a.pesoActual} kg` : '-'}
          </span>
          <div class="text-[10px] font-bold mt-0.5 ${a.gdpPromedioGDia < 300 ? 'text-rose-600' : 'text-emerald-700'}">
            ${a.gdpPromedioGDia !== undefined ? `${a.gdpPromedioGDia} g/d` : '-'}
          </div>
        </td>

        <!-- Acciones -->
        <td class="p-3 text-center">
          <div class="flex items-center justify-center gap-1.5">
            <button class="btn-ver-ficha-animal px-2.5 py-1.5 rounded-xl bg-slate-900 hover:bg-slate-800 text-white font-bold text-[11px] shadow transition flex items-center gap-1 cursor-pointer" data-id="${a.id}" title="Ver Ficha Zootécnica">
              <span>🔍</span> Ficha
            </button>
            ${esInactivo ? `
              <button class="btn-reactivar-fila-animal px-2 py-1.5 rounded-xl bg-emerald-50 hover:bg-emerald-100 text-emerald-700 font-bold text-[11px] shadow-sm transition flex items-center gap-1 cursor-pointer" data-id="${a.id}" data-tag="${tag}" title="Reactivar ejemplar en el hato">
                <span>🔄</span> Reactivar
              </button>
            ` : (!esSoloConsulta ? `
              <button class="btn-extraer-fila-animal px-2 py-1.5 rounded-xl bg-rose-50 hover:bg-rose-100 text-rose-700 font-bold text-[11px] shadow-sm transition flex items-center gap-1 cursor-pointer" data-id="${a.id}" data-tag="${tag}" title="Extraer animal por Venta o Muerte">
                <span>🚪</span>
              </button>
              <button class="btn-trasladar-animal px-2 py-1.5 rounded-xl bg-purple-50 hover:bg-purple-100 text-purple-700 font-bold text-[11px] shadow-sm transition flex items-center gap-1 cursor-pointer" data-id="${a.id}" title="Trasladar este animal a otra finca">
                <span>🚚</span>
              </button>
              <button class="btn-editar-animal px-2 py-1.5 rounded-xl bg-blue-50 hover:bg-blue-100 text-blue-700 font-bold text-[11px] shadow-sm transition flex items-center gap-1 cursor-pointer" data-id="${a.id}" title="Modificar cualquier dato de este animal">
                <span>✏️</span>
              </button>
              <button class="btn-eliminar-animal p-1.5 rounded-xl bg-rose-50 hover:bg-rose-100 text-rose-600 transition cursor-pointer" data-id="${a.id}" data-tag="${tag}" title="Eliminar animal">
                🗑️
              </button>
            ` : '')}
          </div>
        </td>
      </tr>
    `;
  }

  renderFilaVacia() {
    return `
      <tr>
        <td colspan="9" class="p-8 text-center text-slate-400">
          <span class="text-3xl block mb-2">🐄</span>
          No se encontraron animales registrados con los filtros aplicados.
        </td>
      </tr>
    `;
  }

  renderTarjetaAnimalMobile(a, esSoloConsulta) {
    const tag = a.identificacionTag || a.numero;
    const especie = (a.especie || 'bovino').toLowerCase();
    const esBufalo = especie === 'bufalino';
    const edadMeses = calcularEdadMeses(a.fechaNacimiento);
    const edadAnios = (edadMeses / 12).toFixed(1);

    const fParto = a.fechaUltimoParto || a.ultimoParto;
    const diasAbiertos = calcularDiasAbiertos(fParto, a.estadoReproductivo);
    const iep = calcularIEP(diasAbiertos, especie);
    const estaPrenada = (a.estadoReproductivo || '').toLowerCase().includes('prenad') || (a.estadoReproductivo || '').toLowerCase().includes('preñad');
    const diasG = parseInt(a.diasGestacionActual || a.diasGestacion || 0);

    const esInactivo = (a.estadoVida || a.estado) === 'inactivo' || Boolean(a.motivoBaja);
    const motivoBaja = (a.motivoBaja || '').toLowerCase();

    return `
      <div class="card-animal-mobile p-3.5 bg-white border border-slate-200/80 rounded-2xl shadow-sm space-y-2.5 ${esInactivo ? 'opacity-65 bg-slate-50/80 text-slate-500' : ''}">
        <!-- CABECERA DE LA TARJETA: Tag, Nombre, Sexo, Especie, Peso -->
        <div class="flex items-start justify-between gap-2">
          <div class="flex items-center gap-2">
            <span class="text-2xl shrink-0">${esBufalo ? '🦬' : '🐂'}</span>
            <div>
              <div class="flex items-center gap-1.5 flex-wrap">
                <span class="font-black font-mono text-slate-950 text-base tracking-tight">${tag}</span>
                <span class="text-[9px] font-bold px-2 py-0.5 rounded-full ${esBufalo ? 'bg-amber-100 text-amber-900' : 'bg-blue-100 text-blue-900'}">
                  ${esBufalo ? 'Bufalino' : 'Vacuno'}
                </span>
                <span class="text-[9px] font-bold px-1.5 py-0.5 rounded bg-slate-100 text-slate-700">
                  ${a.sexo === 'hembra' ? '♀️' : '♂️'}
                </span>
                ${esInactivo ? `
                  <span class="text-[9px] font-bold px-2 py-0.5 rounded-full bg-rose-100 text-rose-800 border border-rose-200">
                    🚪 ${motivoBaja === 'venta' ? 'Vendido' : (motivoBaja === 'muerte' ? 'Muerto' : 'Extraído')}
                  </span>
                ` : ''}
              </div>
              <h3 class="font-bold text-slate-800 text-sm mt-0.5">${a.nombreAlias || a.nombre || 'Sin Alias'}</h3>
            </div>
          </div>
          <div class="text-right shrink-0">
            <span class="inline-block px-2.5 py-1 rounded-xl text-xs font-mono font-black bg-slate-900 text-white shadow-sm">
              ${a.ultimoPesoKg || a.pesoActual ? `${a.ultimoPesoKg || a.pesoActual} kg` : '-'}
            </span>
            ${a.gdpPromedioGDia !== undefined ? `
              <div class="text-[10px] font-bold mt-0.5 ${a.gdpPromedioGDia < 300 ? 'text-rose-600' : 'text-emerald-700'}">
                ${a.gdpPromedioGDia} g/d
              </div>
            ` : ''}
          </div>
        </div>

        <!-- DETALLES ZOOTÉCNICOS EN GRID DE 2 COLUMNAS -->
        <div class="grid grid-cols-2 gap-2 text-xs bg-slate-50 p-2.5 rounded-xl border border-slate-100">
          <div>
            <span class="text-[9px] uppercase font-bold text-slate-400 block">Raza & Lote</span>
            <span class="font-bold text-slate-800 truncate block">${a.raza || 'Común'}</span>
            <span class="text-[10px] text-slate-500 block truncate">${a.categoria || 'General'} • 📍 ${a.lote || 'General'}</span>
          </div>

          <div>
            <span class="text-[9px] uppercase font-bold text-slate-400 block">Reproductivo</span>
            ${estaPrenada ? `
              <span class="inline-flex items-center gap-1 font-black text-emerald-700">
                <span>🟢</span> Preñada (${diasG}d)
              </span>
            ` : `
              <span class="font-bold text-slate-700">
                ${a.estadoReproductivo || 'Vacía'}
              </span>
            `}
            <span class="text-[10px] text-slate-500 block">
              ${fParto ? `Parto: ${fParto}` : `${edadMeses} m`}
            </span>
          </div>
        </div>

        <!-- PEDIGREE COMPACTO -->
        <div class="flex items-center justify-between text-[11px] font-mono text-slate-600 px-1">
          <div><span class="text-slate-400">P:</span> <strong class="text-slate-800">${a.padreTag || a.padre || 'Desc.'}</strong></div>
          <div><span class="text-slate-400">M:</span> <strong class="text-slate-800">${a.madreTag || a.madre || 'Desc.'}</strong></div>
        </div>

        <!-- BOTONES DE ACCIÓN ERGONÓMICOS (TOUCH FRIENDLY) -->
        <div class="flex items-center gap-2 pt-1 border-t border-slate-100">
          <button class="btn-ver-ficha-animal flex-1 py-2.5 px-3 rounded-xl bg-slate-900 hover:bg-slate-800 text-white font-bold text-xs shadow transition flex items-center justify-center gap-1.5 active:scale-95 cursor-pointer" data-id="${a.id}">
            <span>🔍</span> Ficha
          </button>
          ${esInactivo ? `
            <button class="btn-reactivar-fila-animal flex-1 py-2.5 px-3 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-xs shadow transition flex items-center justify-center gap-1.5 active:scale-95 cursor-pointer" data-id="${a.id}" data-tag="${tag}">
              <span>🔄</span> Reactivar
            </button>
          ` : (!esSoloConsulta ? `
            <button class="btn-extraer-fila-animal p-2.5 rounded-xl bg-rose-100 hover:bg-rose-200 text-rose-800 font-bold text-xs shadow-sm transition flex items-center justify-center active:scale-95 cursor-pointer" data-id="${a.id}" data-tag="${tag}" title="Extraer">
              <span>🚪</span>
            </button>
            <button class="btn-trasladar-animal p-2.5 rounded-xl bg-purple-100 hover:bg-purple-200 text-purple-800 font-bold text-xs shadow-sm transition flex items-center justify-center active:scale-95 cursor-pointer" data-id="${a.id}" title="Trasladar">
              <span>🚚</span>
            </button>
            <button class="btn-editar-animal p-2.5 rounded-xl bg-blue-100 hover:bg-blue-200 text-blue-800 font-bold text-xs shadow-sm transition flex items-center justify-center active:scale-95 cursor-pointer" data-id="${a.id}" title="Editar">
              <span>✏️</span>
            </button>
            <button class="btn-eliminar-animal p-2.5 rounded-xl bg-rose-100 hover:bg-rose-200 text-rose-700 font-bold text-xs shadow-sm transition flex items-center justify-center active:scale-95 cursor-pointer" data-id="${a.id}" data-tag="${tag}" title="Eliminar">
              <span>🗑️</span>
            </button>
          ` : '')}
        </div>
      </div>
    `;
  }

  renderTarjetaVaciaMobile() {
    return `
      <div class="p-8 text-center text-slate-400 bg-white rounded-2xl border border-slate-200">
        <span class="text-3xl block mb-2">🐄</span>
        No se encontraron animales registrados con los filtros aplicados.
      </div>
    `;
  }

  renderModalNuevoAnimal(lotes) {
    return `
      <div class="fixed inset-0 bg-slate-950/80 backdrop-blur-sm z-50 flex items-center justify-center p-0 sm:p-5 overflow-y-auto">
        <div class="bg-white rounded-none sm:rounded-3xl shadow-2xl border border-slate-200 max-w-2xl w-full h-full sm:h-auto sm:max-h-[95vh] flex flex-col modal-fullscreen-mobile">
          <!-- CABECERA MODAL -->
          <div class="bg-gradient-to-r from-slate-950 via-slate-900 to-slate-950 text-white p-5 flex justify-between items-center">
            <div class="flex items-center gap-3">
              <span class="text-2xl p-2 bg-emerald-600/30 rounded-xl border border-emerald-500/40">➕</span>
              <div>
                <h3 class="text-base font-black tracking-tight">Registrar Nuevo Ejemplar</h3>
                <p class="text-xs text-slate-400">Ingreso individual al inventario con datos genealógicos y reproductivos.</p>
              </div>
            </div>
            <button id="btn-cerrar-modal-nuevo" class="p-2 rounded-xl bg-slate-800 text-slate-300 hover:text-white transition">
              ✕
            </button>
          </div>

          <!-- FORMULARIO -->
          <form id="form-nuevo-animal" class="p-5 sm:p-6 overflow-y-auto space-y-4 text-xs flex-1">
            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
              <!-- Arete -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Número de Arete / Tag *:</label>
                <input type="text" id="nuevo-tag" required placeholder="Ej. BV-650" class="w-full px-3 py-2 font-mono font-bold rounded-xl border border-slate-300 outline-none uppercase focus:border-emerald-500">
              </div>

              <!-- Especie -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Especie *:</label>
                <select id="nuevo-especie" class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none bg-white">
                  <option value="bovino">🐂 Vacuno (Bovino)</option>
                  <option value="bufalino">🦬 Bufalino (Búfalo)</option>
                </select>
              </div>

              <!-- Nombre / Alias -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Nombre / Alias:</label>
                <input type="text" id="nuevo-nombre" placeholder="Ej. Princesa" class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none">
              </div>

              <!-- Sexo -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Sexo *:</label>
                <select id="nuevo-sexo" class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none bg-white">
                  <option value="hembra">♀️ Hembra</option>
                  <option value="macho">♂️ Macho</option>
                </select>
              </div>

              <!-- Raza -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Raza:</label>
                <input type="text" id="nuevo-raza" placeholder="Ej. Brahman Blanco, Gyr, Murrah..." class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none">
              </div>

              <!-- Categoría -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Categoría:</label>
                <select id="nuevo-categoria" class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none bg-white">
                  <option value="Vaca de Ordeño">Vaca de Ordeño</option>
                  <option value="Vaca Horra">Vaca Horra / Seca</option>
                  <option value="Novilla de Vientre">Novilla de Vientre</option>
                  <option value="Novillo de Ceba">Novillo de Ceba</option>
                  <option value="Ternero / Ternera">Ternero / Ternera</option>
                  <option value="Toro Reproductor">Toro Reproductor</option>
                </select>
              </div>

              <!-- Lote -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Lote de Destino:</label>
                <input type="text" id="nuevo-lote" list="lotes-existentes" placeholder="General" class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none">
                <datalist id="lotes-existentes">
                  ${lotes.map((l) => `<option value="${l}"></option>`).join('')}
                </datalist>
              </div>

              <!-- Fecha de Nacimiento -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Fecha de Nacimiento:</label>
                <input type="date" id="nuevo-nacimiento" class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none">
              </div>

              <!-- Padre -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Padre (Toro / Tag):</label>
                <input type="text" id="nuevo-padre" placeholder="Ej. TORO-01 o Pajilla 883" class="w-full px-3 py-2 font-mono font-bold rounded-xl border border-slate-300 outline-none uppercase">
              </div>

              <!-- Madre -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Madre (Vaca / Tag):</label>
                <input type="text" id="nuevo-madre" placeholder="Ej. BV-102" class="w-full px-3 py-2 font-mono font-bold rounded-xl border border-slate-300 outline-none uppercase">
              </div>

              <!-- Peso Actual (Kg) -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Peso Inicial / Actual (Kg):</label>
                <input type="number" step="0.5" id="nuevo-peso" placeholder="Ej. 420" class="w-full px-3 py-2 font-mono font-bold rounded-xl border border-slate-300 outline-none">
              </div>

              <!-- Estado Reproductivo -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Estado Reproductivo:</label>
                <select id="nuevo-repro" class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none bg-white">
                  <option value="Vacía">⚪ Vacía</option>
                  <option value="Preñada">🟢 Preñada (Gestante)</option>
                  <option value="No Aplica">⚪ No Aplica (Macho/Cría)</option>
                </select>
              </div>

              <!-- Días de Preñez (Condicional) -->
              <div id="wrapper-nuevo-dias-prened" class="hidden">
                <label class="block font-bold text-emerald-800 mb-1">Días de Preñez / Gestación:</label>
                <input type="number" id="nuevo-dias-gestacion" value="60" min="0" max="315" class="w-full px-3 py-2 font-mono font-bold rounded-xl border border-emerald-300 bg-emerald-50 outline-none">
                <span class="text-[10px] text-emerald-700 block mt-0.5">Días calculados desde la monta o inseminación.</span>
              </div>

              <!-- Fecha de Último Parto -->
              <div id="wrapper-nuevo-parto">
                <label class="block font-bold text-slate-700 mb-1">Fecha Último Parto (si aplica):</label>
                <input type="date" id="nuevo-ultimo-parto" class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none">
              </div>
            </div>

            <!-- BOTONES ACCIÓN -->
            <div class="pt-4 border-t border-slate-200 flex justify-end gap-2">
              <button type="button" id="btn-cancelar-nuevo-animal" class="px-4 py-2 rounded-xl bg-slate-100 hover:bg-slate-200 font-bold text-slate-700 transition">
                Cancelar
              </button>
              <button type="submit" class="px-5 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-500 font-black text-white shadow-lg transition">
                Guardar Animal
              </button>
            </div>
          </form>
        </div>
      </div>
    `;
  }

  renderModalEditarAnimal(lotes = []) {
    const a = this.animalEditando;
    if (!a) return '';

    const tag = a.identificacionTag || a.numero || a.tag || '';
    const especie = (a.especie || 'bovino').toLowerCase();
    const nombre = a.nombreAlias || a.nombre || '';
    const sexo = (a.sexo || 'hembra').toLowerCase();
    const raza = a.raza || '';
    const categoria = a.categoria || 'Vaca de Ordeño';
    const lote = a.lote || 'General';
    const fNac = a.fechaNacimiento || '';
    const padre = a.genealogiaPadre || a.padre || a.padreTag || '';
    const madre = a.genealogiaMadre || a.madre || a.madreTag || '';
    const peso = a.ultimoPesoKg || a.pesoActual || '';
    const repro = a.estadoReproductivo || 'Vacía';
    const diasG = a.diasGestacionActual || a.diasGestacion || 0;
    const fParto = a.fechaUltimoParto || a.ultimoParto || '';
    const condicion = a.condicionCorporal || '3.5';

    const esPrenada = repro.toLowerCase().includes('prenad') || repro.toLowerCase().includes('preñad');

    return `
      <div class="fixed inset-0 bg-slate-950/80 backdrop-blur-sm z-50 flex items-center justify-center p-0 sm:p-5 overflow-y-auto">
        <div class="bg-white rounded-none sm:rounded-3xl shadow-2xl border border-slate-200 max-w-2xl w-full h-full sm:h-auto sm:max-h-[95vh] flex flex-col modal-fullscreen-mobile">
          <!-- CABECERA MODAL -->
          <div class="bg-gradient-to-r from-slate-950 via-blue-950 to-slate-950 text-white p-5 flex justify-between items-center">
            <div class="flex items-center gap-3">
              <span class="text-2xl p-2 bg-blue-600/30 rounded-xl border border-blue-500/40">✏️</span>
              <div>
                <h3 class="text-base font-black tracking-tight">Modificar Datos del Ejemplar: ${tag}</h3>
                <p class="text-xs text-slate-400">Edita cualquier dato genealógico, zootécnico, de peso o reproductivo.</p>
              </div>
            </div>
            <button id="btn-cerrar-modal-editar-animal" class="p-2 rounded-xl bg-slate-800 text-slate-300 hover:text-white transition cursor-pointer">
              ✕
            </button>
          </div>

          <!-- FORMULARIO -->
          <form id="form-editar-animal" class="p-5 sm:p-6 overflow-y-auto space-y-4 text-xs flex-1">
            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
              <!-- Arete -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Número de Arete / Tag *:</label>
                <input type="text" id="edit-tag" required value="${tag}" class="w-full px-3 py-2 font-mono font-bold rounded-xl border border-slate-300 outline-none uppercase focus:border-blue-500">
              </div>

              <!-- Especie -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Especie *:</label>
                <select id="edit-especie" class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none bg-white">
                  <option value="bovino" ${especie === 'bovino' ? 'selected' : ''}>🐂 Vacuno (Bovino)</option>
                  <option value="bufalino" ${especie === 'bufalino' ? 'selected' : ''}>🦬 Bufalino (Búfalo)</option>
                </select>
              </div>

              <!-- Nombre / Alias -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Nombre / Alias:</label>
                <input type="text" id="edit-nombre" value="${nombre}" placeholder="Ej. Princesa" class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none">
              </div>

              <!-- Sexo -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Sexo *:</label>
                <select id="edit-sexo" class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none bg-white">
                  <option value="hembra" ${sexo === 'hembra' ? 'selected' : ''}>♀️ Hembra</option>
                  <option value="macho" ${sexo === 'macho' ? 'selected' : ''}>♂️ Macho</option>
                </select>
              </div>

              <!-- Raza -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Raza:</label>
                <input type="text" id="edit-raza" value="${raza}" placeholder="Ej. Brahman Blanco, Gyr, Murrah..." class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none">
              </div>

              <!-- Categoría -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Categoría:</label>
                <select id="edit-categoria" class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none bg-white">
                  <option value="Vaca de Ordeño" ${categoria === 'Vaca de Ordeño' || categoria === 'Vaca en Producción' ? 'selected' : ''}>Vaca de Ordeño / Producción</option>
                  <option value="Vaca Horra" ${categoria === 'Vaca Horra' ? 'selected' : ''}>Vaca Horra / Seca</option>
                  <option value="Novilla de Vientre" ${categoria === 'Novilla de Vientre' ? 'selected' : ''}>Novilla de Vientre</option>
                  <option value="Novillo de Ceba" ${categoria === 'Novillo de Ceba' ? 'selected' : ''}>Novillo de Ceba</option>
                  <option value="Ternero / Ternera" ${categoria === 'Ternero / Ternera' || categoria === 'Ternera' ? 'selected' : ''}>Ternero / Ternera</option>
                  <option value="Toro Reproductor" ${categoria === 'Toro Reproductor' ? 'selected' : ''}>Toro Reproductor</option>
                  <option value="Búfala de Ordeño" ${categoria === 'Búfala de Ordeño' ? 'selected' : ''}>Búfala de Ordeño</option>
                  <option value="Búfala Horra" ${categoria === 'Búfala Horra' ? 'selected' : ''}>Búfala Horra / Seca</option>
                  <option value="Bubilla de Vientre" ${categoria === 'Bubilla de Vientre' ? 'selected' : ''}>Bubilla de Vientre</option>
                  <option value="Búfalo de Ceba" ${categoria === 'Búfalo de Ceba' ? 'selected' : ''}>Búfalo de Ceba</option>
                </select>
              </div>

              <!-- Lote -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Lote de Destino:</label>
                <input type="text" id="edit-lote" value="${lote}" list="lotes-existentes-edit" class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none">
                <datalist id="lotes-existentes-edit">
                  ${lotes.map((l) => `<option value="${l}"></option>`).join('')}
                </datalist>
              </div>

              <!-- Fecha de Nacimiento -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Fecha de Nacimiento:</label>
                <input type="date" id="edit-nacimiento" value="${fNac}" class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none">
              </div>

              <!-- Padre -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Padre (Toro / Tag):</label>
                <input type="text" id="edit-padre" value="${padre}" placeholder="Ej. TORO-01 o Pajilla" class="w-full px-3 py-2 font-mono font-bold rounded-xl border border-slate-300 outline-none uppercase">
              </div>

              <!-- Madre -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Madre (Vaca / Tag):</label>
                <input type="text" id="edit-madre" value="${madre}" placeholder="Ej. BV-102" class="w-full px-3 py-2 font-mono font-bold rounded-xl border border-slate-300 outline-none uppercase">
              </div>

              <!-- Peso Actual (Kg) -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Peso Actual (Kg):</label>
                <input type="number" step="0.5" id="edit-peso" value="${peso}" placeholder="Ej. 450" class="w-full px-3 py-2 font-mono font-bold rounded-xl border border-slate-300 outline-none">
              </div>

              <!-- Condición Corporal -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Condición Corporal (1-5):</label>
                <select id="edit-condicion" class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none bg-white">
                  <option value="1.0" ${condicion === '1.0' ? 'selected' : ''}>1.0 - Muy Flaca</option>
                  <option value="2.0" ${condicion === '2.0' ? 'selected' : ''}>2.0 - Flaca</option>
                  <option value="3.0" ${condicion === '3.0' ? 'selected' : ''}>3.0 - Regular</option>
                  <option value="3.5" ${condicion === '3.5' ? 'selected' : ''}>3.5 - Óptima / Ideal</option>
                  <option value="4.0" ${condicion === '4.0' ? 'selected' : ''}>4.0 - Buena</option>
                  <option value="5.0" ${condicion === '5.0' ? 'selected' : ''}>5.0 - Obesa</option>
                </select>
              </div>

              <!-- Estado Reproductivo -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Estado Reproductivo:</label>
                <select id="edit-repro" class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none bg-white">
                  <option value="Vacía" ${repro === 'Vacía' ? 'selected' : ''}>⚪ Vacía</option>
                  <option value="Servida" ${repro === 'Servida' ? 'selected' : ''}>🟡 Servida</option>
                  <option value="Preñada" ${esPrenada ? 'selected' : ''}>🟢 Preñada (Gestante)</option>
                  <option value="No Aplica" ${repro === 'No Aplica' ? 'selected' : ''}>⚪ No Aplica (Macho/Cría)</option>
                </select>
              </div>

              <!-- Días de Preñez (Condicional) -->
              <div id="wrapper-edit-dias-prened" class="${esPrenada ? '' : 'hidden'}">
                <label class="block font-bold text-emerald-800 mb-1">Días de Preñez / Gestación:</label>
                <input type="number" id="edit-dias-gestacion" value="${diasG}" min="0" max="315" class="w-full px-3 py-2 font-mono font-bold rounded-xl border border-emerald-300 bg-emerald-50 outline-none">
                <span class="text-[10px] text-emerald-700 block mt-0.5">Días calculados desde la monta o inseminación.</span>
              </div>

              <!-- Fecha de Último Parto -->
              <div>
                <label class="block font-bold text-slate-700 mb-1">Fecha Último Parto:</label>
                <input type="date" id="edit-ultimo-parto" value="${fParto}" class="w-full px-3 py-2 font-bold rounded-xl border border-slate-300 outline-none">
              </div>
            </div>

            <!-- BOTONES ACCIÓN -->
            <div class="pt-4 border-t border-slate-200 flex justify-end gap-2">
              <button type="button" id="btn-cancelar-editar-animal" class="px-4 py-2 rounded-xl bg-slate-100 hover:bg-slate-200 font-bold text-slate-700 transition cursor-pointer">
                Cancelar
              </button>
              <button type="submit" class="px-5 py-2 rounded-xl bg-blue-600 hover:bg-blue-500 font-black text-white shadow-lg transition cursor-pointer">
                Guardar Modificaciones
              </button>
            </div>
          </form>
        </div>
      </div>
    `;
  }

  attachEvents() {
    // Búsqueda reactiva con autosuggest universal (números o letras)
    const inputTag = this.container.querySelector('#input-tag-animal-directo');
    if (inputTag) {
      conectarAutosuggestAnimales({
        inputElement: inputTag,
        getAnimales: () => this.getAnimalesBusqueda ? this.getAnimalesBusqueda() : (this.getAnimales ? this.getAnimales() : []),
        theme: 'emerald',
        maxResultados: 8,
        onTrasladarAFinca: (animal) => {
          if (this.onTrasladarAFinca) this.onTrasladarAFinca(animal);
        },
        onReactivarAnimal: (animal) => {
          if (this.onReactivarAnimal) this.onReactivarAnimal(animal);
        },
        onSeleccionar: (animal) => {
          const tag = animal.identificacionTag || animal.numero;
          inputTag.value = tag;
          this.filtroBusqueda = tag;
          if (this.onVerFicha) {
            this.onVerFicha(animal.id);
          }
          this.filtrarTablaEnVivo();
        }
      });

      inputTag.addEventListener('input', (e) => {
        this.filtroBusqueda = e.target.value;
        this.filtrarTablaEnVivo();
      });
    }

    // Formulario de Búsqueda Directa estilo Manga (Abre la Ficha si coincide exactamente)
    const formBuscarDirecto = this.container.querySelector('#form-buscar-animal-directo');
    if (formBuscarDirecto) {
      formBuscarDirecto.addEventListener('submit', (e) => {
        e.preventDefault();
        const inputTagEl = this.container.querySelector('#input-tag-animal-directo');
        const q = inputTagEl ? inputTagEl.value.trim().toUpperCase() : '';

        this.filtroBusqueda = q;
        if (!q) {
          this.filtrarTablaEnVivo();
          return;
        }

        const todos = this.getAnimalesBusqueda ? this.getAnimalesBusqueda() : (this.getAnimales ? this.getAnimales() : []);

        // 1. Buscar coincidencia exacta por arete/tag o número
        let matchExacto = todos.find((a) =>
          (a.identificacionTag || '').toUpperCase() === q ||
          (a.numero || '').toUpperCase() === q
        );

        // Si es exacto, comprobar si está en otra finca o extraído
        if (matchExacto) {
          if (matchExacto._estaEnOtraFinca) {
            const confirmacion = confirm(`El animal "${matchExacto.identificacionTag || matchExacto.numero}" se encuentra registrado en la finca "${matchExacto._fincaNombre || 'otra finca'}".\n\n¿Deseas trasladarlo inmediatamente a la finca en la que estás trabajando?`);
            if (confirmacion && typeof this.onTrasladarAFinca === 'function') {
              this.onTrasladarAFinca(matchExacto);
            }
          } else if (matchExacto._estaExtraido) {
            const motivo = matchExacto.motivoBaja || matchExacto._motivoExtraido || 'Baja';
            const confirmacion = confirm(`El animal "${matchExacto.identificacionTag || matchExacto.numero}" se encuentra actualmente EXTRAÍDO del hato (Motivo: ${motivo}).\n\n¿Deseas activarlo nuevamente en esta finca?`);
            if (confirmacion && typeof this.onReactivarAnimal === 'function') {
              this.onReactivarAnimal(matchExacto);
            }
          }

          if (this.onVerFicha) {
            this.onVerFicha(matchExacto.id);
          }
        }

        this.filtrarTablaEnVivo();
      });
    }

    // Botón para abrir el módulo de traslados entre fincas
    const btnTrasladosPestana = this.container.querySelector('#btn-abrir-traslados-pestana');
    if (btnTrasladosPestana) {
      btnTrasladosPestana.addEventListener('click', () => {
        if (this.onAbrirModuloTraslados) {
          this.onAbrirModuloTraslados();
        }
      });
    }

    // Botón para limpiar filtro de búsqueda
    const btnLimpiar = this.container.querySelector('#btn-limpiar-busqueda-pestana');
    if (btnLimpiar) {
      btnLimpiar.addEventListener('click', () => {
        this.filtroBusqueda = '';
        const inEl = this.container.querySelector('#input-tag-animal-directo');
        if (inEl) inEl.value = '';
        this.filtrarTablaEnVivo();
      });
    }

    // Filtro Estado Vida (Activos, Vendidos, Muertos, Todos)
    const selEst = this.container.querySelector('#select-filtro-estado-pestana');
    if (selEst) {
      selEst.addEventListener('change', (e) => {
        this.filtroEstadoVida = e.target.value;
        this.render();
      });
    }

    // Filtro Especie
    const selEsp = this.container.querySelector('#select-filtro-especie-pestana');
    if (selEsp) {
      selEsp.addEventListener('change', (e) => {
        this.filtroEspecie = e.target.value;
        this.render();
      });
    }

    // Filtro Lote
    const selLot = this.container.querySelector('#select-filtro-lote-pestana');
    if (selLot) {
      selLot.addEventListener('change', (e) => {
        this.filtroLote = e.target.value;
        this.render();
      });
    }

    // Filtro Repro
    const selRep = this.container.querySelector('#select-filtro-repro-pestana');
    if (selRep) {
      selRep.addEventListener('change', (e) => {
        this.filtroRepro = e.target.value;
        this.render();
      });
    }

    // Filtro Raza
    const selRaza = this.container.querySelector('#select-filtro-raza-pestana');
    if (selRaza) {
      selRaza.addEventListener('change', (e) => {
        this.filtroRaza = e.target.value;
        this.render();
      });
    }

    // Eventos de la tabla
    this.enlazarEventosTabla();

    // Modal "+ Nuevo Animal"
    const btnAbrir = this.container.querySelector('#btn-abrir-modal-nuevo-animal');
    if (btnAbrir) {
      btnAbrir.addEventListener('click', () => {
        this.modalNuevoAbierto = true;
        this.render();
      });
    }

    const btnCerrar = this.container.querySelector('#btn-cerrar-modal-nuevo');
    if (btnCerrar) {
      btnCerrar.addEventListener('click', () => {
        this.modalNuevoAbierto = false;
        this.render();
      });
    }

    const btnCancelar = this.container.querySelector('#btn-cancelar-nuevo-animal');
    if (btnCancelar) {
      btnCancelar.addEventListener('click', () => {
        this.modalNuevoAbierto = false;
        this.render();
      });
    }

    // Dinámica campo días de gestación en modal
    const selReproModal = this.container.querySelector('#nuevo-repro');
    const wrapPrened = this.container.querySelector('#wrapper-nuevo-dias-prened');
    if (selReproModal && wrapPrened) {
      selReproModal.addEventListener('change', (e) => {
        if (e.target.value === 'Preñada') {
          wrapPrened.classList.remove('hidden');
        } else {
          wrapPrened.classList.add('hidden');
        }
      });
    }

    // Submit Nuevo Animal
    const formNuevo = this.container.querySelector('#form-nuevo-animal');
    if (formNuevo) {
      formNuevo.addEventListener('submit', (e) => {
        e.preventDefault();
        const tag = document.getElementById('nuevo-tag').value.trim().toUpperCase();
        const especie = document.getElementById('nuevo-especie').value;
        const nombre = document.getElementById('nuevo-nombre').value.trim();
        const sexo = document.getElementById('nuevo-sexo').value;
        const raza = document.getElementById('nuevo-raza').value.trim() || 'Común';
        const categoria = document.getElementById('nuevo-categoria').value;
        const lote = document.getElementById('nuevo-lote').value.trim() || 'General';
        const nacimiento = document.getElementById('nuevo-nacimiento').value || null;
        const padre = document.getElementById('nuevo-padre').value.trim().toUpperCase() || 'Desconocido';
        const madre = document.getElementById('nuevo-madre').value.trim().toUpperCase() || 'Desconocida';
        const peso = parseFloat(document.getElementById('nuevo-peso').value) || null;
        const repro = document.getElementById('nuevo-repro').value;
        const diasG = repro === 'Preñada' ? parseInt(document.getElementById('nuevo-dias-gestacion').value) || 60 : 0;
        const ultimoParto = document.getElementById('nuevo-ultimo-parto').value || null;

        if (sexo === 'macho' && repro === 'Preñada') {
          alert('Error biológico: Un macho no puede registrarse como preñado.');
          return;
        }

        const nuevoAnimal = {
          id: `ANM-${Date.now()}-${tag}`,
          identificacionTag: tag,
          especie: especie,
          nombreAlias: nombre || `Ejemplar ${tag}`,
          sexo: sexo,
          raza: raza,
          categoria: categoria,
          lote: lote,
          fechaNacimiento: nacimiento,
          padreTag: padre,
          madreTag: madre,
          padre: padre,
          madre: madre,
          ultimoPesoKg: peso,
          fechaUltimoPesaje: peso ? new Date().toISOString().split('T')[0] : null,
          estadoReproductivo: repro,
          diasGestacionActual: diasG,
          fechaUltimoParto: ultimoParto,
          estadoVida: 'activo'
        };

        if (this.onCrearAnimal) {
          this.onCrearAnimal(nuevoAnimal);
        }

        this.modalNuevoAbierto = false;
        this.render();
      });
    }

    // Editar Animal Buttons en tabla
    this.container.querySelectorAll('.btn-editar-animal').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const id = e.currentTarget.getAttribute('data-id');
        const todosAnimales = this.getAnimales ? this.getAnimales() : [];
        const animal = todosAnimales.find((a) => a.id === id);
        if (animal) {
          this.abrirModalEditar(animal);
        }
      });
    });

    const btnCerrarEdit = this.container.querySelector('#btn-cerrar-modal-editar-animal');
    if (btnCerrarEdit) {
      btnCerrarEdit.addEventListener('click', () => {
        this.animalEditando = null;
        this.render();
      });
    }

    const btnCancelarEdit = this.container.querySelector('#btn-cancelar-editar-animal');
    if (btnCancelarEdit) {
      btnCancelarEdit.addEventListener('click', () => {
        this.animalEditando = null;
        this.render();
      });
    }

    const selReproEdit = this.container.querySelector('#edit-repro');
    const wrapPrenedEdit = this.container.querySelector('#wrapper-edit-dias-prened');
    if (selReproEdit && wrapPrenedEdit) {
      selReproEdit.addEventListener('change', (e) => {
        if (e.target.value === 'Preñada') {
          wrapPrenedEdit.classList.remove('hidden');
        } else {
          wrapPrenedEdit.classList.add('hidden');
        }
      });
    }

    const formEdit = this.container.querySelector('#form-editar-animal');
    if (formEdit) {
      formEdit.addEventListener('submit', (e) => {
        e.preventDefault();
        if (!this.animalEditando) return;

        const tag = document.getElementById('edit-tag').value.trim().toUpperCase();
        const especie = document.getElementById('edit-especie').value;
        const nombre = document.getElementById('edit-nombre').value.trim();
        const sexo = document.getElementById('edit-sexo').value;
        const raza = document.getElementById('edit-raza').value.trim() || 'Común';
        const categoria = document.getElementById('edit-categoria').value;
        const lote = document.getElementById('edit-lote').value.trim() || 'General';
        const nacimiento = document.getElementById('edit-nacimiento').value || null;
        const padre = document.getElementById('edit-padre').value.trim().toUpperCase() || 'Desconocido';
        const madre = document.getElementById('edit-madre').value.trim().toUpperCase() || 'Desconocida';
        const peso = parseFloat(document.getElementById('edit-peso').value) || null;
        const repro = document.getElementById('edit-repro').value;
        const diasG = repro === 'Preñada' ? parseInt(document.getElementById('edit-dias-gestacion').value) || 60 : 0;
        const ultimoParto = document.getElementById('edit-ultimo-parto').value || null;
        const condicion = document.getElementById('edit-condicion').value || '3.5';

        if (sexo === 'macho' && repro === 'Preñada') {
          alert('Error biológico: Un macho no puede registrarse como preñado.');
          return;
        }

        const animalActualizado = {
          ...this.animalEditando,
          identificacionTag: tag,
          numero: tag,
          tag: tag,
          especie: especie,
          nombreAlias: nombre || `Ejemplar ${tag}`,
          nombre: nombre,
          sexo: sexo,
          raza: raza,
          categoria: categoria,
          lote: lote,
          fechaNacimiento: nacimiento,
          padreTag: padre,
          madreTag: madre,
          padre: padre,
          genealogiaPadre: padre,
          madre: madre,
          genealogiaMadre: madre,
          ultimoPesoKg: peso,
          pesoActual: peso,
          condicionCorporal: condicion,
          estadoReproductivo: repro,
          diasGestacionActual: diasG,
          diasGestacion: diasG,
          fechaUltimoParto: ultimoParto
        };

        if (this.onActualizarAnimal) {
          this.onActualizarAnimal(animalActualizado);
        }

        this.animalEditando = null;
        this.render();
      });
    }

    // Autosuggest para Padre y Madre en Modal Nuevo Animal
    const inNuevoPadre = this.container.querySelector('#nuevo-padre');
    if (inNuevoPadre) {
      conectarAutosuggestAnimales({
        inputElement: inNuevoPadre,
        getAnimales: () => (this.getAnimales ? this.getAnimales() : []).filter((a) => (a.sexo || '').toLowerCase() === 'macho'),
        theme: 'emerald',
        maxResultados: 6,
        onSeleccionar: (a) => {
          inNuevoPadre.value = a.identificacionTag || a.numero;
        }
      });
    }

    const inNuevoMadre = this.container.querySelector('#nuevo-madre');
    if (inNuevoMadre) {
      conectarAutosuggestAnimales({
        inputElement: inNuevoMadre,
        getAnimales: () => (this.getAnimales ? this.getAnimales() : []).filter((a) => (a.sexo || '').toLowerCase() === 'hembra'),
        theme: 'emerald',
        maxResultados: 6,
        onSeleccionar: (a) => {
          inNuevoMadre.value = a.identificacionTag || a.numero;
        }
      });
    }

    // Autosuggest para Padre y Madre en Modal Editar Animal
    const inEditPadre = this.container.querySelector('#edit-padre');
    if (inEditPadre) {
      conectarAutosuggestAnimales({
        inputElement: inEditPadre,
        getAnimales: () => (this.getAnimales ? this.getAnimales() : []).filter((a) => (a.sexo || '').toLowerCase() === 'macho'),
        theme: 'emerald',
        maxResultados: 6,
        onSeleccionar: (a) => {
          inEditPadre.value = a.identificacionTag || a.numero;
        }
      });
    }

    const inEditMadre = this.container.querySelector('#edit-madre');
    if (inEditMadre) {
      conectarAutosuggestAnimales({
        inputElement: inEditMadre,
        getAnimales: () => (this.getAnimales ? this.getAnimales() : []).filter((a) => (a.sexo || '').toLowerCase() === 'hembra'),
        theme: 'emerald',
        maxResultados: 6,
        onSeleccionar: (a) => {
          inEditMadre.value = a.identificacionTag || a.numero;
        }
      });
    }
  }

  enlazarEventosTabla() {
    if (!this.container) return;

    // Ver Ficha Buttons
    this.container.querySelectorAll('.btn-ver-ficha-animal').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const id = e.currentTarget.getAttribute('data-id');
        if (this.onVerFicha) this.onVerFicha(id);
      });
    });

    // Extraer Animal individual desde la tabla
    this.container.querySelectorAll('.btn-extraer-fila-animal').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const id = e.currentTarget.getAttribute('data-id');
        const todos = this.getAnimales ? this.getAnimales() : [];
        const animal = todos.find((a) => a.id === id);
        if (animal && this.onExtraerAnimal) {
          this.onExtraerAnimal(animal);
        } else if (this.onVerFicha) {
          this.onVerFicha(id);
        }
      });
    });

    // Reactivar Animal individual desde la tabla
    this.container.querySelectorAll('.btn-reactivar-fila-animal').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const id = e.currentTarget.getAttribute('data-id');
        const tag = e.currentTarget.getAttribute('data-tag');
        if (confirm(`¿Deseas reactivar al ejemplar ${tag} en el inventario activo de esta finca?`)) {
          const todos = this.getAnimales ? this.getAnimales() : [];
          const animal = todos.find((a) => a.id === id);
          if (animal && this.onReactivarAnimal) {
            this.onReactivarAnimal(animal);
          }
        }
      });
    });

    // Trasladar Animal individual desde la tabla
    this.container.querySelectorAll('.btn-trasladar-animal').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const id = e.currentTarget.getAttribute('data-id');
        const todos = this.getAnimales ? this.getAnimales() : [];
        const animal = todos.find((a) => a.id === id);
        if (animal && this.onTrasladar) {
          this.onTrasladar(animal);
        }
      });
    });

    // Editar Animal Buttons en tabla
    this.container.querySelectorAll('.btn-editar-animal').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const id = e.currentTarget.getAttribute('data-id');
        const todosAnimales = this.getAnimales ? this.getAnimales() : [];
        const animal = todosAnimales.find((a) => a.id === id);
        if (animal) {
          this.abrirModalEditar(animal);
        }
      });
    });

    // Eliminar Animal Buttons
    this.container.querySelectorAll('.btn-eliminar-animal').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const id = e.currentTarget.getAttribute('data-id');
        const tag = e.currentTarget.getAttribute('data-tag');
        if (confirm(`¿Eliminar al ejemplar ${tag} del inventario?`)) {
          if (this.onEliminarAnimal) this.onEliminarAnimal(id);
        }
      });
    });
  }

  filtrarTablaEnVivo() {
    if (!this.container) return;
    const todosAnimales = this.getAnimales ? this.getAnimales() : [];
    let lista = todosAnimales;

    if (this.filtroEstadoVida === 'activos') {
      lista = lista.filter((a) => a.estadoVida === 'activo' || a.estado === 'activo');
    } else if (this.filtroEstadoVida === 'vendidos') {
      lista = lista.filter((a) => (a.motivoBaja || '').toLowerCase() === 'venta');
    } else if (this.filtroEstadoVida === 'muertos') {
      lista = lista.filter((a) => (a.motivoBaja || '').toLowerCase() === 'muerte');
    }

    if (this.filtroEspecie !== 'todas') {
      lista = lista.filter((a) => (a.especie || 'bovino').toLowerCase() === this.filtroEspecie);
    }

    if (this.filtroLote !== 'todos') {
      lista = lista.filter((a) => (a.lote || 'General') === this.filtroLote);
    }

    if (this.filtroRepro !== 'todos') {
      lista = lista.filter((a) => {
        const est = (a.estadoReproductivo || '').toLowerCase();
        if (this.filtroRepro === 'prenada') return est.includes('prenad') || est.includes('preñad');
        if (this.filtroRepro === 'vacia') return est.includes('vaci') || est.includes('vací');
        if (this.filtroRepro === 'no_aplica') return est.includes('no');
        return true;
      });
    }

    if (this.filtroSexo !== 'todos') {
      lista = lista.filter((a) => (a.sexo || '').toLowerCase() === this.filtroSexo);
    }

    if (this.filtroRaza !== 'todas') {
      lista = lista.filter((a) => (a.raza || '').trim().toLowerCase() === this.filtroRaza.toLowerCase());
    }

    if (this.filtroBusqueda.trim().length > 0) {
      const q = this.filtroBusqueda.trim().toLowerCase();
      const qDigits = q.replace(/\D/g, '');
      lista = lista.filter((a) => {
        const tag = (a.identificacionTag || a.numero || '').toLowerCase();
        const tagDigits = tag.replace(/\D/g, '');
        const matchTag = tag.includes(q) || (qDigits.length > 0 && tagDigits.includes(qDigits));
        const matchNombre = (a.nombreAlias || a.nombre || '').toLowerCase().includes(q);
        const matchPadre = (a.padreTag || a.padre || '').toLowerCase().includes(q);
        const matchMadre = (a.madreTag || a.madre || '').toLowerCase().includes(q);
        const matchRaza = (a.raza || '').toLowerCase().includes(q);
        return matchTag || matchNombre || matchPadre || matchMadre || matchRaza;
      });
    }

    const badgeContador = this.container.querySelector('#contador-animales-pestana');
    if (badgeContador) {
      badgeContador.textContent = `${lista.length} de ${todosAnimales.length} Ejemplares`;
    }
    const subtexto = this.container.querySelector('#subtexto-contador-pestana');
    if (subtexto) {
      subtexto.textContent = `Mostrando ${lista.length} ejemplares`;
    }

    const tbody = this.container.querySelector('#tbody-animales-pestana');
    const contTarjetas = this.container.querySelector('#contenedor-tarjetas-mobile');
    const rol = this.getRol ? this.getRol() : 'administrador';
    const esSoloConsulta = rol === 'consulta' || rol === 'propietario' || rol === 'consultor';

    if (tbody) {
      if (lista.length > 0) {
        tbody.innerHTML = lista.map((a) => this.renderFilaAnimal(a, esSoloConsulta)).join('');
      } else {
        tbody.innerHTML = this.renderFilaVacia();
      }
    }

    if (contTarjetas) {
      if (lista.length > 0) {
        contTarjetas.innerHTML = lista.map((a) => this.renderTarjetaAnimalMobile(a, esSoloConsulta)).join('');
      } else {
        contTarjetas.innerHTML = this.renderTarjetaVaciaMobile();
      }
    }

    this.enlazarEventosTabla();
  }
}


// ============================================================================
// ARCHIVO: frontend/src/components/ModuloTraslados.js
// ============================================================================
/**
 * GANADERO AD - MÓDULO DE TRASLADO DE ANIMALES ENTRE FINCAS
 * Flujo en manga uno a uno: selección superior de finca origen y destino,
 * cuadro para buscar el animal y acumularlo en la planilla, y botón final para guardar.
 */



class ModuloTraslados {
  constructor({
    containerId = 'pantalla-traslados',
    getFincas,
    getFincaActiva,
    getAnimales,
    getTraslados,
    getRol,
    onEjecutarTraslado,
    onRevertirTraslado,
    onVerFicha
  }) {
    this.containerId = containerId;
    this.container = typeof document !== 'undefined' ? document.getElementById(containerId) : null;
    this.getFincas = getFincas;
    this.getFincaActiva = getFincaActiva;
    this.getAnimales = getAnimales;
    this.getTraslados = getTraslados;
    this.getRol = getRol;
    this.onEjecutarTraslado = onEjecutarTraslado;
    this.onRevertirTraslado = onRevertirTraslado;
    this.onVerFicha = onVerFicha;

    this.fincaOrigenId = null;
    this.fincaDestinoId = null;
    this.fechaTraslado = new Date().toISOString().split('T')[0];
    this.motivo = 'Pastoreo y Rotación de Potreros';
    this.loteDestino = 'Lote Traslado';
    this.observaciones = '';

    this.animalesSesion = []; // Lista de animales acumulados en la sesión de manga
    this.vistaSubTab = 'manga'; // 'manga' (Nuevo Traslado) | 'historial' (Historial)
    this.ultimoAnimalCargado = null;
    this.mensajeFeedback = null;
  }

  init() {
    if (typeof document !== 'undefined') {
      this.container = document.getElementById(this.containerId);
    }
    this.render();
  }

  abrirModalTrasladoRapido(animal) {
    if (!animal) return;
    this.vistaSubTab = 'manga';
    this.fincaOrigenId = animal.fincaId;
    if (!this.animalesSesion.some((a) => a.id === animal.id)) {
      this.animalesSesion.push(animal);
      this.ultimoAnimalCargado = animal;
    }
    this.render();
  }

  buscarAnimalPorTag(tag) {
    if (!tag) return null;
    const cleanTag = tag.trim().toUpperCase();
    const animales = (this.getAnimales ? this.getAnimales() : []).filter(
      (a) => a.estadoVida === 'activo' || a.estado === 'activo' || !a.estadoVida
    );
    return animales.find(
      (a) => (a.identificacionTag || a.numero || '').toUpperCase() === cleanTag
    ) || null;
  }

  agregarAnimalATraslado(animal) {
    if (!animal) return;

    // Validar que pertenezca a la Finca Origen
    if (animal.fincaId !== this.fincaOrigenId) {
      const fincas = this.getFincas ? this.getFincas() : [];
      const fActual = fincas.find((f) => f.id === animal.fincaId);
      this.mensajeFeedback = `El animal ${animal.identificacionTag} se encuentra en "${fActual ? fActual.nombre : animal.fincaId}", no en la finca origen seleccionada.`;
      this.render();
      return;
    }

    // Validar que no esté ya en la lista
    if (this.animalesSesion.some((a) => a.id === animal.id)) {
      this.mensajeFeedback = `El animal ${animal.identificacionTag} ya está en la lista de traslado.`;
      this.render();
      return;
    }

    // Agregar exitosamente a la sesión
    this.animalesSesion.unshift(animal);
    this.ultimoAnimalCargado = animal;
    this.mensajeFeedback = null;
    this.render();

    const refoc = this.container.querySelector('#input-tag-traslado-manga');
    if (refoc) {
      refoc.value = '';
      refoc.focus();
    }
  }

  render() {
    if (!this.container && typeof document !== 'undefined') {
      this.container = document.getElementById(this.containerId);
    }
    if (!this.container) return;

    const fincas = this.getFincas ? this.getFincas() : [];
    const fActiva = this.getFincaActiva ? this.getFincaActiva() : null;

    if (!this.fincaOrigenId) {
      this.fincaOrigenId = fActiva ? fActiva.id : (fincas[0]?.id || null);
    }

    const fincasDestino = fincas.filter((f) => f.id !== this.fincaOrigenId);
    if (!this.fincaDestinoId || this.fincaDestinoId === this.fincaOrigenId) {
      this.fincaDestinoId = fincasDestino[0]?.id || null;
    }

    const todosAnimales = this.getAnimales ? this.getAnimales() : [];
    const animalesEnOrigen = todosAnimales.filter(
      (a) => a.fincaId === this.fincaOrigenId && (a.estadoVida === 'activo' || !a.estadoVida)
    );

    const traslados = this.getTraslados ? this.getTraslados() : [];
    const rol = this.getRol ? this.getRol() : 'administrador';
    const esSoloConsulta = rol === 'consulta' || rol === 'consultor';

    const fOrigenObj = fincas.find((f) => f.id === this.fincaOrigenId);
    const fDestinoObj = fincas.find((f) => f.id === this.fincaDestinoId);
    const lotesOrigen = [...new Set(animalesEnOrigen.map((a) => a.lote || 'General'))].filter(Boolean);

    this.container.innerHTML = `
      <div class="bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden">
        <!-- CABECERA PRINCIPAL SUPERIOR (ESTILO CUADRICULA MASIVA) -->
        <div class="bg-gradient-to-r from-slate-950 via-slate-900 to-slate-950 text-white p-4 sm:p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-3">
          <div class="flex items-center gap-3">
            <div class="w-11 h-11 rounded-2xl bg-purple-600/20 text-purple-400 border border-purple-500/30 flex items-center justify-center text-2xl shadow-inner">
              🚚
            </div>
            <div>
              <h2 class="text-base sm:text-lg font-black tracking-tight flex items-center gap-2">
                <span>Módulo de Traslado de Animales</span>
                <span class="text-[10px] uppercase font-mono px-2 py-0.5 rounded bg-purple-500/20 text-purple-300 border border-purple-400/30">
                  Modo Manga / Planilla
                </span>
              </h2>
              <p class="text-xs text-slate-400 mt-0.5">Selecciona origen y destino, busca el animal para sumarlo a la lista y confirma el traslado.</p>
            </div>
          </div>

          <!-- BOTONES DE PESTAÑAS (PLANILLA DE TRASLADO / HISTORIAL) -->
          <div class="flex items-center gap-1.5 bg-slate-800 p-1.5 rounded-xl border border-slate-700 w-full md:w-auto">
            <button id="btn-subtab-manga" class="flex-1 md:flex-none px-3.5 py-1.5 rounded-lg text-xs font-bold transition flex items-center justify-center gap-1.5 ${this.vistaSubTab === 'manga' ? 'bg-purple-600 text-white shadow' : 'text-slate-400 hover:text-white'}">
              <span>📋</span> Planilla de Traslado
            </button>
            <button id="btn-subtab-historial" class="flex-1 md:flex-none px-3.5 py-1.5 rounded-lg text-xs font-bold transition flex items-center justify-center gap-1.5 ${this.vistaSubTab === 'historial' ? 'bg-purple-600 text-white shadow' : 'text-slate-400 hover:text-white'}">
              <span>🕒</span> Historial (${traslados.length})
            </button>
          </div>
        </div>

        ${this.vistaSubTab === 'manga' ? `
          <!-- PARTE SUPERIOR: SELECCIÓN DE FINCA ORIGEN Y DESTINO + PARÁMETROS -->
          <div class="p-4 sm:p-5 bg-slate-50 border-b border-slate-200">
            <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3 text-xs">
              <!-- FINCA ORIGEN -->
              <div class="bg-white p-3 rounded-xl border border-slate-300 shadow-sm space-y-1">
                <label class="block font-black text-slate-800 uppercase tracking-wider text-[10px] flex items-center gap-1">
                  <span>🏡</span> Finca de Origen (Emisora) *:
                </label>
                <select id="sel-finca-origen-traslado" class="w-full px-2.5 py-2 bg-slate-50 font-bold text-slate-900 rounded-lg border border-slate-300 outline-none focus:border-purple-600 cursor-pointer">
                  ${fincas.map((f) => `<option value="${f.id}" ${f.id === this.fincaOrigenId ? 'selected' : ''}>${f.nombre}</option>`).join('')}
                </select>
                <div class="text-[10px] text-slate-500 flex justify-between">
                  <span>Predio de salida</span>
                  <span class="font-bold text-purple-700">${animalesEnOrigen.length} disponibles</span>
                </div>
              </div>

              <!-- FINCA DESTINO -->
              <div class="bg-white p-3 rounded-xl border border-purple-300 shadow-sm space-y-1">
                <label class="block font-black text-purple-900 uppercase tracking-wider text-[10px] flex items-center gap-1">
                  <span>🏁</span> Finca de Destino (Receptora) *:
                </label>
                ${fincasDestino.length > 0 ? `
                  <select id="sel-finca-destino-traslado" class="w-full px-2.5 py-2 bg-purple-50/50 font-bold text-purple-950 rounded-lg border border-purple-300 outline-none focus:border-purple-600 cursor-pointer">
                    ${fincasDestino.map((f) => `<option value="${f.id}" ${f.id === this.fincaDestinoId ? 'selected' : ''}>${f.nombre}</option>`).join('')}
                  </select>
                ` : `
                  <div class="p-2 bg-amber-50 text-amber-900 font-bold rounded-lg text-[11px] border border-amber-200">
                    Se requieren 2 fincas registradas
                  </div>
                `}
                <div class="text-[10px] text-purple-700">Predio de llegada de los animales</div>
              </div>

              <!-- FECHA Y MOTIVO -->
              <div class="bg-white p-3 rounded-xl border border-slate-300 shadow-sm space-y-1">
                <label class="block font-bold text-slate-700 text-[10px] uppercase">📅 Fecha y Motivo:</label>
                <input type="date" id="input-fecha-traslado" value="${this.fechaTraslado}" class="w-full px-2.5 py-1.5 rounded-lg border border-slate-300 font-bold text-xs outline-none focus:border-purple-600 mb-1">
                <select id="sel-motivo-traslado" class="w-full px-2.5 py-1.5 rounded-lg border border-slate-300 font-bold text-xs bg-slate-50 outline-none cursor-pointer">
                  <option value="Pastoreo y Rotación de Potreros" ${this.motivo === 'Pastoreo y Rotación de Potreros' ? 'selected' : ''}>Pastoreo y Rotación</option>
                  <option value="Ceba y Engorde" ${this.motivo === 'Ceba y Engorde' ? 'selected' : ''}>Ceba y Engorde</option>
                  <option value="Reproducción y Monta" ${this.motivo === 'Reproducción y Monta' ? 'selected' : ''}>Reproducción / Monta</option>
                  <option value="Producción de Leche" ${this.motivo === 'Producción de Leche' ? 'selected' : ''}>Producción de Leche</option>
                  <option value="Cuarentena y Sanidad" ${this.motivo === 'Cuarentena y Sanidad' ? 'selected' : ''}>Cuarentena / Sanidad</option>
                  <option value="Transferencia Interna" ${this.motivo === 'Transferencia Interna' ? 'selected' : ''}>Transferencia Interna</option>
                </select>
              </div>

              <!-- LOTE EN DESTINO Y GUÍA -->
              <div class="bg-white p-3 rounded-xl border border-slate-300 shadow-sm space-y-1">
                <label class="block font-bold text-slate-700 text-[10px] uppercase">🏷️ Lote en Destino & Notas:</label>
                <input type="text" id="input-lote-destino-traslado" value="${this.loteDestino}" placeholder="Ej. Lote Ceba 1" class="w-full px-2.5 py-1.5 rounded-lg border border-slate-300 font-bold text-xs outline-none focus:border-purple-600 mb-1">
                <input type="text" id="input-obs-traslado" value="${this.observaciones}" placeholder="Guía ICA / Conductor / Camión" class="w-full px-2.5 py-1.5 rounded-lg border border-slate-300 text-xs outline-none">
              </div>
            </div>
          </div>

          <!-- SECCIÓN DE BÚSQUEDA Y CAPTURA UNO A UNO EN MANGA -->
          <div class="p-4 sm:p-5 bg-emerald-50/40 border-b border-emerald-100">
            <div class="max-w-3xl mx-auto space-y-3">
              <form id="form-buscar-traslado-manga" class="flex flex-col sm:flex-row items-center gap-3">
                <div class="relative w-full">
                  <span class="absolute left-3.5 top-3.5 text-slate-400 text-sm">🔍</span>
                  <input 
                    type="text" 
                    id="input-tag-traslado-manga" 
                    list="datalist-animales-traslado-origen"
                    placeholder="Digite o escanee No. de animal en ${fOrigenObj ? fOrigenObj.nombre : 'finca origen'} (Ej. BV-401, 102)..." 
                    class="w-full pl-10 pr-4 py-3 bg-white text-slate-900 font-mono font-black text-base rounded-xl border-2 border-purple-500 focus:ring-4 focus:ring-purple-500/20 outline-none uppercase shadow-sm"
                    autocomplete="off"
                  >
                  <datalist id="datalist-animales-traslado-origen">
                    ${animalesEnOrigen.map((a) => `<option value="${a.identificacionTag || a.numero}">${a.nombreAlias ? a.nombreAlias + ' - ' : ''}${a.raza || ''} (Lote: ${a.lote || 'Sin Lote'})</option>`).join('')}
                  </datalist>
                </div>
                <button 
                  type="submit" 
                  id="btn-agregar-traslado-manga" 
                  class="w-full sm:w-auto px-6 py-3 bg-purple-700 hover:bg-purple-600 active:scale-95 text-white font-black text-sm rounded-xl shadow transition whitespace-nowrap flex items-center justify-center gap-2 cursor-pointer"
                >
                  <span>➕</span> Agregar a la Lista
                </button>
              </form>

              <!-- FEEDBACK RÁPIDO / ANIMAL RECIÉN AGREGADO -->
              ${this.ultimoAnimalCargado ? `
                <div class="p-3 bg-purple-100/70 border border-purple-300 rounded-xl flex items-center justify-between text-xs text-purple-950 animate-fadeIn">
                  <div class="flex items-center gap-2">
                    <span class="text-base">${(this.ultimoAnimalCargado.especie || '').toLowerCase() === 'bufalino' ? '🦬' : '🐂'}</span>
                    <span class="font-mono font-black text-sm text-purple-900">${this.ultimoAnimalCargado.identificacionTag}</span>
                    <span class="font-bold">${this.ultimoAnimalCargado.nombreAlias || 'Sin Alias'}</span>
                    <span class="text-slate-600 font-mono">(${this.ultimoAnimalCargado.raza || 'Común'})</span>
                    <span class="bg-purple-200 text-purple-800 px-2 py-0.5 rounded text-[10px] font-bold">Lote: ${this.ultimoAnimalCargado.lote || 'General'}</span>
                  </div>
                  <span class="text-emerald-700 font-bold text-[11px]">✓ En lista de traslado</span>
                </div>
              ` : ''}

              ${this.mensajeFeedback ? `
                <div class="p-2.5 bg-amber-100 border border-amber-300 text-amber-900 rounded-xl text-xs font-bold flex items-center justify-between">
                  <span>⚠️ ${this.mensajeFeedback}</span>
                  <button type="button" id="btn-cerrar-feedback" class="text-amber-700 font-bold hover:text-amber-900 cursor-pointer">✕</button>
                </div>
              ` : ''}

              <!-- BOTÓN OPCIONAL: AGREGAR TODO UN LOTE -->
              ${lotesOrigen.length > 0 ? `
                <div class="flex items-center justify-between pt-1 text-xs text-slate-500">
                  <span>O agrega los animales de un lote completo:</span>
                  <div class="flex items-center gap-2">
                    <select id="sel-lote-completo-traslado" class="px-2.5 py-1 bg-white border border-slate-300 rounded-lg text-xs font-bold text-slate-700 outline-none">
                      ${lotesOrigen.map((l) => `<option value="${l}">Lote ${l}</option>`).join('')}
                    </select>
                    <button type="button" id="btn-agregar-lote-completo" class="px-3 py-1 bg-slate-200 hover:bg-slate-300 font-bold text-slate-800 rounded-lg text-xs transition cursor-pointer">
                      + Agregar Lote
                    </button>
                  </div>
                </div>
              ` : ''}
            </div>
          </div>

          <!-- LISTA DE REGISTROS DE LA PLANILLA ACUMULADA -->
          <div class="p-4 sm:p-5">
            <div class="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2 mb-3">
              <h3 class="font-black text-slate-900 text-sm flex items-center gap-2">
                <span>📝</span> Animales Listados para Traslado
                <span class="text-xs font-mono font-bold px-2 py-0.5 rounded-full bg-purple-100 text-purple-800 border border-purple-200">
                  ${this.animalesSesion.length} Animales en Lista
                </span>
                <span class="text-xs text-slate-500 font-normal">
                  (${fOrigenObj ? fOrigenObj.nombre : 'Origen'} ➔ ${fDestinoObj ? fDestinoObj.nombre : 'Destino'})
                </span>
              </h3>

              <div class="flex items-center gap-2 w-full sm:w-auto justify-end">
                <button id="btn-limpiar-lista-traslado" class="px-3 py-2 bg-slate-100 hover:bg-slate-200 text-slate-600 font-bold rounded-xl text-xs transition cursor-pointer ${this.animalesSesion.length === 0 ? 'hidden' : ''}">
                  Limpiar Lista
                </button>
                ${!esSoloConsulta ? `
                  <button id="btn-guardar-traslado-sesion" class="w-full sm:w-auto px-6 py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white font-black rounded-xl text-xs shadow-lg transition active:scale-95 flex items-center justify-center gap-2 cursor-pointer ${this.animalesSesion.length === 0 || fincasDestino.length === 0 ? 'opacity-50 pointer-events-none' : ''}">
                    <span>💾</span> Confirmar y Guardar Traslado (${this.animalesSesion.length})
                  </button>
                ` : `
                  <span class="px-3 py-1.5 bg-amber-100 text-amber-800 rounded-xl text-xs font-bold">Modo Consulta</span>
                `}
              </div>
            </div>

            <!-- TABLA DESKTOP -->
            <div class="hidden md:block overflow-x-auto border border-slate-200 rounded-xl shadow-sm">
              <table class="w-full text-left text-xs border-collapse">
                <thead class="bg-slate-100 uppercase font-bold text-slate-700 text-[10px] border-b border-slate-200">
                  <tr>
                    <th class="p-3 w-10 text-center">#</th>
                    <th class="p-3">Tag / Arete</th>
                    <th class="p-3">Nombre & Raza</th>
                    <th class="p-3">Categoría</th>
                    <th class="p-3">Lote Origen ➔ Lote Destino</th>
                    <th class="p-3 text-right">Peso Actual</th>
                    <th class="p-3 w-12 text-center">✕</th>
                  </tr>
                </thead>
                <tbody class="divide-y divide-slate-100">
                  ${this.animalesSesion.length > 0 ? this.animalesSesion.map((a, idx) => {
                    const esBufalo = (a.especie || 'bovino').toLowerCase() === 'bufalino';
                    return `
                      <tr class="hover:bg-slate-50 transition">
                        <td class="p-3 text-center font-mono text-slate-400 font-bold">${idx + 1}</td>
                        <td class="p-3">
                          <div class="flex items-center gap-2">
                            <span>${esBufalo ? '🦬' : '🐂'}</span>
                            <span class="font-black font-mono text-slate-900 text-sm">${a.identificacionTag || a.numero}</span>
                          </div>
                        </td>
                        <td class="p-3">
                          <div class="font-bold text-slate-800">${a.nombreAlias || a.nombre || 'Sin Alias'}</div>
                          <div class="text-[10px] text-slate-500">${a.raza || 'Común'}</div>
                        </td>
                        <td class="p-3 font-semibold text-slate-700">${a.categoria || 'General'}</td>
                        <td class="p-3">
                          <span class="px-2 py-0.5 bg-slate-100 text-slate-700 rounded text-[10px] font-bold">${a.lote || 'General'}</span>
                          <span class="text-purple-600 font-bold mx-1">➔</span>
                          <span class="px-2 py-0.5 bg-purple-100 text-purple-900 rounded text-[10px] font-bold">${this.loteDestino || a.lote || 'General'}</span>
                        </td>
                        <td class="p-3 text-right font-black font-mono text-slate-800">
                          ${a.ultimoPesoKg || a.pesoActual ? `${a.ultimoPesoKg || a.pesoActual} kg` : '-'}
                        </td>
                        <td class="p-3 text-center">
                          <button data-action="quitar-animal-traslado" data-idx="${idx}" class="text-slate-400 hover:text-rose-600 font-black transition p-1.5 hover:bg-rose-50 rounded-lg cursor-pointer" title="Quitar de la lista de traslado">
                            ✕
                          </button>
                        </td>
                      </tr>
                    `;
                  }).join('') : `
                    <tr>
                      <td colspan="7" class="p-10 text-center text-slate-400">
                        <span class="text-3xl block mb-2">🎯</span>
                        <div class="font-bold text-slate-600 text-sm">No hay animales en la lista de traslado.</div>
                        <p class="text-xs mt-1">Digita o escanea el número de arete arriba en el cuadro de búsqueda para agregarlo a esta planilla.</p>
                      </td>
                    </tr>
                  `}
                </tbody>
              </table>
            </div>

            <!-- TARJETAS MÓVILES (CELULARES) -->
            <div class="md:hidden space-y-2 mt-3">
              ${this.animalesSesion.length > 0 ? this.animalesSesion.map((a, idx) => {
                const esBufalo = (a.especie || 'bovino').toLowerCase() === 'bufalino';
                return `
                  <div class="p-3 bg-white border border-slate-200 rounded-2xl shadow-sm flex items-center justify-between gap-2">
                    <div class="flex items-center gap-2.5">
                      <span class="text-xl">${esBufalo ? '🦬' : '🐂'}</span>
                      <div>
                        <div class="flex items-center gap-1.5">
                          <span class="font-black font-mono text-slate-900 text-sm">${a.identificacionTag || a.numero}</span>
                          <span class="text-[10px] font-bold text-slate-500">${a.nombreAlias || a.nombre || ''}</span>
                        </div>
                        <div class="text-[10px] text-slate-500 mt-0.5">
                          <span>${a.lote || 'General'} ➔ <strong class="text-purple-700">${this.loteDestino || 'Destino'}</strong></span>
                          ${a.ultimoPesoKg || a.pesoActual ? ` • <strong>${a.ultimoPesoKg || a.pesoActual} kg</strong>` : ''}
                        </div>
                      </div>
                    </div>
                    <button data-action="quitar-animal-traslado" data-idx="${idx}" class="p-2 text-rose-500 hover:bg-rose-50 rounded-xl font-black text-sm active:scale-95 cursor-pointer">
                      ✕
                    </button>
                  </div>
                `;
              }).join('') : `
                <div class="p-6 text-center text-slate-400 bg-white border border-dashed border-slate-200 rounded-2xl">
                  <span class="text-2xl block mb-1">🚚</span>
                  No hay animales en la lista de traslado. Digite aretes arriba para añadirlos.
                </div>
              `}
            </div>
          </div>
        ` : `
          <!-- PESTAÑA: HISTORIAL DE TRASLADOS REALIZADOS -->
          <div class="p-4 sm:p-6 space-y-4">
            <div class="flex items-center justify-between">
              <h3 class="font-black text-slate-900 text-sm flex items-center gap-2">
                <span>📋</span> Historial Cronológico de Movilización
                <span class="text-xs font-mono font-bold px-2 py-0.5 rounded-full bg-slate-100 text-slate-700">
                  ${traslados.length} Registros
                </span>
              </h3>
            </div>

            <div class="overflow-x-auto border border-slate-200 rounded-2xl shadow-sm">
              <table class="w-full text-left text-xs">
                <thead class="bg-slate-100 uppercase font-black text-[10px] text-slate-700 border-b border-slate-200">
                  <tr>
                    <th class="p-3">Fecha & Hora</th>
                    <th class="p-3">Arete / Animal</th>
                    <th class="p-3">Finca Origen</th>
                    <th class="p-3">Finca Destino</th>
                    <th class="p-3">Lote Destino</th>
                    <th class="p-3">Motivo</th>
                    <th class="p-3">Responsable</th>
                    ${!esSoloConsulta ? '<th class="p-3 text-center">Acción</th>' : ''}
                  </tr>
                </thead>
                <tbody class="divide-y divide-slate-100">
                  ${traslados.length > 0 ? traslados.map((t) => `
                    <tr class="hover:bg-slate-50 transition">
                      <td class="p-3 font-mono text-slate-600 whitespace-nowrap">
                        ${t.fecha}
                        <span class="block text-[10px] text-slate-400">${t.hora || ''}</span>
                      </td>
                      <td class="p-3">
                        <div class="font-black font-mono text-slate-900">${t.tag || t.animalTag || t.animalId}</div>
                        ${t.nombreAlias ? `<div class="text-[10px] text-slate-500">${t.nombreAlias}</div>` : ''}
                      </td>
                      <td class="p-3 font-semibold text-slate-700">${t.fincaOrigenNombre || t.fincaOrigenId}</td>
                      <td class="p-3 font-bold text-purple-900">${t.fincaDestinoNombre || t.fincaDestinoId}</td>
                      <td class="p-3 font-mono text-xs text-slate-700">${t.loteNuevo || '-'}</td>
                      <td class="p-3 text-slate-600 font-medium">${t.motivo || 'Rotación'}</td>
                      <td class="p-3 text-slate-500 text-[11px]">${t.responsable || '-'}</td>
                      ${!esSoloConsulta ? `
                        <td class="p-3 text-center">
                          <button class="btn-revertir-traslado-historial text-[10px] font-bold px-2.5 py-1 bg-rose-50 hover:bg-rose-100 text-rose-700 border border-rose-200 rounded-lg transition cursor-pointer" data-id="${t.id}" title="Revertir y devolver animal a su finca previa">
                            ↩️ Revertir
                          </button>
                        </td>
                      ` : ''}
                    </tr>
                  `).join('') : `
                    <tr>
                      <td colspan="8" class="p-10 text-center text-slate-400">
                        <span class="text-3xl block mb-2">🚚</span>
                        No hay traslados registrados en el historial todavía.
                      </td>
                    </tr>
                  `}
                </tbody>
              </table>
            </div>
          </div>
        `}
      </div>
    `;

    this.attachEvents();
  }

  attachEvents() {
    if (!this.container) return;

    // Subtabs manga vs historial
    const btnTabManga = this.container.querySelector('#btn-subtab-manga');
    if (btnTabManga) {
      btnTabManga.addEventListener('click', () => {
        this.vistaSubTab = 'manga';
        this.render();
      });
    }

    const btnTabHist = this.container.querySelector('#btn-subtab-historial');
    if (btnTabHist) {
      btnTabHist.addEventListener('click', () => {
        this.vistaSubTab = 'historial';
        this.render();
      });
    }

    // Finca Origen
    const selOrigen = this.container.querySelector('#sel-finca-origen-traslado');
    if (selOrigen) {
      selOrigen.addEventListener('change', (e) => {
        const nuevaOrigen = e.target.value;
        if (nuevaOrigen !== this.fincaOrigenId) {
          this.fincaOrigenId = nuevaOrigen;
          this.animalesSesion = [];
          this.ultimoAnimalCargado = null;
          this.mensajeFeedback = null;
          this.render();
        }
      });
    }

    // Finca Destino
    const selDestino = this.container.querySelector('#sel-finca-destino-traslado');
    if (selDestino) {
      selDestino.addEventListener('change', (e) => {
        this.fincaDestinoId = e.target.value;
      });
    }

    // Fecha
    const inFecha = this.container.querySelector('#input-fecha-traslado');
    if (inFecha) {
      inFecha.addEventListener('change', (e) => {
        this.fechaTraslado = e.target.value;
      });
    }

    // Motivo
    const selMotivo = this.container.querySelector('#sel-motivo-traslado');
    if (selMotivo) {
      selMotivo.addEventListener('change', (e) => {
        this.motivo = e.target.value;
      });
    }

    // Lote Destino
    const inLoteDestino = this.container.querySelector('#input-lote-destino-traslado');
    if (inLoteDestino) {
      inLoteDestino.addEventListener('input', (e) => {
        this.loteDestino = e.target.value;
      });
    }

    // Observaciones
    const inObs = this.container.querySelector('#input-obs-traslado');
    if (inObs) {
      inObs.addEventListener('input', (e) => {
        this.observaciones = e.target.value;
      });
    }

    // Buscador en manga (form submit & autosuggest en vivo)
    const formBusq = this.container.querySelector('#form-buscar-traslado-manga');
    const inTag = this.container.querySelector('#input-tag-traslado-manga');

    if (inTag) {
      conectarAutosuggestAnimales({
        inputElement: inTag,
        getAnimales: () => {
          const todos = this.getAnimales ? this.getAnimales() : [];
          return todos.filter((a) => a.fincaId === this.fincaOrigenId);
        },
        onSeleccionar: (animal) => {
          this.agregarAnimalATraslado(animal);
        },
        theme: 'purple',
        textoVacio: 'Sin animales en finca origen con esos números o letras'
      });
    }

    if (formBusq) {
      formBusq.addEventListener('submit', (e) => {
        e.preventDefault();
        const tag = inTag ? inTag.value.trim() : '';
        if (!tag) return;

        const animal = this.buscarAnimalPorTag(tag);
        if (!animal) {
          this.mensajeFeedback = `No se encontró ningún ejemplar registrado con arete o número "${tag}".`;
          this.render();
          return;
        }

        this.agregarAnimalATraslado(animal);
      });
    }

    // Cerrar feedback
    const btnCerrarFeed = this.container.querySelector('#btn-cerrar-feedback');
    if (btnCerrarFeed) {
      btnCerrarFeed.addEventListener('click', () => {
        this.mensajeFeedback = null;
        this.render();
      });
    }

    // Agregar lote completo
    const btnLoteCompleto = this.container.querySelector('#btn-agregar-lote-completo');
    if (btnLoteCompleto) {
      btnLoteCompleto.addEventListener('click', () => {
        const selLote = this.container.querySelector('#sel-lote-completo-traslado');
        const loteVal = selLote ? selLote.value : null;
        if (!loteVal) return;

        const todosAnimales = this.getAnimales ? this.getAnimales() : [];
        const delLote = todosAnimales.filter(
          (a) => a.fincaId === this.fincaOrigenId &&
                 (a.lote === loteVal) &&
                 !this.animalesSesion.some((item) => item.id === a.id) &&
                 (a.estadoVida === 'activo' || !a.estadoVida)
        );

        if (delLote.length === 0) {
          alert(`Todos los animales del lote "${loteVal}" ya están en la lista o no hay animales activos.`);
          return;
        }

        delLote.forEach((a) => this.animalesSesion.push(a));
        this.mensajeFeedback = null;
        this.render();
      });
    }

    // Quitar animal individual de la planilla
    this.container.querySelectorAll('[data-action="quitar-animal-traslado"]').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const idx = parseInt(e.currentTarget.getAttribute('data-idx'));
        if (!isNaN(idx)) {
          this.animalesSesion.splice(idx, 1);
          this.render();
        }
      });
    });

    // Limpiar lista
    const btnLimpiar = this.container.querySelector('#btn-limpiar-lista-traslado');
    if (btnLimpiar) {
      btnLimpiar.addEventListener('click', () => {
        if (confirm('¿Deseas limpiar todos los animales de la lista de traslado actual?')) {
          this.animalesSesion = [];
          this.ultimoAnimalCargado = null;
          this.mensajeFeedback = null;
          this.render();
        }
      });
    }

    // Botón Guardar Traslado
    const btnGuardar = this.container.querySelector('#btn-guardar-traslado-sesion');
    if (btnGuardar) {
      btnGuardar.addEventListener('click', () => {
        if (this.animalesSesion.length === 0) {
          alert('Por favor agrega al menos un animal a la lista de traslado.');
          return;
        }
        if (!this.fincaDestinoId || this.fincaDestinoId === this.fincaOrigenId) {
          alert('Por favor selecciona una finca destino válida y diferente al origen.');
          return;
        }

        const fincas = this.getFincas ? this.getFincas() : [];
        const fOrig = fincas.find((f) => f.id === this.fincaOrigenId);
        const fDest = fincas.find((f) => f.id === this.fincaDestinoId);

        const fecha = this.container.querySelector('#input-fecha-traslado')?.value || this.fechaTraslado;
        const motivo = this.container.querySelector('#sel-motivo-traslado')?.value || this.motivo;
        const loteDestino = this.container.querySelector('#input-lote-destino-traslado')?.value || this.loteDestino;
        const obs = this.container.querySelector('#input-obs-traslado')?.value || this.observaciones;

        const conf = confirm(
          `¿Confirmar el traslado de ${this.animalesSesion.length} animales?\n\n` +
          `• Finca Origen: ${fOrig ? fOrig.nombre : this.fincaOrigenId}\n` +
          `• Finca Destino: ${fDest ? fDest.nombre : this.fincaDestinoId}\n` +
          `• Fecha: ${fecha}\n` +
          `• Motivo: ${motivo}\n` +
          `• Lote Destino: ${loteDestino}`
        );
        if (!conf) return;

        if (this.onEjecutarTraslado) {
          const ok = this.onEjecutarTraslado({
            animalIds: this.animalesSesion.map((a) => a.id),
            fincaOrigenId: this.fincaOrigenId,
            fincaDestinoId: this.fincaDestinoId,
            fecha,
            motivo,
            loteDestino,
            observaciones: obs
          });
          if (ok !== false) {
            this.animalesSesion = [];
            this.ultimoAnimalCargado = null;
            this.mensajeFeedback = null;
            this.vistaSubTab = 'historial';
            this.render();
          }
        }
      });
    }

    // Revertir traslado en historial
    this.container.querySelectorAll('.btn-revertir-traslado-historial').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const id = e.currentTarget.getAttribute('data-id');
        if (confirm('¿Deseas revertir este traslado y devolver el ejemplar a su predio original?')) {
          if (this.onRevertirTraslado) this.onRevertirTraslado(id);
          this.render();
        }
      });
    });
  }
}


// ============================================================================
// ARCHIVO: frontend/src/components/ModuloIngresosDiarios.js
// ============================================================================
/**
 * GANADERO AD - REGISTRO GENERAL DE ACTIVIDADES & AUDITORÍA DE DATOS
 * Bitácora central de todos los datos ingresados al sistema ganadero:
 * pesajes, destetes, partos, traslados entre fincas, palpaciones, servicios reproductivos, etc.
 * Con buscador superior en tiempo real, filtro por fecha o acción, y exportación a Excel (.CSV).
 */

class ModuloIngresosDiarios {
  constructor({
    containerId = 'pantalla-ingresos',
    getFincas,
    getFincaActiva,
    getAnimales,
    getOperaciones,
    getIngresosPorFecha,
    getFechasConRegistros,
    getRol,
    onVerFicha
  }) {
    this.containerId = containerId;
    this.container = typeof document !== 'undefined' ? document.getElementById(containerId) : null;
    this.getFincas = getFincas;
    this.getFincaActiva = getFincaActiva;
    this.getAnimales = getAnimales;
    this.getOperaciones = getOperaciones;
    this.getIngresosPorFecha = getIngresosPorFecha;
    this.getFechasConRegistros = getFechasConRegistros;
    this.getRol = getRol;
    this.onVerFicha = onVerFicha;

    this.filtroTexto = '';
    this.filtroAccion = 'todas';
    this.filtroFinca = 'todas';
    this.filtroFecha = '';
    this.fechaSeleccionada = '';
    this.filtroRango = 'todo'; // 'todo' | 'hoy' | '7dias' | '30dias'
  }

  init() {
    if (typeof document !== 'undefined') {
      this.container = document.getElementById(this.containerId);
    }
    this.render();
  }

  render() {
    if (!this.container && typeof document !== 'undefined') {
      this.container = document.getElementById(this.containerId);
    }
    if (!this.container) return;

    const fincas = this.getFincas ? this.getFincas() : [];
    const fActiva = this.getFincaActiva ? this.getFincaActiva() : null;

    // Obtener actividades filtradas
    let operaciones = [];
    if (this.getOperaciones) {
      operaciones = this.getOperaciones({
        texto: this.filtroTexto,
        accion: this.filtroAccion,
        finca: this.filtroFinca,
        fecha: this.filtroFecha || this.fechaSeleccionada || '',
        rango: this.filtroRango
      });
    } else if (this.getIngresosPorFecha) {
      const f = this.filtroFecha || this.fechaSeleccionada || '';
      operaciones = this.getIngresosPorFecha(f, this.filtroFinca || 'todas', this.filtroAccion === 'todas' ? 'todos' : this.filtroAccion) || [];
    }

    // Calcular estadísticas sobre los registros filtrados (soportando singular y plural)
    const totalRegistros = operaciones.length;
    const pesajes = operaciones.filter((o) => o.accion === 'pesajes' || o.modulo === 'pesajes' || o.accion === 'pesaje');
    const partos = operaciones.filter((o) => o.accion === 'partos' || o.modulo === 'partos' || o.accion === 'parto');
    const destetes = operaciones.filter((o) => o.accion === 'destetes' || o.modulo === 'destetes' || o.accion === 'destete');
    const traslados = operaciones.filter((o) => o.accion === 'traslados' || o.modulo === 'traslados' || o.accion === 'traslado');
    const palpaciones = operaciones.filter((o) => o.accion === 'palpaciones' || o.modulo === 'palpaciones' || o.accion === 'palpacion');
    const servicios = operaciones.filter((o) => o.accion === 'servicios' || o.modulo === 'servicios' || o.accion === 'servicio');
    const leches = operaciones.filter((o) => o.accion === 'leche' || o.modulo === 'leche' || o.accion === 'pesaje_leche' || o.modulo === 'lecheria');

    // Métricas de pesaje
    let pesoPromedio = 0;
    let gdpPromedio = 0;
    if (pesajes.length > 0) {
      const pesajesValidos = pesajes.filter((p) => p.peso !== undefined && p.peso !== null && !isNaN(p.peso));
      if (pesajesValidos.length > 0) {
        pesoPromedio = Math.round(pesajesValidos.reduce((acc, p) => acc + parseFloat(p.peso), 0) / pesajesValidos.length);
      }
      const gdpsValidos = pesajes.filter((p) => p.gdp !== undefined && p.gdp !== null && !isNaN(p.gdp));
      if (gdpsValidos.length > 0) {
        gdpPromedio = Math.round(gdpsValidos.reduce((acc, p) => acc + parseFloat(p.gdp), 0) / gdpsValidos.length);
      }
    }

    // Métrica de preñez en palpaciones
    let pctPrenez = 0;
    if (palpaciones.length > 0) {
      const prenadas = palpaciones.filter((p) => {
        const res = (p.resultado || p.detalle || '').toLowerCase();
        return res.includes('preñada') || res.includes('positiv');
      }).length;
      pctPrenez = Math.round((prenadas / palpaciones.length) * 100);
    }

    this.container.innerHTML = `
      <div class="bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden space-y-4 pb-6">
        <!-- CABECERA PRINCIPAL SUPERIOR -->
        <div class="bg-gradient-to-r from-blue-950 via-slate-900 to-indigo-950 text-white p-4 sm:p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div class="flex items-center gap-3">
            <div class="w-11 h-11 rounded-2xl bg-blue-600/20 text-blue-300 border border-blue-500/30 flex items-center justify-center text-2xl shadow-inner">
              📅
            </div>
            <div>
              <h2 class="text-base sm:text-lg font-black tracking-tight flex items-center gap-2">
                <span>Registro General de Actividades & Auditoría de Datos</span>
                <span class="text-[10px] uppercase font-mono px-2 py-0.5 rounded bg-blue-500/20 text-blue-300 border border-blue-400/30">
                  Bitácora de Campo
                </span>
              </h2>
              <p class="text-xs text-slate-300 mt-0.5">Historial unificado de todos los datos ingresados: pesajes, destetes, partos, traslados y servicios.</p>
            </div>
          </div>

          <!-- BOTONES DE EXPORTACIÓN A EXCEL -->
          <div class="flex items-center gap-2 w-full md:w-auto flex-wrap justify-end">
            <button 
              id="btn-exportar-actual-excel" 
              class="px-4 py-2 bg-emerald-600 hover:bg-emerald-500 active:scale-95 text-white font-black text-xs rounded-xl shadow-lg transition flex items-center gap-1.5 cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed"
              ${totalRegistros === 0 ? 'disabled' : ''}
              title="Descargar los registros visibles actualmente en formato Excel CSV"
            >
              <span>📥</span> Exportar a Excel (.CSV)
            </button>
            <div class="relative inline-block text-left">
              <select id="sel-exportar-grupo-rapido" class="px-3 py-2 bg-slate-800 hover:bg-slate-700 text-blue-300 font-bold text-xs rounded-xl border border-slate-700 outline-none cursor-pointer">
                <option value="" selected disabled>📥 Exportar Grupo...</option>
                <option value="pesajes">⚖️ Exportar Pesajes</option>
                <option value="partos">🍼 Exportar Partos y Destetes</option>
                <option value="traslados">🚚 Exportar Traslados</option>
                <option value="palpaciones">🩺 Exportar Reproducción</option>
                <option value="todo">🌐 Exportar Todo el Historial</option>
              </select>
            </div>
          </div>
        </div>

        <!-- BARRA SUPERIOR DE BÚSQUEDA Y FILTROS INTEGRADOS -->
        <div class="px-4 sm:px-6 space-y-3">
          <!-- BUSCADOR UNIVERSAL EN VIVO -->
          <div class="relative">
            <span class="absolute left-3.5 top-3 text-slate-400 text-sm">🔍</span>
            <input 
              type="text" 
              id="input-busqueda-actividades" 
              placeholder="Buscar por arete, nombre, finca (ej. Vesubio), técnico, lote, diagnóstico o nota..." 
              value="${this.filtroTexto}" 
              class="w-full pl-10 pr-4 py-2.5 bg-slate-50 hover:bg-white text-slate-900 font-bold text-xs rounded-xl border-2 border-slate-300 focus:border-blue-500 focus:bg-white outline-none transition shadow-sm"
            >
          </div>

          <!-- FILTROS CRUZADOS: ACCIÓN, FINCA, FECHA Y RANGO -->
          <div class="p-3 bg-slate-50 border border-slate-200 rounded-2xl flex flex-col md:flex-row justify-between items-stretch md:items-center gap-3 text-xs">
            <div class="flex items-center gap-2 flex-wrap">
              <!-- FILTRO ACCIÓN -->
              <div class="flex items-center gap-1">
                <span class="font-bold text-slate-600 text-[11px] whitespace-nowrap">⚡ Acción:</span>
                <select id="sel-filtro-accion" class="px-3 py-1.5 rounded-xl border border-slate-300 bg-white font-bold text-xs text-slate-800 outline-none cursor-pointer">
                  <option value="todas" ${this.filtroAccion === 'todas' ? 'selected' : ''}>🌐 Todas las Acciones (${totalRegistros})</option>
                  <option value="pesajes" ${this.filtroAccion === 'pesajes' ? 'selected' : ''}>⚖️ Pesajes (${pesajes.length})</option>
                  <option value="partos" ${this.filtroAccion === 'partos' ? 'selected' : ''}>🍼 Partos (${partos.length})</option>
                  <option value="destetes" ${this.filtroAccion === 'destetes' ? 'selected' : ''}>🌾 Destetes (${destetes.length})</option>
                  <option value="traslados" ${this.filtroAccion === 'traslados' ? 'selected' : ''}>🚚 Traslados (${traslados.length})</option>
                  <option value="palpaciones" ${this.filtroAccion === 'palpaciones' ? 'selected' : ''}>🩺 Palpaciones (${palpaciones.length})</option>
                  <option value="servicios" ${this.filtroAccion === 'servicios' ? 'selected' : ''}>🧬 Servicios IA/Monta (${servicios.length})</option>
                  <option value="leche" ${this.filtroAccion === 'leche' ? 'selected' : ''}>🥛 Control Lechero (${leches.length})</option>
                </select>
              </div>

              <!-- FILTRO FINCA -->
              <div class="flex items-center gap-1">
                <span class="font-bold text-slate-600 text-[11px] whitespace-nowrap">🏡 Finca:</span>
                <select id="sel-filtro-finca" class="px-3 py-1.5 rounded-xl border border-slate-300 bg-white font-bold text-xs text-slate-800 outline-none cursor-pointer">
                  <option value="todas" ${this.filtroFinca === 'todas' ? 'selected' : ''}>🌐 Todas las Fincas</option>
                  ${fincas.map((f) => `<option value="${f.id}" ${this.filtroFinca === f.id ? 'selected' : ''}>${f.nombre}</option>`).join('')}
                </select>
              </div>
            </div>

            <!-- FILTRO DE FECHA CON RANGOS RÁPIDOS -->
            <div class="flex items-center gap-1.5 flex-wrap">
              <span class="font-bold text-slate-600 text-[11px] whitespace-nowrap">📅 Fecha:</span>
              <input 
                type="date" 
                id="input-filtro-fecha" 
                value="${this.filtroFecha}" 
                class="px-2.5 py-1 rounded-xl border border-slate-300 bg-white font-mono font-bold text-xs text-slate-800 outline-none cursor-pointer"
              >
              <button id="btn-rango-todo" class="px-2.5 py-1 rounded-lg border font-bold text-[11px] transition cursor-pointer ${this.filtroRango === 'todo' && !this.filtroFecha ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-slate-700 border-slate-200 hover:bg-slate-100'}">
                Todo
              </button>
              <button id="btn-rango-hoy" class="px-2.5 py-1 rounded-lg border font-bold text-[11px] transition cursor-pointer ${this.filtroRango === 'hoy' || this.filtroFecha === new Date().toISOString().split('T')[0] ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-slate-700 border-slate-200 hover:bg-slate-100'}">
                Hoy
              </button>
              <button id="btn-rango-7dias" class="px-2.5 py-1 rounded-lg border font-bold text-[11px] transition cursor-pointer ${this.filtroRango === '7dias' ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-slate-700 border-slate-200 hover:bg-slate-100'}">
                7 Días
              </button>
              <button id="btn-rango-30dias" class="px-2.5 py-1 rounded-lg border font-bold text-[11px] transition cursor-pointer ${this.filtroRango === '30dias' ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-slate-700 border-slate-200 hover:bg-slate-100'}">
                30 Días
              </button>
              ${(this.filtroTexto || this.filtroAccion !== 'todas' || this.filtroFinca !== 'todas' || this.filtroFecha || this.filtroRango !== 'todo') ? `
                <button id="btn-limpiar-todos-filtros" class="px-2 py-1 text-[11px] font-bold text-rose-600 hover:underline cursor-pointer">
                  ✕ Limpiar Filtros
                </button>
              ` : ''}
            </div>
          </div>

          <!-- TARJETAS DE RESUMEN KPI DE LA CONSULTA -->
          <div class="grid grid-cols-2 sm:grid-cols-5 gap-3">
            <div class="bg-slate-50 border border-slate-200 p-3 rounded-2xl">
              <span class="text-[10px] font-bold uppercase text-slate-500 block">Total Actividades</span>
              <div class="text-xl font-black font-mono text-slate-900 mt-0.5">${totalRegistros}</div>
              <span class="text-[10px] text-slate-400">Registros en consulta</span>
            </div>

            <div class="bg-blue-50/60 border border-blue-200 p-3 rounded-2xl">
              <span class="text-[10px] font-bold uppercase text-blue-900 block">⚖️ Pesajes Realizados</span>
              <div class="text-xl font-black font-mono text-blue-900 mt-0.5">${pesajes.length}</div>
              <span class="text-[10px] text-blue-700 font-bold block">
                ${pesoPromedio > 0 ? `Prom: ${pesoPromedio} kg ${gdpPromedio ? `| GDP: ${gdpPromedio} g/d` : ''}` : 'Sin mediciones'}
              </span>
            </div>

            <div class="bg-amber-50/60 border border-amber-200 p-3 rounded-2xl">
              <span class="text-[10px] font-bold uppercase text-amber-900 block">🍼 Partos & Destetes</span>
              <div class="text-xl font-black font-mono text-amber-900 mt-0.5">${partos.length + destetes.length}</div>
              <span class="text-[10px] text-amber-700 font-bold block">${partos.length} Nacimientos | ${destetes.length} Destetados</span>
            </div>

            <div class="bg-purple-50/60 border border-purple-200 p-3 rounded-2xl">
              <span class="text-[10px] font-bold uppercase text-purple-900 block">🚚 Traslados entre Fincas</span>
              <div class="text-xl font-black font-mono text-purple-900 mt-0.5">${traslados.length}</div>
              <span class="text-[10px] text-purple-700 font-bold block">Movilizaciones de lote</span>
            </div>

            <div class="bg-emerald-50/60 border border-emerald-200 p-3 rounded-2xl">
              <span class="text-[10px] font-bold uppercase text-emerald-900 block">🩺 Chequeos Repro</span>
              <div class="text-xl font-black font-mono text-emerald-900 mt-0.5">${palpaciones.length + servicios.length}</div>
              <span class="text-[10px] text-emerald-700 font-bold block">${palpaciones.length} Palpaciones (${pctPrenez}% preñez) | ${servicios.length} Servicios</span>
            </div>
          </div>

          <!-- TABLA DE ACTIVIDADES DETALLADAS -->
          <div class="border border-slate-200 rounded-2xl overflow-hidden shadow-sm">
            <div class="hidden md:block overflow-x-auto max-h-[60vh]">
              <table class="w-full text-left text-xs border-collapse">
                <thead class="bg-slate-100 text-slate-700 uppercase font-black text-[10px] sticky top-0 z-10 border-b border-slate-200">
                  <tr>
                    <th class="p-3">Fecha & Hora</th>
                    <th class="p-3">Acción / Evento</th>
                    <th class="p-3">Arete / Animal</th>
                    <th class="p-3">Nombre & Raza</th>
                    <th class="p-3">Finca</th>
                    <th class="p-3">Detalle de la Operación</th>
                    <th class="p-3">Lote / Ubicación</th>
                    <th class="p-3">Responsable</th>
                    <th class="p-3 text-center">Ficha</th>
                  </tr>
                </thead>
                <tbody class="divide-y divide-slate-100">
                  ${operaciones.length > 0 ? operaciones.map((op) => {
                    let badgeClass = 'bg-slate-100 text-slate-800 border-slate-200';
                    let icono = '📋';
                    let nombreAccion = op.accion || op.modulo || 'Operación';

                    if (op.accion === 'pesajes' || op.modulo === 'pesajes') {
                      badgeClass = 'bg-blue-100 text-blue-800 border-blue-300';
                      icono = '⚖️';
                      nombreAccion = 'Pesaje';
                    } else if (op.accion === 'partos' || op.modulo === 'partos') {
                      badgeClass = 'bg-amber-100 text-amber-900 border-amber-300';
                      icono = '🍼';
                      nombreAccion = 'Parto';
                    } else if (op.accion === 'destetes' || op.modulo === 'destetes') {
                      badgeClass = 'bg-orange-100 text-orange-900 border-orange-300';
                      icono = '🌾';
                      nombreAccion = 'Destete';
                    } else if (op.accion === 'traslados' || op.modulo === 'traslados') {
                      badgeClass = 'bg-purple-100 text-purple-900 border-purple-300';
                      icono = '🚚';
                      nombreAccion = 'Traslado';
                    } else if (op.accion === 'palpaciones' || op.modulo === 'palpaciones') {
                      badgeClass = 'bg-rose-100 text-rose-900 border-rose-300';
                      icono = '🩺';
                      nombreAccion = 'Palpación';
                    } else if (op.accion === 'servicios' || op.modulo === 'servicios') {
                      badgeClass = 'bg-indigo-100 text-indigo-900 border-indigo-300';
                      icono = '🧬';
                      nombreAccion = 'Servicio / IA';
                    } else if (op.accion === 'leche' || op.modulo === 'leche') {
                      badgeClass = 'bg-cyan-100 text-cyan-900 border-cyan-300';
                      icono = '🥛';
                      nombreAccion = 'Leche';
                    } else if (op.accion === 'altas' || op.modulo === 'altas') {
                      badgeClass = 'bg-emerald-100 text-emerald-900 border-emerald-300';
                      icono = '🏷️';
                      nombreAccion = 'Alta Animal';
                    }

                    const esBufalo = (op.especie || '').toLowerCase() === 'bufalino';

                    return `
                      <tr class="hover:bg-slate-50 transition">
                        <td class="p-3 font-mono text-slate-600 whitespace-nowrap">
                          ${op.fecha || '-'}
                          <span class="block text-[10px] text-slate-400">${op.hora || ''}</span>
                        </td>
                        <td class="p-3 whitespace-nowrap">
                          <span class="px-2.5 py-1 rounded-full text-[10px] font-bold inline-flex items-center gap-1 border ${badgeClass}">
                            <span>${icono}</span> ${nombreAccion}
                          </span>
                        </td>
                        <td class="p-3">
                          <div class="flex items-center gap-1.5">
                            <span>${esBufalo ? '🦬' : '🐂'}</span>
                            <span class="font-black font-mono text-slate-900 text-sm">${op.tag || '-'}</span>
                          </div>
                        </td>
                        <td class="p-3">
                          <div class="font-bold text-slate-800">${op.nombreAlias || 'Sin Alias'}</div>
                          <div class="text-[10px] text-slate-500">${op.raza || 'Común'} ${op.categoria ? `• ${op.categoria}` : ''}</div>
                        </td>
                        <td class="p-3 font-semibold text-slate-700 whitespace-nowrap">
                          🏡 ${op.fincaNombre || op.fincaId || '-'}
                        </td>
                        <td class="p-3">
                          <div class="font-bold text-slate-800">${op.detalle || '-'}</div>
                          ${op.subDetalle ? `<div class="text-[10px] text-slate-500 font-mono">${op.subDetalle}</div>` : ''}
                        </td>
                        <td class="p-3 text-slate-600 font-mono text-[11px]">
                          ${op.lote || op.loteUbicacion || '-'}
                        </td>
                        <td class="p-3 text-slate-500 text-[11px]">
                          ${op.responsable || '-'}
                          ${op.observaciones ? `<div class="text-[10px] text-slate-400 italic mt-0.5">${op.observaciones}</div>` : ''}
                        </td>
                        <td class="p-3 text-center">
                          ${op.animalId ? `
                            <button class="btn-ver-ficha-actividad px-2.5 py-1 bg-slate-900 hover:bg-slate-800 text-white rounded-lg font-bold text-[10px] transition cursor-pointer" data-id="${op.animalId}">
                              🔍 Ficha
                            </button>
                          ` : '-'}
                        </td>
                      </tr>
                    `;
                  }).join('') : `
                    <tr>
                      <td colspan="9" class="p-12 text-center text-slate-400">
                        <span class="text-3xl block mb-2">📋</span>
                        <div class="font-bold text-slate-600 text-sm">No se encontraron actividades registradas con los filtros seleccionados.</div>
                        <p class="text-xs mt-1">Prueba seleccionando "Todo el Historial" o limpiando el texto de búsqueda.</p>
                      </td>
                    </tr>
                  `}
                </tbody>
              </table>
            </div>

            <!-- FEED MÓVIL DE ACTIVIDADES (CELULARES) -->
            <div class="md:hidden space-y-2.5 p-3 max-h-[70vh] overflow-y-auto">
              ${operaciones.length > 0 ? operaciones.map((op) => {
                let badgeClass = 'bg-slate-100 text-slate-800 border-slate-200';
                let icono = '📋';
                let nombreAccion = op.accion || op.modulo || 'Operación';

                if (op.accion === 'pesajes' || op.modulo === 'pesajes') {
                  badgeClass = 'bg-blue-100 text-blue-800 border-blue-300';
                  icono = '⚖️';
                  nombreAccion = 'Pesaje';
                } else if (op.accion === 'partos' || op.modulo === 'partos') {
                  badgeClass = 'bg-amber-100 text-amber-900 border-amber-300';
                  icono = '🍼';
                  nombreAccion = 'Parto';
                } else if (op.accion === 'destetes' || op.modulo === 'destetes') {
                  badgeClass = 'bg-orange-100 text-orange-900 border-orange-300';
                  icono = '🌾';
                  nombreAccion = 'Destete';
                } else if (op.accion === 'traslados' || op.modulo === 'traslados') {
                  badgeClass = 'bg-purple-100 text-purple-900 border-purple-300';
                  icono = '🚚';
                  nombreAccion = 'Traslado';
                } else if (op.accion === 'palpaciones' || op.modulo === 'palpaciones') {
                  badgeClass = 'bg-rose-100 text-rose-900 border-rose-300';
                  icono = '🩺';
                  nombreAccion = 'Palpación';
                } else if (op.accion === 'servicios' || op.modulo === 'servicios') {
                  badgeClass = 'bg-indigo-100 text-indigo-900 border-indigo-300';
                  icono = '🧬';
                  nombreAccion = 'Servicio / IA';
                } else if (op.accion === 'leche' || op.modulo === 'leche') {
                  badgeClass = 'bg-cyan-100 text-cyan-900 border-cyan-300';
                  icono = '🥛';
                  nombreAccion = 'Leche';
                } else if (op.accion === 'altas' || op.modulo === 'altas') {
                  badgeClass = 'bg-emerald-100 text-emerald-900 border-emerald-300';
                  icono = '🏷️';
                  nombreAccion = 'Alta Animal';
                }

                const esBufalo = (op.especie || '').toLowerCase() === 'bufalino';

                return `
                  <div class="p-3 bg-white rounded-2xl border border-slate-200 shadow-sm space-y-2">
                    <div class="flex items-center justify-between gap-2">
                      <span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold inline-flex items-center gap-1 border ${badgeClass}">
                        <span>${icono}</span> ${nombreAccion}
                      </span>
                      <span class="font-mono text-[10px] text-slate-500 font-bold">
                        ${op.fecha || ''} ${op.hora || ''}
                      </span>
                    </div>

                    <div class="flex items-center justify-between gap-2">
                      <div class="flex items-center gap-2">
                        <span class="text-xl shrink-0">${esBufalo ? '🦬' : '🐂'}</span>
                        <div>
                          <div class="font-black font-mono text-slate-900 text-sm">${op.tag || 'Sin Arete'}</div>
                          <div class="text-[10px] text-slate-500">${op.nombreAlias || 'Sin Alias'} ${op.raza ? `• ${op.raza}` : ''}</div>
                        </div>
                      </div>
                      ${op.animalId ? `
                        <button class="btn-ver-ficha-actividad px-3 py-1.5 bg-slate-900 hover:bg-slate-800 active:scale-95 text-white rounded-xl font-bold text-xs transition cursor-pointer" data-id="${op.animalId}">
                          🔍 Ficha
                        </button>
                      ` : ''}
                    </div>

                    <div class="bg-slate-50 p-2.5 rounded-xl border border-slate-100 text-xs">
                      <div class="font-bold text-slate-800">${op.detalle || '-'}</div>
                      ${op.subDetalle ? `<div class="text-[10px] text-slate-500 font-mono mt-0.5">${op.subDetalle}</div>` : ''}
                    </div>

                    <div class="flex items-center justify-between text-[10px] text-slate-500 pt-0.5">
                      <span>🏡 ${op.fincaNombre || op.fincaId || '-'} • 📍 ${op.lote || op.loteUbicacion || 'General'}</span>
                      <span>${op.responsable || ''}</span>
                    </div>
                  </div>
                `;
              }).join('') : `
                <div class="p-8 text-center text-slate-400 bg-white rounded-2xl">
                  <span class="text-3xl block mb-2">📋</span>
                  No se encontraron actividades registradas con los filtros seleccionados.
                </div>
              `}
            </div>
          </div>
        </div>
      </div>
    `;

    this.attachEvents();
  }

  exportarExcelCSV(grupo = null) {
    let dataset = this.getOperaciones
      ? this.getOperaciones({
          texto: this.filtroTexto,
          accion: grupo && grupo !== 'todo' ? grupo : this.filtroAccion,
          finca: this.filtroFinca,
          fecha: this.filtroFecha,
          rango: this.filtroRango
        })
      : [];

    if (grupo && grupo !== 'todo') {
      if (grupo === 'partos') {
        dataset = dataset.filter((o) => o.accion === 'partos' || o.accion === 'destetes');
      } else if (grupo === 'palpaciones') {
        dataset = dataset.filter((o) => o.accion === 'palpaciones' || o.accion === 'servicios');
      } else {
        dataset = dataset.filter((o) => o.accion === grupo || o.modulo === grupo);
      }
    }

    if (dataset.length === 0) {
      alert('No hay actividades disponibles para exportar con los filtros aplicados.');
      return;
    }

    const cabeceras = [
      'Fecha',
      'Hora',
      'Accion_Evento',
      'Arete_Tag',
      'Especie',
      'Nombre_Alias',
      'Raza',
      'Categoria',
      'Finca',
      'Detalle_Operacion',
      'Lote_Ubicacion',
      'Observaciones_Notas',
      'Responsable_Tecnico'
    ];

    const escapeCsv = (val) => {
      if (val === null || val === undefined) return '';
      let s = String(val).replace(/"/g, '""');
      if (s.includes(';') || s.includes('"') || s.includes('\n') || s.includes('\r')) {
        s = `"${s}"`;
      }
      return s;
    };

    const lineas = [cabeceras.join(';')];
    dataset.forEach((op) => {
      const fila = [
        escapeCsv(op.fecha),
        escapeCsv(op.hora || ''),
        escapeCsv(op.accion || op.modulo || 'Actividad'),
        escapeCsv(op.tag || ''),
        escapeCsv(op.especie || 'bovino'),
        escapeCsv(op.nombreAlias || ''),
        escapeCsv(op.raza || ''),
        escapeCsv(op.categoria || ''),
        escapeCsv(op.fincaNombre || op.fincaId || ''),
        escapeCsv(op.detalle || ''),
        escapeCsv(op.lote || op.loteUbicacion || ''),
        escapeCsv(op.observaciones || ''),
        escapeCsv(op.responsable || '')
      ];
      lineas.push(fila.join(';'));
    });

    const csvContent = '\uFEFF' + lineas.join('\r\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.href = url;
    const tagGrupo = grupo || this.filtroAccion || 'Actividades';
    const tagFinca = this.filtroFinca || 'Todas';
    a.download = `BoviTrack_Bitacora_${tagGrupo}_${tagFinca}_${new Date().toISOString().split('T')[0]}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }

  attachEvents() {
    if (!this.container) return;

    // Buscador texto en vivo
    const inBusq = this.container.querySelector('#input-busqueda-actividades');
    if (inBusq) {
      inBusq.addEventListener('input', (e) => {
        this.filtroTexto = e.target.value;
        this.render();
        const refoc = this.container.querySelector('#input-busqueda-actividades');
        if (refoc) {
          refoc.focus();
          const l = refoc.value.length;
          refoc.setSelectionRange(l, l);
        }
      });
    }

    // Filtro Acción
    const selAccion = this.container.querySelector('#sel-filtro-accion');
    if (selAccion) {
      selAccion.addEventListener('change', (e) => {
        this.filtroAccion = e.target.value;
        this.render();
      });
    }

    // Filtro Finca
    const selFinca = this.container.querySelector('#sel-filtro-finca');
    if (selFinca) {
      selFinca.addEventListener('change', (e) => {
        this.filtroFinca = e.target.value;
        this.render();
      });
    }

    // Input Fecha
    const inFecha = this.container.querySelector('#input-filtro-fecha');
    if (inFecha) {
      inFecha.addEventListener('change', (e) => {
        this.filtroFecha = e.target.value;
        this.filtroRango = 'todo';
        this.render();
      });
    }

    // Botones rápidos de rango
    const btnTodo = this.container.querySelector('#btn-rango-todo');
    if (btnTodo) {
      btnTodo.addEventListener('click', () => {
        this.filtroRango = 'todo';
        this.filtroFecha = '';
        this.render();
      });
    }

    const btnHoy = this.container.querySelector('#btn-rango-hoy');
    if (btnHoy) {
      btnHoy.addEventListener('click', () => {
        this.filtroRango = 'hoy';
        this.filtroFecha = new Date().toISOString().split('T')[0];
        this.render();
      });
    }

    const btn7Dias = this.container.querySelector('#btn-rango-7dias');
    if (btn7Dias) {
      btn7Dias.addEventListener('click', () => {
        this.filtroRango = '7dias';
        this.filtroFecha = '';
        this.render();
      });
    }

    const btn30Dias = this.container.querySelector('#btn-rango-30dias');
    if (btn30Dias) {
      btn30Dias.addEventListener('click', () => {
        this.filtroRango = '30dias';
        this.filtroFecha = '';
        this.render();
      });
    }

    // Limpiar todos los filtros
    const btnLimpiar = this.container.querySelector('#btn-limpiar-todos-filtros');
    if (btnLimpiar) {
      btnLimpiar.addEventListener('click', () => {
        this.filtroTexto = '';
        this.filtroAccion = 'todas';
        this.filtroFinca = 'todas';
        this.filtroFecha = '';
        this.filtroRango = 'todo';
        this.render();
      });
    }

    // Exportar vista actual
    const btnExportar = this.container.querySelector('#btn-exportar-actual-excel');
    if (btnExportar) {
      btnExportar.addEventListener('click', () => this.exportarExcelCSV());
    }

    // Exportar grupo rápido
    const selExpGrupo = this.container.querySelector('#sel-exportar-grupo-rapido');
    if (selExpGrupo) {
      selExpGrupo.addEventListener('change', (e) => {
        const grp = e.target.value;
        if (grp) {
          this.exportarExcelCSV(grp);
          selExpGrupo.value = '';
        }
      });
    }

    // Botones Ver Ficha
    this.container.querySelectorAll('.btn-ver-ficha-actividad').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const id = e.currentTarget.getAttribute('data-id');
        if (id && this.onVerFicha) {
          this.onVerFicha(id);
        }
      });
    });
  }
}


// ============================================================================
// ARCHIVO: frontend/src/components/ModuloNutricion.js
// ============================================================================
/**
 * GANADERO AD - MÓDULO ESPECIAL DE NUTRICIÓN ANIMAL & BIOTECNOLOGÍA IA
 * 
 * Permite seleccionar animales específicos mediante un buscador rápido estilo manga.
 * Solo estos animales forman parte del módulo y de las formulaciones de precisión:
 * - Sugerencias alimenticias por raza y estado reproductivo
 * - Prescripción de medicamentos, moduladores ruminales, suplementos y hormonas (IATF)
 * - Análisis fotográfico morfológico efímero (sin persistir la foto pesada en memoria)
 * - Persistencia y sincronización en tiempo real con Supabase Cloud
 */




class ModuloNutricion {
  constructor({
    containerId = 'pantalla-nutricion',
    getAnimales,
    getAnimalesBusqueda,
    getFincaActiva,
    getNutricion,
    onGuardarPlan,
    onEliminarRegistro,
    onVerFicha,
    onTrasladarAFinca,
    onReactivarAnimal
  }) {
    this.containerId = containerId;
    this.container = typeof document !== 'undefined' ? document.getElementById(containerId) : null;
    this.getAnimales = getAnimales;
    this.getAnimalesBusqueda = getAnimalesBusqueda;
    this.getFincaActiva = getFincaActiva;
    this.getNutricion = getNutricion;
    this.onGuardarPlan = onGuardarPlan;
    this.onEliminarRegistro = onEliminarRegistro;
    this.onVerFicha = onVerFicha;
    this.onTrasladarAFinca = onTrasladarAFinca;
    this.onReactivarAnimal = onReactivarAnimal;

    this.animalSeleccionado = null;
    this.planGenerado = null;
    this.analisisFotoEnCurso = false;
    this.mensajeFeedback = null;
    this.tipoFeedback = 'info'; // 'info' | 'exito' | 'error'
    this.filtroEtapa = 'todas';
    this.modoModalEvaluacion = false;
  }

  init() {
    if (typeof document !== 'undefined') {
      this.container = document.getElementById(this.containerId);
    }
    this.render();
  }

  getAnimalesEnrolados() {
    const todosAnimales = this.getAnimales ? this.getAnimales() : [];
    const registrosNutricion = this.getNutricion ? this.getNutricion() : [];

    // Mapear cada registro de nutrición al animal correspondiente
    const tagsEnrolados = new Set(registrosNutricion.map(r => String(r.tag || r.animalTag || '').toUpperCase()));

    // Los animales enrolados son aquellos que tienen un registro en nutricion
    const enrolados = [];
    registrosNutricion.forEach(reg => {
      const tag = String(reg.tag || reg.animalTag || '').toUpperCase();
      const animalData = todosAnimales.find(a => String(a.identificacionTag || a.numero || a.tag || '').toUpperCase() === tag) || {
        id: reg.animalId || ('ANM-' + tag),
        identificacionTag: tag,
        nombreAlias: reg.nombreAlias || '',
        raza: reg.raza || 'Comercial',
        sexo: 'Hembra',
        peso: reg.pesoActualKg || 420,
        categoria: reg.etapaProductiva || 'General',
        estadoReproductivo: reg.etapaProductiva || 'Vacía'
      };
      enrolados.push({
        ...animalData,
        registroNutricion: reg
      });
    });

    return enrolados;
  }

  enrolarAnimalPorTag(tagOAnimal) {
    if (!tagOAnimal) return;
    let animal = null;

    if (typeof tagOAnimal === 'object') {
      animal = tagOAnimal;
    } else {
      const cleanTag = String(tagOAnimal).trim().toUpperCase();
      const todos = this.getAnimalesBusqueda ? this.getAnimalesBusqueda() : (this.getAnimales ? this.getAnimales() : []);
      animal = todos.find(a => String(a.identificacionTag || a.numero || a.tag || '').toUpperCase() === cleanTag);

      if (animal) {
        if (animal._estaEnOtraFinca) {
          const confirmacion = confirm(`El animal "${animal.identificacionTag || animal.numero}" se encuentra registrado en la finca "${animal._fincaNombre || 'otra finca'}".\n\n¿Deseas trasladarlo inmediatamente a la finca en la que estás trabajando?`);
          if (confirmacion && typeof this.onTrasladarAFinca === 'function') {
            this.onTrasladarAFinca(animal);
          }
        } else if (animal._estaExtraido) {
          const motivo = animal.motivoBaja || animal._motivoExtraido || 'Baja';
          const confirmacion = confirm(`El animal "${animal.identificacionTag || animal.numero}" se encuentra actualmente EXTRAÍDO del hato (Motivo: ${motivo}).\n\n¿Deseas activarlo nuevamente en esta finca?`);
          if (confirmacion && typeof this.onReactivarAnimal === 'function') {
            this.onReactivarAnimal(animal);
          }
        }
      } else {
        // Permitir enrolar creando un registro provisional con ese Tag
        animal = {
          id: 'ANM-' + cleanTag,
          identificacionTag: cleanTag,
          nombreAlias: 'Ejemplar ' + cleanTag,
          raza: 'Brahman (Cebú)',
          sexo: 'Hembra',
          peso: 450,
          categoria: 'Vaca',
          estadoReproductivo: 'Vacía'
        };
      }
    }

    const registrosNutricion = this.getNutricion ? this.getNutricion() : [];
    const yaExiste = registrosNutricion.some(r => String(r.tag || r.animalTag || '').toUpperCase() === String(animal.identificacionTag || animal.tag).toUpperCase());

    if (yaExiste) {
      this.mensajeFeedback = `El ejemplar ${animal.identificacionTag || animal.tag} ya está en el grupo de Nutrición Especial.`;
      this.tipoFeedback = 'info';
      this.abrirEvaluacionParaAnimal(animal);
      return;
    }

    // Generar evaluación zootécnica inicial
    const planInicial = evaluarNutricionAnimal({
      animal,
      pesoActual: animal.ultimoPesoKg || animal.peso || 450,
      tallaCm: animal.tallaCm || null,
      tallaFrame: 'Medio (Frame 4-6)',
      condicionCorporal: 3.0
    });

    const nuevoRegistro = {
      id: 'NUT-' + Date.now() + '-' + Math.floor(Math.random() * 1000),
      animalId: animal.id,
      tag: animal.identificacionTag || animal.tag,
      animalTag: animal.identificacionTag || animal.tag,
      fechaAnalisis: new Date().toISOString().split('T')[0],
      etapaProductiva: planInicial.etapaProductiva,
      tallaCm: planInicial.tallaCm,
      tallaFrame: planInicial.tallaFrame,
      frameScore: planInicial.frameScore,
      categoriaFrame: planInicial.categoriaFrame,
      indiceCompacidadKgCm: planInicial.indiceCompacidadKgCm,
      statusCompacidad: planInicial.statusCompacidad,
      condicionCorporal: planInicial.condicionCorporal,
      pesoActualKg: planInicial.pesoActualKg,
      gdpEsperadaGDia: planInicial.gdpEsperadaGDia,
      sugerenciaDieta: planInicial.sugerenciaDieta,
      sugerenciaMedicamentos: planInicial.sugerenciaMedicamentos,
      sugerenciaSuplementos: planInicial.sugerenciaSuplementos,
      sugerenciaHormonas: planInicial.sugerenciaHormonas,
      analisisIA: planInicial.analisisIA,
      notas: ''
    };

    if (this.onGuardarPlan) {
      this.onGuardarPlan(nuevoRegistro);
    }

    this.mensajeFeedback = `✓ Ejemplar ${animal.identificacionTag || animal.tag} ingresado exitosamente al Módulo de Nutrición Especial.`;
    this.tipoFeedback = 'exito';
    this.abrirEvaluacionParaAnimal(animal);
  }

  retirarAnimalDelModulo(tag) {
    if (!tag) return;
    const cleanTag = String(tag).trim().toUpperCase();
    if (confirm(`¿Confirma retirar al ejemplar ${cleanTag} del Grupo de Nutrición Especial?`)) {
      if (this.onEliminarRegistro) {
        this.onEliminarRegistro(cleanTag);
      }
      if (this.animalSeleccionado && String(this.animalSeleccionado.identificacionTag || this.animalSeleccionado.tag).toUpperCase() === cleanTag) {
        this.modoModalEvaluacion = false;
        this.animalSeleccionado = null;
        this.planGenerado = null;
      }
      this.mensajeFeedback = `El ejemplar ${cleanTag} ha sido retirado del módulo de nutrición.`;
      this.tipoFeedback = 'info';
      this.render();
    }
  }

  abrirEvaluacionParaAnimal(animal) {
    this.animalSeleccionado = animal;
    this.modoModalEvaluacion = true;

    // Buscar si ya tiene un plan guardado
    const registros = this.getNutricion ? this.getNutricion() : [];
    const regGuardado = registros.find(r => String(r.tag || r.animalTag || '').toUpperCase() === String(animal.identificacionTag || animal.tag).toUpperCase());

    if (regGuardado) {
      this.planGenerado = {
        animalId: animal.id,
        animalTag: animal.identificacionTag || animal.tag,
        nombreAlias: animal.nombreAlias || animal.alias || '',
        raza: animal.raza || regGuardado.raza || 'Brahman',
        pesoActualKg: regGuardado.pesoActualKg || animal.peso || 450,
        tallaCm: regGuardado.tallaCm || (regGuardado.sugerenciaDieta && regGuardado.sugerenciaDieta.tallaCm) || (regGuardado.tallaFrame && regGuardado.tallaFrame.match(/(\d{2,3})\s*cm/i) ? Number(regGuardado.tallaFrame.match(/(\d{2,3})\s*cm/i)[1]) : null),
        tallaFrame: regGuardado.tallaFrame || 'Medio (Frame 4-6)',
        frameScore: regGuardado.frameScore || (regGuardado.sugerenciaDieta && regGuardado.sugerenciaDieta.frameScore) || null,
        categoriaFrame: regGuardado.categoriaFrame || (regGuardado.sugerenciaDieta && regGuardado.sugerenciaDieta.categoriaFrame) || '',
        indiceCompacidadKgCm: regGuardado.indiceCompacidadKgCm || (regGuardado.sugerenciaDieta && regGuardado.sugerenciaDieta.indiceCompacidadKgCm) || null,
        statusCompacidad: regGuardado.statusCompacidad || (regGuardado.sugerenciaDieta && regGuardado.sugerenciaDieta.statusCompacidad) || 'normal',
        condicionCorporal: regGuardado.condicionCorporal || 3.0,
        etapaProductiva: regGuardado.etapaProductiva || 'Vacía / Mantenimiento',
        gdpEsperadaGDia: regGuardado.gdpEsperadaGDia || 450,
        sugerenciaDieta: regGuardado.sugerenciaDieta || {},
        sugerenciaMedicamentos: regGuardado.sugerenciaMedicamentos || [],
        sugerenciaSuplementos: regGuardado.sugerenciaSuplementos || [],
        sugerenciaHormonas: regGuardado.sugerenciaHormonas || [],
        analisisIA: regGuardado.analisisIA || '',
        notas: regGuardado.notas || ''
      };
    } else {
      this.planGenerado = evaluarNutricionAnimal({
        animal,
        pesoActual: animal.ultimoPesoKg || animal.peso || 450,
        tallaCm: animal.tallaCm || null,
        tallaFrame: 'Medio (Frame 4-6)',
        condicionCorporal: 3.0
      });
    }

    this.render();
  }

  calcularPlanDesdeFormulario() {
    if (!this.animalSeleccionado || !this.container) return;

    const pesoInput = this.container.querySelector('#input-nutri-peso');
    const tallaCmInput = this.container.querySelector('#input-nutri-talla-cm');
    const tallaInput = this.container.querySelector('#input-nutri-talla');
    const bcsInput = this.container.querySelector('#input-nutri-bcs');
    const etapaInput = this.container.querySelector('#input-nutri-etapa');
    const gdpInput = this.container.querySelector('#input-nutri-gdp');
    const notasInput = this.container.querySelector('#input-nutri-notas');

    const peso = pesoInput ? Number(pesoInput.value) : (this.animalSeleccionado.ultimoPesoKg || this.animalSeleccionado.peso || 450);
    const tallaCm = tallaCmInput && tallaCmInput.value ? Number(tallaCmInput.value) : null;
    const talla = tallaInput ? tallaInput.value : 'Medio (Frame 4-6)';
    const bcs = bcsInput ? Number(bcsInput.value) : 3.0;
    const etapa = etapaInput ? etapaInput.value : 'Vacía / Mantenimiento';
    const gdp = gdpInput && gdpInput.value ? Number(gdpInput.value) : null;
    const notas = notasInput ? notasInput.value : '';

    this.planGenerado = evaluarNutricionAnimal({
      animal: this.animalSeleccionado,
      pesoActual: peso,
      tallaCm,
      tallaFrame: talla,
      condicionCorporal: bcs,
      etapaProductiva: etapa,
      gdpObjetivoGDia: gdp,
      notas
    });

    // Guardar automáticamente
    const registro = {
      id: 'NUT-' + Date.now() + '-' + Math.floor(Math.random() * 1000),
      animalId: this.animalSeleccionado.id,
      tag: this.animalSeleccionado.identificacionTag || this.animalSeleccionado.tag,
      animalTag: this.animalSeleccionado.identificacionTag || this.animalSeleccionado.tag,
      fechaAnalisis: new Date().toISOString().split('T')[0],
      etapaProductiva: this.planGenerado.etapaProductiva,
      tallaCm: this.planGenerado.tallaCm,
      tallaFrame: this.planGenerado.tallaFrame,
      frameScore: this.planGenerado.frameScore,
      categoriaFrame: this.planGenerado.categoriaFrame,
      indiceCompacidadKgCm: this.planGenerado.indiceCompacidadKgCm,
      statusCompacidad: this.planGenerado.statusCompacidad,
      condicionCorporal: this.planGenerado.condicionCorporal,
      pesoActualKg: this.planGenerado.pesoActualKg,
      gdpEsperadaGDia: this.planGenerado.gdpEsperadaGDia,
      sugerenciaDieta: this.planGenerado.sugerenciaDieta,
      sugerenciaMedicamentos: this.planGenerado.sugerenciaMedicamentos,
      sugerenciaSuplementos: this.planGenerado.sugerenciaSuplementos,
      sugerenciaHormonas: this.planGenerado.sugerenciaHormonas,
      analisisIA: this.planGenerado.analisisIA,
      notas: this.planGenerado.notas
    };

    if (this.onGuardarPlan) {
      this.onGuardarPlan(registro);
    }

    this.mensajeFeedback = `✓ Plan nutricional y biometría de pista actualizados para ${registro.tag} (${this.planGenerado.tallaCm} cm, Frame ${this.planGenerado.frameScore.toFixed(1)}).`;
    this.tipoFeedback = 'exito';
    this.render();
  }

  async procesarFotoEfimera(file) {
    if (!file) return;
    this.analisisFotoEnCurso = true;
    this.render();

    try {
      const resultadoFoto = await analizarMorfologiaFotoEfimera(file, this.animalSeleccionado);
      this.analisisFotoEnCurso = false;

      // Actualizar campos en el modal
      if (this.container) {
        const bcsInput = this.container.querySelector('#input-nutri-bcs');
        const bcsLabel = this.container.querySelector('#label-nutri-bcs');
        const tallaInput = this.container.querySelector('#input-nutri-talla');

        if (bcsInput) bcsInput.value = resultadoFoto.condicionCorporalEstimada;
        if (bcsLabel) bcsLabel.textContent = resultadoFoto.condicionCorporalEstimada.toFixed(2);
        if (tallaInput) tallaInput.value = resultadoFoto.tallaFrameEstimada;
        const tallaCmInput = this.container.querySelector('#input-nutri-talla-cm');
        if (tallaCmInput && resultadoFoto.tallaCmEstimada) {
          tallaCmInput.value = resultadoFoto.tallaCmEstimada;
        }
      }

      this.mensajeFeedback = `📸 ${resultadoFoto.observacionesIA} (La fotografía fue procesada y purgada efímeramente sin almacenar archivos en memoria).`;
      this.tipoFeedback = 'exito';

      // Recalcular plan con los nuevos parámetros estimados
      this.calcularPlanDesdeFormulario();
    } catch (err) {
      this.analisisFotoEnCurso = false;
      this.mensajeFeedback = 'Error analizando la fotografía: ' + err.message;
      this.tipoFeedback = 'error';
      this.render();
    }
  }

  imprimirPlanNutricional() {
    if (!this.planGenerado) return;
    window.print();
  }

  render() {
    if (!this.container) {
      if (typeof document !== 'undefined') {
        this.container = document.getElementById(this.containerId);
      }
      if (!this.container) return;
    }

    if (this.modoModalEvaluacion && this.animalSeleccionado) {
      this.container.innerHTML = this.renderPanelEvaluacion();
      this.enlazarEventos();
      return;
    }

    const enrolados = this.getAnimalesEnrolados();
    const finca = this.getFincaActiva ? this.getFincaActiva() : null;

    let html = `
      <div class="space-y-4">
        <!-- HEADER DEL MÓDULO -->
        <div class="bg-gradient-to-r from-emerald-950/70 via-slate-900 to-slate-900 p-4 sm:p-6 rounded-3xl border border-emerald-500/30 shadow-xl flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <div>
            <div class="flex items-center gap-2">
              <span class="text-2xl sm:text-3xl">🥗</span>
              <h2 class="text-xl sm:text-2xl font-black text-white">Módulo Especial de Nutrición Animal & Biotecnología IA</h2>
              <span class="px-2.5 py-0.5 rounded-full text-[10px] font-black bg-emerald-500/20 text-emerald-300 border border-emerald-500/40">PREDICCIÓN IA</span>
            </div>
            <p class="text-xs sm:text-sm text-slate-400 mt-1">
              Programa de precisión para animales seleccionados en manga: raciones por raza y estado reproductivo, medicamentos, minerales quelatados y visión fotográfica efímera.
            </p>
          </div>
          <div class="flex items-center gap-3">
            <div class="bg-slate-800/90 border border-slate-700 px-4 py-2 rounded-2xl flex items-center gap-3">
              <div class="text-right">
                <div class="text-[10px] text-slate-400 uppercase font-black">Grupo Especial</div>
                <div class="text-lg font-black text-emerald-400 font-mono">${enrolados.length} <span class="text-xs text-slate-300">Animales</span></div>
              </div>
              <span class="text-2xl">🧬</span>
            </div>
          </div>
        </div>

        <!-- MENSAJE FEEDBACK TEMPORAL -->
        ${this.mensajeFeedback ? `
          <div class="p-3.5 rounded-2xl text-xs font-bold flex items-center justify-between transition-all ${
            this.tipoFeedback === 'exito'
              ? 'bg-emerald-950/60 border border-emerald-500/50 text-emerald-300'
              : this.tipoFeedback === 'error'
              ? 'bg-rose-950/60 border border-rose-500/50 text-rose-300'
              : 'bg-blue-950/60 border border-blue-500/50 text-blue-300'
          }">
            <div class="flex items-center gap-2">
              <span>${this.tipoFeedback === 'exito' ? '✅' : this.tipoFeedback === 'error' ? '⚠️' : 'ℹ️'}</span>
              <span>${this.mensajeFeedback}</span>
            </div>
            <button id="btn-cerrar-feedback-nutri" class="text-slate-400 hover:text-white px-2 py-0.5 text-xs font-mono">✕</button>
          </div>
        ` : ''}

        <!-- BUSCADOR DE MANGA PARA AGREGAR ANIMALES ESPECÍFICOS -->
        <div class="bg-slate-900 p-4 sm:p-5 rounded-3xl border border-slate-800 space-y-3">
          <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 pb-2 border-b border-slate-800/80">
            <div class="flex items-center gap-2">
              <span class="text-base sm:text-lg">🔍</span>
              <span class="text-xs sm:text-sm font-black text-white uppercase tracking-wider">Buscador Rápido en Manga (Ingreso de Animales al Módulo)</span>
            </div>
            <span class="text-[10px] text-slate-400">Escriba el número de arete, tag o nombre para incluir el animal</span>
          </div>

          <div class="flex flex-col sm:flex-row items-stretch gap-2.5">
            <div class="relative flex-1">
              <input
                id="input-buscador-nutricion-manga"
                type="text"
                autocomplete="off"
                placeholder="Digitar arete (ej: BV-401, 112, Paloma, Murrah)..."
                class="w-full bg-slate-950 border border-slate-700 text-white px-4 py-3 rounded-2xl text-sm font-black placeholder-slate-500 focus:outline-none focus:border-emerald-500 transition shadow-inner font-mono"
              />
              <div id="dropdown-nutricion-autosuggest" class="hidden absolute left-0 right-0 top-full mt-1 bg-slate-900 border border-slate-700 rounded-2xl shadow-2xl z-50 max-h-60 overflow-y-auto divide-y divide-slate-800"></div>
            </div>
            <button
              id="btn-agregar-animal-nutricion"
              class="px-5 py-3 rounded-2xl bg-emerald-600 hover:bg-emerald-500 active:scale-95 text-white font-black text-xs sm:text-sm flex items-center justify-center gap-2 shadow-lg shadow-emerald-950 transition cursor-pointer shrink-0"
            >
              <span>➕</span>
              <span>Incluir en Nutrición Especial</span>
            </button>
          </div>
        </div>

        <!-- LISTADO DE ANIMALES ENROLADOS EN EL PROGRAMA ESPECIAL -->
        <div class="bg-slate-900 p-4 sm:p-6 rounded-3xl border border-slate-800 space-y-4">
          <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 pb-3 border-b border-slate-800">
            <div>
              <h3 class="text-sm sm:text-base font-black text-white flex items-center gap-2">
                <span>📋</span> Animales Activos en el Módulo (${enrolados.length})
              </h3>
              <p class="text-[11px] text-slate-400">Solo estos ejemplares específicos reciben seguimiento nutricional avanzado y planes IA</p>
            </div>
          </div>

          ${enrolados.length === 0 ? `
            <div class="py-12 px-4 text-center text-slate-400 space-y-3">
              <span class="text-4xl block">🌾</span>
              <p class="text-sm font-bold text-slate-300">No hay animales incluidos en el Módulo Especial de Nutrición aún.</p>
              <p class="text-xs text-slate-500 max-w-md mx-auto">
                Utilice el buscador de manga de arriba para seleccionar e incorporar ejemplares que requieran dietas especiales, biotecnología o seguimiento de condición corporal.
              </p>
            </div>
          ` : `
            <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3.5">
              ${enrolados.map(a => {
                const reg = a.registroNutricion || {};
                const bcs = reg.condicionCorporal || 3.0;
                const perfil = resolverPerfilRaza(a.raza);
                const esBuf = perfil.tipo === 'bufalo';

                return `
                  <div class="bg-slate-950 p-4 rounded-2xl border border-slate-800 hover:border-slate-700 transition flex flex-col justify-between space-y-3">
                    <div class="flex items-start justify-between gap-2">
                      <div>
                        <div class="flex items-center gap-1.5">
                          <span class="text-base">${esBuf ? '🐃' : '🐄'}</span>
                          <span class="text-sm font-black text-white font-mono">${a.identificacionTag || a.tag}</span>
                          ${a.nombreAlias ? `<span class="text-xs text-slate-300 font-bold">"${a.nombreAlias}"</span>` : ''}
                        </div>
                        <div class="text-[11px] text-emerald-400 font-semibold mt-0.5">${a.raza || 'Comercial'} • ${a.sexo || 'Hembra'}</div>
                      </div>
                      <button
                        class="btn-retirar-nutri text-slate-500 hover:text-rose-400 p-1.5 text-xs transition rounded-lg hover:bg-slate-900"
                        data-tag="${a.identificacionTag || a.tag}"
                        title="Retirar del grupo especial"
                      >
                        ✕
                      </button>
                    </div>

                    <div class="grid grid-cols-4 gap-1.5 bg-slate-900/80 p-2.5 rounded-xl text-center">
                      <div>
                        <div class="text-[9px] uppercase font-black text-slate-400">Peso (Báscula)</div>
                        <div class="text-xs font-black text-white font-mono">${a.ultimoPesoKg || reg.pesoActualKg || a.peso || '---'} kg</div>
                      </div>
                      <div>
                        <div class="text-[9px] uppercase font-black text-emerald-400">Talla</div>
                        <div class="text-xs font-black text-emerald-300 font-mono">${reg.tallaCm ? reg.tallaCm + 'cm' : (reg.tallaFrame && reg.tallaFrame.includes('cm') ? reg.tallaFrame.split(' ')[0] : '---')}</div>
                      </div>
                      <div>
                        <div class="text-[9px] uppercase font-black text-slate-400">BCS</div>
                        <div class="text-xs font-black ${bcs < 2.5 ? 'text-rose-400' : bcs > 3.75 ? 'text-amber-400' : 'text-emerald-400'} font-mono">${Number(bcs).toFixed(1)}/5</div>
                      </div>
                      <div>
                        <div class="text-[9px] uppercase font-black text-cyan-400">Frame</div>
                        <div class="text-xs font-black text-cyan-300 font-mono">${reg.frameScore ? 'FS ' + Number(reg.frameScore).toFixed(1) : (reg.sugerenciaDieta?.frameScore ? 'FS ' + Number(reg.sugerenciaDieta.frameScore).toFixed(1) : 'FS 5.0')}</div>
                      </div>
                    </div>

                    <div class="text-[11px] text-slate-300 bg-slate-900/50 p-2 rounded-xl border border-slate-800/60">
                      <div class="font-black text-slate-200 truncate">🌾 ${reg.etapaProductiva || a.categoria || 'Mantenimiento'}</div>
                      <div class="text-[10px] text-slate-400 truncate mt-0.5">Sal: ${reg.sugerenciaDieta?.formulaSalMineral ? reg.sugerenciaDieta.formulaSalMineral.slice(0, 38) + '...' : 'Sal mineralizada balanceada'}</div>
                    </div>

                    <div class="flex items-center gap-2 pt-1 border-t border-slate-800/80">
                      <button
                        class="btn-evaluar-nutri flex-1 py-2 rounded-xl bg-emerald-600/20 hover:bg-emerald-600/30 text-emerald-300 border border-emerald-500/40 text-xs font-black flex items-center justify-center gap-1.5 transition cursor-pointer"
                        data-tag="${a.identificacionTag || a.tag}"
                      >
                        <span>🔬</span>
                        <span>Plan & Diagnóstico IA</span>
                      </button>
                      ${this.onVerFicha ? `
                        <button
                          class="btn-ver-ficha-nutri p-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 text-xs font-bold transition cursor-pointer"
                          data-id="${a.id}"
                          title="Ver Ficha Zootécnica General"
                        >
                          👁️
                        </button>
                      ` : ''}
                    </div>
                  </div>
                `;
              }).join('')}
            </div>
          `}
        </div>

      </div>
    `;

    this.container.innerHTML = html;
    this.enlazarEventos();
  }

  renderPanelEvaluacion() {
    const animal = this.animalSeleccionado;
    const plan = this.planGenerado || {};
    const dieta = plan.sugerenciaDieta || {};
    const medicamentos = plan.sugerenciaMedicamentos || [];
    const suplementos = plan.sugerenciaSuplementos || [];
    const hormonas = plan.sugerenciaHormonas || [];
    const perfil = resolverPerfilRaza(animal.raza);
    const esBuf = perfil.tipo === 'bufalo';

    return `
      <div id="panel-evaluacion-nutricion" class="w-full flex flex-col space-y-4 fade-in">
        <div class="flex items-center">
          <button id="btn-cerrar-modal-nutri" class="px-5 py-2.5 rounded-2xl bg-slate-800 hover:bg-slate-700 text-slate-200 text-sm font-bold transition flex items-center gap-2 cursor-pointer shadow-lg active:scale-95 border border-slate-700">
            <span>⬅️</span> <span>Regresar a la Tabla de Todos los Animales</span>
          </button>
        </div>
        
        <div class="bg-slate-900 border border-slate-700 w-full rounded-3xl shadow-2xl overflow-hidden flex flex-col">
          
          <!-- PANEL HEADER -->
          <div class="bg-slate-950 p-4 sm:p-5 border-b border-slate-800 flex items-center justify-between shrink-0">
            <div class="flex items-center gap-3">
              <span class="text-2xl">${esBuf ? '🐃' : '🐄'}</span>
              <div>
                <div class="flex items-center gap-2">
                  <h3 class="text-base sm:text-lg font-black text-white font-mono">${animal.identificacionTag || animal.tag}</h3>
                  ${animal.nombreAlias ? `<span class="text-xs text-slate-300 font-bold">"${animal.nombreAlias}"</span>` : ''}
                  <span class="px-2 py-0.5 rounded-full text-[9px] font-black bg-emerald-500/20 text-emerald-300 border border-emerald-500/40">${perfil.nombre}</span>
                </div>
                <p class="text-[11px] text-slate-400">Evaluación Nutricional, Zootécnica y Prescripción IA</p>
              </div>
            </div>
            <div class="flex items-center gap-2">
              <button id="btn-imprimir-nutri" class="px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs font-bold transition flex items-center gap-1.5 cursor-pointer">
                <span>🖨️</span> <span class="hidden sm:inline">Imprimir Ficha</span>
              </button>
            </div>
          </div>

          <!-- CONTENIDO SCROLLABLE -->
          <div class="p-4 sm:p-6 overflow-y-auto space-y-6 flex-1">
            
            <!-- FORMULARIO DE PARÁMETROS DE CAMPO -->
            <div class="bg-slate-950 p-4 sm:p-5 rounded-2xl border border-slate-800 space-y-4">
              <div class="flex items-center justify-between">
                <h4 class="text-xs sm:text-sm font-black text-white flex items-center gap-2">
                  <span>⚙️</span> Parámetros Fisiológicos y de Campo
                </h4>
                <span class="text-[10px] text-slate-400">Actualice datos para regenerar la formulación</span>
              </div>

              <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-3">
                <div>
                  <label class="block text-[10px] font-black uppercase text-slate-400 mb-1">1. Peso en Báscula (kg)</label>
                  <input
                    id="input-nutri-peso"
                    type="number"
                    value="${animal.ultimoPesoKg || animal.peso || plan.pesoActualKg || 0}"
                    class="w-full bg-slate-900 border border-slate-700 text-slate-400 px-3 py-2 rounded-xl text-sm font-black font-mono outline-none cursor-not-allowed opacity-80"
                    readonly
                    title="El peso proviene de la báscula y no se puede editar aquí."
                  />
                </div>

                <div>
                  <div class="flex items-center justify-between mb-1">
                    <label class="text-[10px] font-black uppercase text-emerald-400">2. Talla (cm) *</label>
                    <span id="badge-frame-calc" class="text-[9px] px-1.5 py-0.2 rounded bg-emerald-500/20 text-emerald-300 font-mono font-bold">FS ${Number(plan.frameScore || 5.0).toFixed(1)}</span>
                  </div>
                  <input
                    id="input-nutri-talla-cm"
                    type="number"
                    step="0.5"
                    min="60"
                    max="190"
                    placeholder="ej. 138"
                    value="${plan.tallaCm || 135}"
                    class="w-full bg-slate-900 border border-emerald-500/60 text-emerald-300 px-3 py-2 rounded-xl text-sm font-black font-mono focus:border-emerald-400 outline-none shadow-sm"
                  />
                  <span class="text-[9px] text-slate-400 mt-0.5 block">Alzada cruz/grupa</span>
                </div>

                <div>
                  <label class="block text-[10px] font-black uppercase text-slate-400 mb-1">3. Categoría Frame</label>
                  <select
                    id="input-nutri-talla"
                    class="w-full bg-slate-900 border border-slate-700 text-white px-3 py-2 rounded-xl text-xs font-bold focus:border-emerald-500 outline-none cursor-pointer"
                  >
                    <option value="Bajo (Frame 1-3) - Compacto" ${String(plan.tallaFrame).includes('Bajo') ? 'selected' : ''}>Bajo (Frame 1-3) - Compacto</option>
                    <option value="Medio (Frame 4-6) - Estándar" ${!String(plan.tallaFrame).includes('Bajo') && !String(plan.tallaFrame).includes('Alto') ? 'selected' : ''}>Medio (Frame 4-6) - Estándar Pista</option>
                    <option value="Alto (Frame 7-9) - Longilíneo" ${String(plan.tallaFrame).includes('Alto') ? 'selected' : ''}>Alto (Frame 7-9) - Longilíneo</option>
                  </select>
                </div>

                <div>
                  <div class="flex items-center justify-between mb-1">
                    <label class="text-[10px] font-black uppercase text-slate-400">4. Condición Corporal</label>
                    <span id="label-nutri-bcs" class="text-xs font-black text-emerald-400 font-mono">${Number(plan.condicionCorporal || 3.0).toFixed(2)}</span>
                  </div>
                  <input
                    id="input-nutri-bcs"
                    type="range"
                    min="1.0"
                    max="5.0"
                    step="0.25"
                    value="${plan.condicionCorporal || 3.0}"
                    class="w-full accent-emerald-500 cursor-pointer"
                  />
                  <div class="flex justify-between text-[9px] text-slate-500 font-bold mt-0.5">
                    <span>1 (Flaca)</span>
                    <span>3 (Óptima Pista)</span>
                    <span>5 (Obesa)</span>
                  </div>
                </div>

                <div>
                  <label class="block text-[10px] font-black uppercase text-slate-400 mb-1">5. Etapa Exposición / Repro</label>
                  <select
                    id="input-nutri-etapa"
                    class="w-full bg-slate-900 border border-slate-700 text-white px-3 py-2 rounded-xl text-xs font-bold focus:border-emerald-500 outline-none cursor-pointer"
                  >
                    <option value="Terneros (0 - 7 meses) - Creep Feeding & Rumen" ${String(plan.etapaProductiva).includes('Ternero') ? 'selected' : ''}>1. Terneros (0-7 m) Creep Feeding & Rumen</option>
                    <option value="Novillas en Desarrollo (8 - 16 meses) - Altura de Pista" ${String(plan.etapaProductiva).includes('Novilla') ? 'selected' : ''}>2. Novillas Desarrollo (8-16 m) Altura Pista</option>
                    <option value="Vacas: Flushing & Prep. Reproductiva (21 días pre-servicio)" ${String(plan.etapaProductiva).includes('Flushing') ? 'selected' : ''}>3A. Vacas: Flushing Repro (21 d pre-servicio)</option>
                    <option value="Vacas: Gestación Media (CC 3.0 - 3.5)" ${String(plan.etapaProductiva).includes('Gestación') ? 'selected' : ''}>3B. Vacas: Gestación Media (CC 3.0-3.5)</option>
                    <option value="Vacas: Dieta de Transición Preparto (21 días pre-parto)" ${String(plan.etapaProductiva).includes('Preparto') || String(plan.etapaProductiva).includes('Transición') ? 'selected' : ''}>3C. Vacas: Preparto Transición (21 d)</option>
                    <option value="Vacas en Lactancia / Prep. Final de Feria (60 días pista)" ${String(plan.etapaProductiva).includes('Final de Feria') || String(plan.etapaProductiva).includes('Lactancia') ? 'selected' : ''}>4. Vacas Lactancia / Final Feria (60 d pista)</option>
                    <option value="Toro Reproductor" ${String(plan.etapaProductiva).includes('Toro') ? 'selected' : ''}>Toros: Reproductor de Pista</option>
                    <option value="Vaca Seca / Horra" ${String(plan.etapaProductiva).includes('Seca') ? 'selected' : ''}>Vaca Seca / Horra (Descanso)</option>
                  </select>
                </div>
              </div>

              <!-- BANNER DE BIOMETRÍA DE PISTA & ANÁLISIS DE CONFORMACIÓN -->
              <div class="bg-gradient-to-r from-slate-900 via-emerald-950/20 to-slate-900 p-3.5 rounded-xl border border-emerald-500/30 flex flex-col md:flex-row items-start md:items-center justify-between gap-3 text-xs">
                <div class="flex items-center gap-3 flex-wrap">
                  <div class="flex items-center gap-1.5 bg-slate-950/80 px-2.5 py-1 rounded-lg border border-slate-800">
                    <span class="text-slate-400 text-[10px] uppercase font-bold">Alzada:</span>
                    <span class="font-black text-emerald-300 font-mono">${plan.tallaCm || 135} cm</span>
                  </div>
                  <div class="flex items-center gap-1.5 bg-slate-950/80 px-2.5 py-1 rounded-lg border border-slate-800">
                    <span class="text-slate-400 text-[10px] uppercase font-bold">Frame Score:</span>
                    <span class="font-black text-cyan-300 font-mono">${Number(plan.frameScore || 5.0).toFixed(1)} / 9.0</span>
                    <span class="text-[10px] text-slate-300 font-semibold">(${plan.categoriaFrame || 'Estándar'})</span>
                  </div>
                  <div class="flex items-center gap-1.5 bg-slate-950/80 px-2.5 py-1 rounded-lg border border-slate-800">
                    <span class="text-slate-400 text-[10px] uppercase font-bold">Relación Peso/Talla:</span>
                    <span class="font-black text-amber-300 font-mono">${plan.indiceCompacidadKgCm ? Number(plan.indiceCompacidadKgCm).toFixed(2) + ' kg/cm' : (plan.pesoActualKg && plan.tallaCm ? (plan.pesoActualKg / plan.tallaCm).toFixed(2) + ' kg/cm' : '---')}</span>
                  </div>
                </div>
                <div class="text-[11px] text-slate-300 italic">
                  🎯 ${plan.sugerenciaDieta?.statusCompacidad === 'sobrepeso_riesgo' ? '⚠️ Precaución: Evitar depósitos grasos en ubre o cuello' : (plan.sugerenciaDieta?.statusCompacidad === 'subdesarrollo' ? '📈 Consolidar desarrollo muscular y arqueo' : '✨ Conformación y alzada óptimas de pista')}
                </div>
              </div>

              <!-- ZONA DE ESCANEO FOTOGRÁFICO MORFOLÓGICO EFÍMERO -->
              <div class="bg-gradient-to-r from-slate-900 to-slate-900/60 p-3.5 rounded-xl border border-emerald-500/30 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
                <div class="space-y-0.5">
                  <div class="flex items-center gap-1.5">
                    <span class="text-base">📸</span>
                    <span class="text-xs font-black text-white">Escaneo Morfológico Fotográfico con Visión IA</span>
                    <span class="px-2 py-0.2 rounded-full text-[9px] font-black bg-emerald-500/20 text-emerald-300 border border-emerald-500/40">100% EFÍMERO</span>
                  </div>
                  <p class="text-[10px] text-slate-400">
                    Sube una foto del ejemplar: la IA analiza contorno dorsal, apófisis y cobertura grasa para estimar BCS y talla en cm. <strong>La foto nunca se guarda en memoria</strong> para no saturar el almacenamiento.
                  </p>
                </div>

                <div class="flex items-center gap-2 shrink-0">
                  <label class="px-3.5 py-2 rounded-xl bg-slate-800 hover:bg-slate-700 active:scale-95 text-white font-bold text-xs flex items-center gap-2 cursor-pointer border border-slate-700 transition">
                    <span>${this.analisisFotoEnCurso ? '⏳' : '📷'}</span>
                    <span>${this.analisisFotoEnCurso ? 'Analizando...' : 'Subir / Tomar Foto'}</span>
                    <input id="input-foto-nutri-efimera" type="file" accept="image/*" capture="environment" class="hidden" />
                  </label>
                  <button
                    id="btn-recalcular-plan"
                    class="px-4 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-500 active:scale-95 text-white font-black text-xs flex items-center gap-1.5 shadow transition cursor-pointer"
                  >
                    <span>⚡</span>
                    <span>Actualizar Plan IA</span>
                  </button>
                </div>
              </div>
            </div>

            <!-- RESULTADO 1: DIETA & RACIÓN ZOOTÉCNICA -->
            <div class="bg-slate-950 p-4 sm:p-5 rounded-2xl border border-slate-800 space-y-3">
              <div class="flex items-center justify-between pb-2 border-b border-slate-800">
                <h4 class="text-xs sm:text-sm font-black text-white flex items-center gap-2">
                  <span>🌾</span> 1. Ración & Dieta Zootécnica de Precisión
                </h4>
                <span class="text-[10px] font-mono text-emerald-400 font-bold">GDP Proyectada: +${plan.gdpEsperadaGDia || 450} g/día</span>
              </div>

              <div class="grid grid-cols-2 sm:grid-cols-4 gap-2.5">
                <div class="bg-slate-900 p-3 rounded-xl border border-slate-800/80">
                  <div class="text-[9px] uppercase font-black text-slate-400">Materia Seca (CMS)</div>
                  <div class="text-base font-black text-white font-mono mt-0.5">${dieta.materiaSecaKgDia || 0} <span class="text-xs text-slate-400">kg/día</span></div>
                  <div class="text-[9px] text-slate-400 mt-0.5">Requerimiento base</div>
                </div>

                <div class="bg-slate-900 p-3 rounded-xl border border-slate-800/80">
                  <div class="text-[9px] uppercase font-black text-slate-400">Forraje Verde Fresco</div>
                  <div class="text-base font-black text-emerald-400 font-mono mt-0.5">${dieta.forrajeVerdeKgDia || 0} <span class="text-xs text-slate-400">kg/día</span></div>
                  <div class="text-[9px] text-slate-400 mt-0.5">Base fresca 22% MS</div>
                </div>

                <div class="bg-slate-900 p-3 rounded-xl border border-slate-800/80">
                  <div class="text-[9px] uppercase font-black text-slate-400">Concentrado Formulado</div>
                  <div class="text-base font-black text-amber-400 font-mono mt-0.5">${dieta.concentradoKgDia || 0} <span class="text-xs text-slate-400">kg/día</span></div>
                  <div class="text-[9px] text-slate-400 mt-0.5">${dieta.proteinaCrudaPorc || 14}% Prot. Cruda</div>
                </div>

                <div class="bg-slate-900 p-3 rounded-xl border border-slate-800/80">
                  <div class="text-[9px] uppercase font-black text-slate-400">Sal Mineralizada</div>
                  <div class="text-base font-black text-cyan-400 font-mono mt-0.5">${dieta.salMineralizadaGramosDia || 80} <span class="text-xs text-slate-400">g/día</span></div>
                  <div class="text-[9px] text-slate-400 mt-0.5">Con Fósforo y Selenio</div>
                </div>
              </div>

              <div class="bg-slate-900/60 p-3.5 rounded-xl text-xs space-y-1.5 border border-slate-800">
                <div class="text-slate-300 font-bold">🌿 Forraje Base: <span class="text-slate-200 font-normal">${dieta.tipoForrajeRecomendado || 'Pastura fresca y heno de excelente calidad'}</span></div>
                <div class="text-slate-300 font-bold">🥣 Ración Concentrada: <span class="text-slate-200 font-normal">${dieta.tipoConcentrado || 'Suplemento formulado'}</span></div>
                <div class="text-amber-300 font-bold">⏱️ Manejo de Comedero: <span class="text-slate-200 font-normal">${dieta.fraccionamientoRacion || (dieta.tomasAlimentacionDia ? `${dieta.tomasAlimentacionDia} tomas diarias` : '2 tomas diarias')}</span></div>
                ${dieta.aditivosPista && dieta.aditivosPista.length > 0 ? `
                  <div class="text-emerald-300 font-bold flex items-start gap-1">
                    <span class="shrink-0">✨ Aditivos de Pista:</span>
                    <span class="text-slate-300 font-normal">${dieta.aditivosPista.join(' • ')}</span>
                  </div>
                ` : ''}
                <div class="text-slate-300 font-bold">🧂 Sal Mineralizada: <span class="text-emerald-300 font-normal">${dieta.formulaSalMineral || 'Sal mineralizada balanceada'}</span></div>
                <div class="text-slate-300 font-bold">💧 Agua Requerida: <span class="text-cyan-300 font-mono font-bold">${dieta.recomendacionAguaLitrosDia || 50} litros/día</span> <span class="text-slate-400 font-normal">(limpia, fresca y a voluntad)</span></div>
              </div>
            </div>

            <!-- RESULTADO 2: MEDICAMENTOS & MODULADORES RUMINALES -->
            <div class="bg-slate-950 p-4 sm:p-5 rounded-2xl border border-slate-800 space-y-3">
              <h4 class="text-xs sm:text-sm font-black text-white flex items-center gap-2 pb-2 border-b border-slate-800">
                <span>💊</span> 2. Prescripción de Medicamentos & Sanidad Ruminal
              </h4>

              <div class="space-y-2.5">
                ${medicamentos.map(m => `
                  <div class="bg-slate-900 p-3 rounded-xl border border-slate-800 text-xs space-y-1">
                    <div class="flex items-center justify-between">
                      <span class="font-black text-white">${m.nombre}</span>
                      <span class="px-2 py-0.5 rounded text-[9px] font-black bg-blue-500/20 text-blue-300">${m.tipo}</span>
                    </div>
                    <div class="grid grid-cols-1 sm:grid-cols-3 gap-1.5 text-slate-300 pt-1">
                      <div><strong class="text-slate-400">Dosis:</strong> ${m.dosis}</div>
                      <div><strong class="text-slate-400">Vía:</strong> ${m.via}</div>
                      <div><strong class="text-slate-400">Frecuencia:</strong> ${m.frecuencia}</div>
                    </div>
                    ${m.advertenciaRetiro ? `
                      <div class="text-[10px] text-amber-300 bg-amber-950/40 px-2 py-1 rounded border border-amber-500/20 mt-1">
                        ⚠️ ${m.advertenciaRetiro}
                      </div>
                    ` : ''}
                  </div>
                `).join('')}
              </div>
            </div>

            <!-- RESULTADO 3: SUPLEMENTOS NUTRICIONALES, VITAMINAS & MINERALES QUELATADOS -->
            <div class="bg-slate-950 p-4 sm:p-5 rounded-2xl border border-slate-800 space-y-3">
              <h4 class="text-xs sm:text-sm font-black text-white flex items-center gap-2 pb-2 border-b border-slate-800">
                <span>💉</span> 3. Suplementos Nutricionales & Vitaminas de Alta Asimilación
              </h4>

              <div class="space-y-2.5">
                ${suplementos.map(s => `
                  <div class="bg-slate-900 p-3 rounded-xl border border-slate-800 text-xs space-y-1">
                    <div class="flex items-center justify-between">
                      <span class="font-black text-emerald-400">${s.nombre}</span>
                      <span class="text-[10px] text-slate-400 font-bold">${s.via}</span>
                    </div>
                    <p class="text-slate-300 text-[11px]">${s.objetivo}</p>
                    <div class="text-slate-400 text-[10px]"><strong class="text-slate-300">Dosis sugerida:</strong> ${s.dosisRecomendada}</div>
                  </div>
                `).join('')}
              </div>
            </div>

            <!-- RESULTADO 4: BIOTECNOLOGÍA & HORMONAS (IATF / SINCRONIZACIÓN) -->
            <div class="bg-slate-950 p-4 sm:p-5 rounded-2xl border border-slate-800 space-y-3">
              <h4 class="text-xs sm:text-sm font-black text-white flex items-center gap-2 pb-2 border-b border-slate-800">
                <span>🧬</span> 4. Protocolos Biotecnológicos & Hormonas Reproductivas
              </h4>

              <div class="space-y-2.5">
                ${hormonas.map(h => `
                  <div class="bg-slate-900 p-3 rounded-xl border border-slate-800 text-xs space-y-2">
                    <div class="flex items-center justify-between">
                      <span class="font-black text-purple-300">${h.nombre}</span>
                      <span class="text-[10px] text-purple-400 font-bold">${h.diasAplicacion}</span>
                    </div>
                    <p class="text-slate-300 text-[11px]">${h.indicacion}</p>
                    
                    ${Array.isArray(h.protocolo) ? `
                      <ul class="space-y-1 pl-4 list-disc text-slate-400 text-[11px]">
                        ${h.protocolo.map(p => `<li>${p}</li>`).join('')}
                      </ul>
                    ` : ''}

                    ${h.advertenciaSeguridad ? `
                      <div class="text-[10px] text-purple-300/90 bg-purple-950/40 px-2.5 py-1 rounded border border-purple-500/20">
                        🛡️ ${h.advertenciaSeguridad}
                      </div>
                    ` : ''}
                  </div>
                `).join('')}
              </div>
            </div>

            <!-- RESULTADO 5: DIAGNÓSTICO INTEGRAL IA -->
            <div class="bg-gradient-to-br from-emerald-950/40 via-slate-950 to-slate-950 p-4 sm:p-5 rounded-2xl border border-emerald-500/40 space-y-2">
              <div class="flex items-center gap-2">
                <span class="text-lg">🤖</span>
                <h4 class="text-xs sm:text-sm font-black text-emerald-300">Diagnóstico Zootécnico Integral de la Inteligencia Artificial</h4>
              </div>
              <p class="text-xs text-slate-300 leading-relaxed font-sans">
                ${plan.analisisIA || 'Análisis no disponible.'}
              </p>
            </div>

          </div>

          <!-- MODAL FOOTER -->
          <div class="bg-slate-950 p-4 border-t border-slate-800 flex items-center justify-end gap-3 shrink-0">
            <button id="btn-cerrar-modal-nutri-footer" class="px-4 py-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 text-xs font-bold transition cursor-pointer">
              Regresar a la Tabla
            </button>
            <button id="btn-guardar-plan-modal" class="px-5 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-black transition flex items-center gap-1.5 shadow cursor-pointer">
              <span>💾</span>
              <span>Guardar Plan en Ficha y Supabase</span>
            </button>
          </div>

        </div>
      </div>
    `;
  }

  enlazarEventos() {
    if (!this.container) return;

    // Cerrar feedback temporal
    const btnFeedback = this.container.querySelector('#btn-cerrar-feedback-nutri');
    if (btnFeedback) {
      btnFeedback.addEventListener('click', () => {
        this.mensajeFeedback = null;
        this.render();
      });
    }

    // Buscador rápido con Autosuggest
    const inputBuscador = this.container.querySelector('#input-buscador-nutricion-manga');
    const dropdownAutosuggest = this.container.querySelector('#dropdown-nutricion-autosuggest');
    const btnAgregar = this.container.querySelector('#btn-agregar-animal-nutricion');

    if (dropdownAutosuggest) {
      if (dropdownAutosuggest.style) dropdownAutosuggest.style.display = 'none';
      if (dropdownAutosuggest.classList && typeof dropdownAutosuggest.classList.add === 'function') {
        dropdownAutosuggest.classList.add('hidden');
      }
    }

    if (inputBuscador) {
      conectarAutosuggestAnimales({
        inputElement: inputBuscador,
        getAnimales: () => this.getAnimalesBusqueda ? this.getAnimalesBusqueda() : (this.getAnimales ? this.getAnimales() : []),
        theme: 'emerald',
        maxResultados: 6,
        onTrasladarAFinca: (animal) => {
          if (this.onTrasladarAFinca) this.onTrasladarAFinca(animal);
        },
        onReactivarAnimal: (animal) => {
          if (this.onReactivarAnimal) this.onReactivarAnimal(animal);
        },
        onSeleccionar: (animal) => {
          const tag = animal.identificacionTag || animal.numero;
          inputBuscador.value = tag;
          this.enrolarAnimalPorTag(animal);
        }
      });

      inputBuscador.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
          e.preventDefault();
          const tag = inputBuscador.value.trim();
          if (tag) {
            this.enrolarAnimalPorTag(tag);
          }
        }
      });
    }

    if (btnAgregar && inputBuscador) {
      btnAgregar.addEventListener('click', () => {
        const tag = inputBuscador.value.trim();
        if (tag) {
          this.enrolarAnimalPorTag(tag);
        } else {
          alert('Por favor ingrese el arete o tag del animal.');
        }
      });
    }

    // Botones de acción en tarjetas de animales
    this.container.querySelectorAll('.btn-evaluar-nutri').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const tag = e.currentTarget.getAttribute('data-tag');
        const todos = this.getAnimales ? this.getAnimales() : [];
        const animal = todos.find(a => String(a.identificacionTag || a.tag).toUpperCase() === String(tag).toUpperCase()) || {
          id: 'ANM-' + tag,
          identificacionTag: tag,
          tag,
          peso: 450,
          raza: 'Brahman (Cebú)'
        };
        this.abrirEvaluacionParaAnimal(animal);
      });
    });

    this.container.querySelectorAll('.btn-retirar-nutri').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const tag = e.currentTarget.getAttribute('data-tag');
        this.retirarAnimalDelModulo(tag);
      });
    });

    this.container.querySelectorAll('.btn-ver-ficha-nutri').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const id = e.currentTarget.getAttribute('data-id');
        if (this.onVerFicha) this.onVerFicha(id);
      });
    });

    // Eventos dentro del Modal de Evaluación
    if (this.modoModalEvaluacion) {
      const btnCerrar1 = this.container.querySelector('#btn-cerrar-modal-nutri');
      const btnCerrar2 = this.container.querySelector('#btn-cerrar-modal-nutri-footer');
      const cerrarModal = () => {
        this.modoModalEvaluacion = false;
        this.render();
      };
      if (btnCerrar1) btnCerrar1.addEventListener('click', cerrarModal);
      if (btnCerrar2) btnCerrar2.addEventListener('click', cerrarModal);

      // Slider BCS interactivo
      const inputBcs = this.container.querySelector('#input-nutri-bcs');
      const labelBcs = this.container.querySelector('#label-nutri-bcs');
      if (inputBcs && labelBcs) {
        inputBcs.addEventListener('input', () => {
          labelBcs.textContent = Number(inputBcs.value).toFixed(2);
        });
      }

      // Botón Recalcular Plan IA
      const btnRecalcular = this.container.querySelector('#btn-recalcular-plan');
      if (btnRecalcular) {
        btnRecalcular.addEventListener('click', () => {
          this.calcularPlanDesdeFormulario();
        });
      }

      // Input Foto Efímera
      const inputFoto = this.container.querySelector('#input-foto-nutri-efimera');
      if (inputFoto) {
        inputFoto.addEventListener('change', (e) => {
          if (e.target.files && e.target.files[0]) {
            this.procesarFotoEfimera(e.target.files[0]);
          }
        });
      }

      // Guardar Plan
      const btnGuardarModal = this.container.querySelector('#btn-guardar-plan-modal');
      if (btnGuardarModal) {
        btnGuardarModal.addEventListener('click', () => {
          this.calcularPlanDesdeFormulario();
          this.modoModalEvaluacion = false;
          this.render();
        });
      }

      // Imprimir Ficha
      const btnImprimir = this.container.querySelector('#btn-imprimir-nutri');
      if (btnImprimir) {
        btnImprimir.addEventListener('click', () => {
          this.imprimirPlanNutricional();
        });
      }
    }
  }
}


// ============================================================================
// ARCHIVO: frontend/src/components/CuadriculaMasiva.js
// ============================================================================
/**
 * GANADERO AD - INGRESO MASIVO RÁPIDO EN CAMPO (FLUJO UNO A UNO EN MANGA/BÁSCULA)
 * Permite buscar/digitar el número del animal uno a uno, cargar sus antecedentes,
 * registrar la medición con auditoría de IA y acumular la sesión de trabajo.
 */





class CuadriculaMasiva {
  constructor({ containerId, onGuardarRegistros, getAnimales, getLotes, onTrasladarAFinca, onReactivarAnimal, onExtraerAnimal }) {
    this.container = document.getElementById(containerId);
    this.onGuardarRegistros = onGuardarRegistros;
    this.getAnimales = getAnimales;
    this.getLotes = getLotes;
    this.onTrasladarAFinca = onTrasladarAFinca;
    this.onReactivarAnimal = onReactivarAnimal;
    this.onExtraerAnimal = onExtraerAnimal;
    this.moduloActivo = 'pesajes'; // 'pesajes' | 'palpaciones' | 'leche' | 'partos' | 'destetes' | 'extracciones'
    this.loteFiltro = 'todos';
    this.animalSeleccionado = null;
    this.fechaJornada = new Date().toISOString().split('T')[0];
    this.registrosSesion = []; // Acumulador de la sesión de trabajo en campo
  }

  init() {
    this.render();
  }

  cargarFilasDesdeInventario() {
    // Si la vista está visible, refrescar los datos desde el inventario del predio activo
    if (this.container && !this.container.classList.contains('hidden')) {
      this.render();
    }
  }

  setModulo(mod) {
    this.moduloActivo = mod;
    this.animalSeleccionado = null;
    this.render();
  }

  setLoteFiltro(lote) {
    this.loteFiltro = lote;
    this.render();
  }

  buscarAnimalPorTag(tag) {
    if (!tag) return null;
    const cleanTag = tag.trim().toUpperCase();
    const animales = this.getAnimales ? this.getAnimales() : [];

    let match = animales.find(
      (a) => (a.identificacionTag || a.numero || '').toUpperCase() === cleanTag
    );

    return match || null;
  }

  seleccionarAnimal(tag) {
    const animal = this.buscarAnimalPorTag(tag);
    this.animalSeleccionado = animal;
    this.renderFormularioIngreso();
  }

  render() {
    if (!this.container) return;

    const hoy = new Date().toISOString().split('T')[0];
    const lotes = this.getLotes ? this.getLotes() : [];
    const todosAnimales = (this.getAnimales ? this.getAnimales() : []).filter(
      (a) => a.estadoVida === 'activo' || a.estado === 'activo'
    );

    this.container.innerHTML = `
      <div class="bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden">
        <!-- BARRA SUPERIOR -->
        <div class="bg-gradient-to-r from-slate-950 via-slate-900 to-slate-950 text-white p-4 sm:p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-3">
          <div>
            <h2 class="text-base sm:text-lg font-black tracking-tight flex items-center gap-2">
              <span>📋</span> Cuadrícula Masiva: Ingreso de Campo en Báscula / Brete
              <span class="text-[10px] uppercase font-mono px-2 py-0.5 rounded bg-emerald-500/20 text-emerald-300 border border-emerald-400/30">Modo Uno a Uno</span>
            </h2>
            <p class="text-xs text-slate-400 mt-0.5">Ingresa el número de cada animal individualmente al pasar por la manga.</p>
          </div>

          <!-- Controles superiores: Fecha en que se hace el trabajo y Filtro rápido de Lote -->
          <div class="flex flex-wrap items-center gap-2.5 w-full md:w-auto">
            <div class="flex items-center gap-2 bg-slate-800/90 border border-slate-700 px-3 py-1.5 rounded-xl shadow-inner">
              <label for="input-fecha-jornada-manga" class="text-xs font-bold text-slate-200 whitespace-nowrap cursor-pointer">📅 Fecha en que se hace el trabajo:</label>
              <input type="date" id="input-fecha-jornada-manga" value="${this.fechaJornada || hoy}" title="Fecha en que se hace el trabajo (pesajes, palpaciones, partos, destetes...)" class="bg-slate-900 border border-slate-600 text-emerald-300 font-bold font-mono text-xs rounded-lg px-2.5 py-1 outline-none cursor-pointer focus:border-emerald-400">
            </div>
            <div class="flex items-center gap-1.5 bg-slate-800/90 border border-slate-700 px-3 py-1.5 rounded-xl shadow-inner">
              <span class="text-xs font-bold text-slate-300 whitespace-nowrap">📍 Lote:</span>
              <select id="select-filtro-lote" class="bg-slate-900 border border-slate-600 text-emerald-300 font-bold text-xs rounded-lg px-2 py-0.5 outline-none w-32 md:w-36">
                <option value="todos" ${this.loteFiltro === 'todos' ? 'selected' : ''}>Todos los Lotes</option>
                ${lotes.map((l) => `<option value="${l}" ${this.loteFiltro === l ? 'selected' : ''}>${l}</option>`).join('')}
              </select>
            </div>
          </div>
        </div>

        <!-- SELECTOR DE PESTAÑAS TOUCH (PESAJES, PALPACIONES, LECHE, PARTOS, DESTETES, EXTRACCIONES) -->
        <div class="grid grid-cols-2 sm:grid-cols-6 bg-slate-100 border-b border-slate-200 p-1.5 gap-1.5 text-xs">
          <button class="btn-grid-mod py-2.5 px-2 rounded-xl font-black transition flex items-center justify-center gap-1.5 ${this.moduloActivo === 'pesajes' ? 'bg-white text-emerald-800 shadow border border-slate-200' : 'text-slate-600 hover:bg-slate-200/70'}" data-mod="pesajes">
            <span>⚖️</span> Pesajes & GDP
          </button>
          <button class="btn-grid-mod py-2.5 px-2 rounded-xl font-black transition flex items-center justify-center gap-1.5 ${this.moduloActivo === 'palpaciones' ? 'bg-white text-emerald-800 shadow border border-slate-200' : 'text-slate-600 hover:bg-slate-200/70'}" data-mod="palpaciones">
            <span>✋</span> Palpaciones
          </button>
          <button class="btn-grid-mod py-2.5 px-2 rounded-xl font-black transition flex items-center justify-center gap-1.5 ${this.moduloActivo === 'leche' ? 'bg-white text-emerald-800 shadow border border-slate-200' : 'text-slate-600 hover:bg-slate-200/70'}" data-mod="leche">
            <span>🥛</span> Control Leche
          </button>
          <button class="btn-grid-mod py-2.5 px-2 rounded-xl font-black transition flex items-center justify-center gap-1.5 ${this.moduloActivo === 'partos' ? 'bg-white text-emerald-800 shadow border border-slate-200' : 'text-slate-600 hover:bg-slate-200/70'}" data-mod="partos">
            <span>🍼</span> Partos
          </button>
          <button class="btn-grid-mod py-2.5 px-2 rounded-xl font-black transition flex items-center justify-center gap-1.5 ${this.moduloActivo === 'destetes' ? 'bg-white text-emerald-800 shadow border border-slate-200' : 'text-slate-600 hover:bg-slate-200/70'}" data-mod="destetes">
            <span>🌾</span> Destetes
          </button>
          <button class="btn-grid-mod py-2.5 px-2 rounded-xl font-black transition flex items-center justify-center gap-1.5 ${this.moduloActivo === 'extracciones' ? 'bg-white text-rose-800 shadow border border-rose-300' : 'text-slate-600 hover:bg-slate-200/70'}" data-mod="extracciones">
            <span>🚪</span> Extracción Animales
          </button>
        </div>

        <!-- SECCIÓN DE BÚSQUEDA Y CAPTURA UNO A UNO EN MANGA -->
        <div class="p-4 sm:p-5 bg-emerald-50/40 border-b border-emerald-100">
          <div class="max-w-3xl mx-auto space-y-3">
            <!-- BUSCADOR RÁPIDO DE ARETE -->
            <div class="flex flex-col sm:flex-row items-center gap-3">
              <div class="relative w-full">
                <span class="absolute left-3.5 top-3 text-slate-400 text-sm">🔍</span>
                <input type="text" id="input-tag-manga" autofocus placeholder="Digite o escanee No. de animal (Ej. BV-401, 102)..." class="w-full pl-10 pr-4 py-3 bg-white text-slate-900 font-mono font-black text-base rounded-xl border-2 border-emerald-500 focus:ring-4 focus:ring-emerald-500/20 outline-none uppercase shadow-sm">
              </div>
              <button id="btn-buscar-manga" class="w-full sm:w-auto px-6 py-3 bg-emerald-600 hover:bg-emerald-500 text-white font-black text-sm rounded-xl shadow transition whitespace-nowrap active:scale-95 flex items-center justify-center gap-1.5">
                <span>🔍</span> Buscar
              </button>
            </div>

            <!-- CONTENEDOR DEL FORMULARIO DINÁMICO DEL ANIMAL CARGADO -->
            <div id="contenedor-formulario-animal">
              ${this.obtenerHtmlFormularioIngreso()}
            </div>
          </div>
        </div>

        <!-- LISTA DE REGISTROS DE LA SESIÓN ACTUAL (PLANILLA DE CAMPO ACUMULADA) -->
        <div class="p-4 sm:p-5">
          <div class="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2 mb-3">
            <h3 class="font-black text-slate-900 text-sm flex items-center gap-2">
              <span>📝</span> Planilla de la Sesión Actual
              <span class="text-xs font-mono font-bold px-2 py-0.5 rounded-full bg-slate-100 text-slate-700">
                ${this.registrosSesion.length} Registros Capturados
              </span>
            </h3>

            <div class="flex items-center gap-2 w-full sm:w-auto justify-end flex-wrap">
              <button id="btn-aplicar-fecha-sesion" class="px-3 py-1.5 bg-emerald-50 hover:bg-emerald-100 text-emerald-800 border border-emerald-300 font-bold rounded-xl text-xs transition flex items-center gap-1 cursor-pointer ${this.registrosSesion.length === 0 ? 'hidden' : ''}" title="Aplica la fecha activa a todos los registros de la sesión">
                <span>📅</span> Aplicar Fecha a la Sesión
              </button>
              <button id="btn-limpiar-sesion" class="px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-600 font-bold rounded-xl text-xs transition ${this.registrosSesion.length === 0 ? 'hidden' : ''}">
                Limpiar Sesión
              </button>
              <button id="btn-guardar-sesion" class="w-full sm:w-auto px-5 py-2 bg-emerald-600 hover:bg-emerald-500 text-white font-black rounded-xl text-xs shadow transition active:scale-95 flex items-center justify-center gap-1.5 ${this.registrosSesion.length === 0 ? 'opacity-50 pointer-events-none' : ''}">
                <span>💾</span> Guardar Todo en Base de Datos (${this.registrosSesion.length})
              </button>
            </div>
          </div>

          <div class="overflow-x-auto border border-slate-200 rounded-xl">
            <table class="w-full text-left text-xs border-collapse">
              <thead class="bg-slate-100 uppercase font-bold text-slate-700 text-[10px]">
                <tr>
                  <th class="p-2.5 w-10 text-center">#</th>
                  <th class="p-2.5">Tag / Arete</th>
                  <th class="p-2.5">📅 Fecha del Trabajo</th>
                  <th class="p-2.5">Especie</th>
                  <th class="p-2.5">Datos Registrados</th>
                  <th class="p-2.5 text-center">Auditoría / Indicador</th>
                  <th class="p-2.5 w-10 text-center">✕</th>
                </tr>
              </thead>
              <tbody class="divide-y divide-slate-100">
                ${this.registrosSesion.length > 0 ? this.registrosSesion.map((reg, idx) => `
                  <tr class="hover:bg-slate-50">
                    <td class="p-2.5 text-center font-mono text-slate-400">${idx + 1}</td>
                    <td class="p-2.5 font-black font-mono text-slate-900">${reg.tag}</td>
                    <td class="p-2.5 font-mono text-slate-600 font-bold whitespace-nowrap">${reg.fecha || this.fechaJornada}</td>
                    <td class="p-2.5">
                      <span class="px-2 py-0.5 rounded text-[10px] font-bold ${reg.especie === 'bufalino' ? 'bg-amber-100 text-amber-900' : 'bg-blue-100 text-blue-900'}">
                        ${reg.especie === 'bufalino' ? '🦬 Bufalino' : '🐂 Vacuno'}
                      </span>
                    </td>
                    <td class="p-2.5">${this.renderResumenMedicion(reg)}</td>
                    <td class="p-2.5 text-center">${this.renderBadgeMedicion(reg)}</td>
                    <td class="p-2.5 text-center">
                      <button data-action="delete-sesion-row" data-idx="${idx}" class="text-slate-300 hover:text-rose-600 transition p-1 cursor-pointer">✕</button>
                    </td>
                  </tr>
                `).join('') : `
                  <tr>
                    <td colspan="7" class="p-8 text-center text-slate-400">
                      <span class="text-2xl block mb-1">🎯</span>
                      Digite el primer animal arriba para cargarlo y registrar su medición.
                    </td>
                  </tr>
                `}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    `;

    this.renderFormularioIngreso();
    this.attachEvents();
  }

  obtenerHtmlFormularioIngreso() {
    if (!this.animalSeleccionado) {
      return `
        <div class="bg-white/80 p-4 rounded-xl border border-dashed border-emerald-300 text-center text-xs text-slate-500">
          Esperando número de animal en la manga para cargar historial de pesajes y palpaciones...
        </div>
      `;
    }

    const a = this.animalSeleccionado;
    const especie = a.especie || 'bovino';
    const tag = a.identificacionTag || a.numero;
    const hoy = new Date().toISOString().split('T')[0];

    let inputsModulo = '';

    if (this.moduloActivo === 'pesajes') {
      const pesoPrev = a.ultimoPesoKg || a.pesoActual || 0;
      const fechaPrev = a.fechaUltimoPesaje || a.ultimoPesajeFecha || '';
      inputsModulo = `
        <div class="grid grid-cols-1 sm:grid-cols-4 gap-3 bg-white p-4 rounded-xl border border-emerald-200">
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">📅 Fecha en que se pesó (Trabajo):</label>
            <input type="date" id="form-peso-fecha" value="${this.fechaJornada || hoy}" class="w-full px-2 py-3 sm:py-2 text-xs font-bold rounded-xl border border-slate-300 outline-none">
            <span class="text-[10px] text-slate-400 block mt-1">${pesoPrev ? `Previo: ${pesoPrev} kg (${fechaPrev || 'S/F'})` : (a.fechaNacimiento ? `Nacido: ${a.fechaNacimiento}` : 'Sin pesajes previos')}</span>
          </div>

          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Nuevo Peso en Báscula (kg):</label>
            <input type="number" step="0.5" inputmode="decimal" id="form-nuevo-peso" autofocus placeholder="Ej. 420.5" class="w-full px-3 py-3 sm:py-2 text-lg sm:text-base font-black font-mono text-emerald-800 bg-emerald-50 rounded-xl border-2 border-emerald-400 focus:bg-white focus:ring-2 focus:ring-emerald-500 outline-none text-right shadow-sm">
            <div id="live-gdp-indicator" class="text-xs font-bold mt-1 text-slate-500"></div>
          </div>

          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Condición Corporal:</label>
            <select id="form-condicion" class="w-full px-3 py-3 sm:py-2 bg-white text-xs font-bold rounded-xl border border-slate-300 outline-none">
              <option value="2.5">2.5 (Delgada)</option>
              <option value="3.0">3.0 (Regular)</option>
              <option value="3.5" selected>3.5 (Óptima)</option>
              <option value="4.0">4.0 (Buena)</option>
              <option value="4.5">4.5 (Excelente)</option>
            </select>
          </div>

          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Observaciones / Notas:</label>
            <input type="text" id="form-peso-notas" placeholder="Báscula, lote ceba..." class="w-full px-3 py-3 sm:py-2 text-xs rounded-xl border border-slate-300 outline-none">
          </div>
        </div>
      `;
    } else if (this.moduloActivo === 'palpaciones') {
      inputsModulo = `
        <div class="grid grid-cols-1 sm:grid-cols-4 gap-3 bg-white p-4 rounded-xl border border-emerald-200">
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">📅 Fecha en que se palpó (Trabajo):</label>
            <input type="date" id="form-palp-fecha" value="${this.fechaJornada || hoy}" class="w-full px-2 py-3 sm:py-2 text-xs font-bold rounded-xl border border-slate-300 outline-none">
          </div>

          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Diagnóstico:</label>
            <select id="form-diagnostico" class="w-full px-3 py-3 sm:py-2 bg-white text-xs font-bold rounded-xl border border-slate-300 outline-none">
              <option value="Preñada" selected>🟢 Preñada (Gestante)</option>
              <option value="Vacía">🔴 Vacía (Abierta)</option>
              <option value="Sospechosa">🟡 Sospechosa</option>
            </select>
          </div>

          <div id="box-dias-gestacion">
            <label class="block text-xs font-bold text-slate-800 mb-1">Días de Preñez Estimados:</label>
            <input type="number" inputmode="numeric" id="form-dias-preñez" value="60" class="w-full px-3 py-3 sm:py-2 font-mono font-bold text-center rounded-xl border border-slate-300 outline-none">
          </div>

          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Estructura Ovárica / Notas:</label>
            <input type="text" id="form-estructura-ovario" placeholder="CL activo / Folículo / Dr..." class="w-full px-3 py-3 sm:py-2 text-xs rounded-xl border border-slate-300 outline-none">
          </div>
        </div>
      `;
    } else if (this.moduloActivo === 'leche') {
      inputsModulo = `
        <div class="grid grid-cols-1 sm:grid-cols-4 gap-3 bg-white p-4 rounded-xl border border-emerald-200">
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">📅 Fecha de pesaje de leche (Trabajo):</label>
            <input type="date" id="form-leche-fecha" value="${this.fechaJornada || hoy}" class="w-full px-2 py-3 sm:py-2 text-xs font-bold rounded-xl border border-slate-300 outline-none">
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Turno Mañana (L):</label>
            <input type="number" step="0.1" inputmode="decimal" id="form-leche-am" placeholder="0.0" class="w-full px-3 py-3 sm:py-2 font-mono font-bold text-right text-base rounded-xl border border-slate-300 outline-none">
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Turno Tarde (L):</label>
            <input type="number" step="0.1" inputmode="decimal" id="form-leche-pm" placeholder="0.0" class="w-full px-3 py-3 sm:py-2 font-mono font-bold text-right text-base rounded-xl border border-slate-300 outline-none">
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Notas Ubre / Calidad:</label>
            <input type="text" id="form-leche-notas" placeholder="Salud ubre / Mastitis..." class="w-full px-3 py-3 sm:py-2 text-xs rounded-xl border border-slate-300 outline-none">
          </div>
        </div>
      `;
    } else if (this.moduloActivo === 'partos') {
      inputsModulo = `
        <div class="grid grid-cols-1 sm:grid-cols-5 gap-3 bg-white p-4 rounded-xl border border-emerald-200">
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">📅 Fecha en que parió (Trabajo):</label>
            <input type="date" id="form-parto-fecha" value="${this.fechaJornada || hoy}" class="w-full px-2 py-3 sm:py-2 text-xs font-bold rounded-xl border border-slate-300">
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Sexo Cría:</label>
            <select id="form-parto-sexo" class="w-full px-2 py-3 sm:py-2 text-xs font-bold rounded-xl border border-slate-300">
              <option value="hembra">♀️ Hembra</option>
              <option value="macho">♂️ Macho</option>
            </select>
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Peso Cría (kg):</label>
            <input type="number" step="0.5" inputmode="decimal" id="form-parto-peso" value="32" class="w-full px-2 py-3 sm:py-2 font-mono text-center font-bold rounded-xl border border-slate-300">
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Tag Cría Generado:</label>
            <input type="text" id="form-parto-tag-cria" value="CRIA-${tag}" class="w-full px-2 py-3 sm:py-2 font-mono text-xs font-bold uppercase rounded-xl border border-slate-300">
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Tipo de Parto:</label>
            <select id="form-parto-tipo" class="w-full px-2 py-3 sm:py-2 text-xs font-bold rounded-xl border border-slate-300">
              <option value="Normal">Normal</option>
              <option value="Distócico">Distócico</option>
              <option value="Cesárea">Cesárea</option>
            </select>
          </div>
        </div>
      `;
    } else if (this.moduloActivo === 'destetes') {
      inputsModulo = `
        <div class="grid grid-cols-1 sm:grid-cols-4 gap-3 bg-white p-4 rounded-xl border border-emerald-200">
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">📅 Fecha en que se destetó (Trabajo):</label>
            <input type="date" id="form-destete-fecha" value="${this.fechaJornada || hoy}" class="w-full px-2 py-3 sm:py-2 text-xs font-bold rounded-xl border border-slate-300">
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Peso al Destete (kg):</label>
            <input type="number" step="0.5" inputmode="decimal" id="form-destete-peso" value="${a.ultimoPesoKg || ''}" placeholder="Ej. 185" class="w-full px-2 py-3 sm:py-2 font-mono text-center font-bold rounded-xl border border-slate-300">
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Lote Destino:</label>
            <input type="text" id="form-destete-lote" value="Lote Levante" placeholder="Ej. Lote Levante" class="w-full px-2 py-3 sm:py-2 text-xs font-bold rounded-xl border border-slate-300">
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Observaciones:</label>
            <input type="text" id="form-destete-obs" placeholder="Vacunación al destete, estado..." class="w-full px-2 py-3 sm:py-2 text-xs rounded-xl border border-slate-300">
          </div>
        </div>
      `;
    } else if (this.moduloActivo === 'extracciones') {
      inputsModulo = `
        <div class="bg-white p-4 rounded-xl border-2 border-rose-200 shadow-sm space-y-3">
          <div class="flex items-center justify-between border-b border-rose-100 pb-2">
            <span class="font-black text-rose-900 text-xs flex items-center gap-1.5">
              <span>🚪</span> Registro de Salida / Extracción de Manga
            </span>
            <span class="text-[10px] bg-rose-50 text-rose-700 font-bold px-2 py-0.5 rounded-full border border-rose-200">
              Venta / Muerte / Descarte
            </span>
          </div>
          <div class="grid grid-cols-1 sm:grid-cols-4 gap-3">
            <div>
              <label class="block text-xs font-bold text-slate-800 mb-1">📅 Fecha de Extracción (Trabajo):</label>
              <input type="date" id="form-extraer-fecha" value="${this.fechaJornada || hoy}" class="w-full px-2 py-3 sm:py-2 text-xs font-bold rounded-xl border border-slate-300">
            </div>
            <div>
              <label class="block text-xs font-bold text-slate-800 mb-1">Motivo de Extracción:</label>
              <select id="form-extraer-motivo" class="w-full px-2 py-3 sm:py-2 text-xs font-bold rounded-xl border-2 border-rose-300 bg-white">
                <option value="Venta" selected>💰 Venta Comercial</option>
                <option value="Muerte">☠️ Muerte</option>
                <option value="Descarte">⚠️ Descarte / Sacrificio</option>
              </select>
            </div>
            <div id="col-extraer-comprador">
              <label class="block text-xs font-bold text-slate-800 mb-1">Comprador / Destino:</label>
              <input type="text" id="form-extraer-comprador" placeholder="Ej. Frigorífico / Juan Pérez" class="w-full px-2 py-3 sm:py-2 text-xs font-bold rounded-xl border border-slate-300">
            </div>
            <div id="col-extraer-valor">
              <label class="block text-xs font-bold text-slate-800 mb-1">Valor Venta (COP $):</label>
              <input type="number" id="form-extraer-valor" step="1000" placeholder="Ej. 3500000" class="w-full px-2 py-3 sm:py-2 font-mono text-xs font-bold rounded-xl border border-slate-300">
            </div>
            <div id="col-extraer-peso">
              <label class="block text-xs font-bold text-slate-800 mb-1">Peso de Salida (kg):</label>
              <input type="number" id="form-extraer-peso" step="0.5" value="${a.ultimoPesoKg || a.pesoActual || ''}" placeholder="Ej. 480" class="w-full px-2 py-3 sm:py-2 font-mono text-xs font-bold rounded-xl border border-slate-300">
            </div>
            <div id="col-extraer-muerte" class="hidden sm:col-span-3">
              <label class="block text-xs font-bold text-rose-800 mb-1">Causa / Diagnóstico de Muerte o Descarte:</label>
              <input type="text" id="form-extraer-causa" placeholder="Ej. Picadura de culebra, Timpanismo, Neumonía, Fractura..." class="w-full px-2 py-3 sm:py-2 text-xs font-bold rounded-xl border border-rose-300 bg-rose-50/50">
            </div>
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Observaciones / Notas:</label>
            <input type="text" id="form-extraer-obs" placeholder="Detalles adicionales de la extracción de este ejemplar..." class="w-full px-2 py-3 sm:py-2 text-xs rounded-xl border border-slate-300">
          </div>
        </div>
      `;
    } else if (this.moduloActivo === 'servicios') {
      inputsModulo = `
        <div class="grid grid-cols-1 sm:grid-cols-5 gap-3 bg-white p-4 rounded-xl border border-indigo-200">
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">📅 Fecha en que se sirvió (Trabajo):</label>
            <input type="date" id="form-srv-fecha" value="${this.fechaJornada || hoy}" class="w-full px-2 py-3 sm:py-2 text-xs font-bold rounded-xl border border-slate-300">
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Modalidad:</label>
            <select id="form-srv-tipo" class="w-full px-2 py-3 sm:py-2 text-xs font-bold rounded-xl border border-slate-300 bg-white">
              <option value="inseminacion_artificial" selected>💉 Inseminación Artificial</option>
              <option value="transferencia_embriones">🔬 Transf. Embriones</option>
              <option value="monta_natural">🐂 Servicio con Toro</option>
            </select>
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Toro / Pajilla:</label>
            <input type="text" id="form-srv-reproductor" placeholder="Ej. TORO-08" class="w-full px-2 py-3 sm:py-2 font-mono text-xs font-bold rounded-xl border border-slate-300">
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Técnico:</label>
            <input type="text" id="form-srv-tecnico" placeholder="Inseminador" class="w-full px-2 py-3 sm:py-2 text-xs rounded-xl border border-slate-300">
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1">Protocolo:</label>
            <input type="text" id="form-srv-protocolo" placeholder="IATF" class="w-full px-2 py-3 sm:py-2 text-xs rounded-xl border border-slate-300">
          </div>
        </div>
      `;
    }

    return `
      <div class="bg-white p-4 rounded-2xl border border-emerald-300 shadow-md space-y-3">
        <!-- FICHA RESUMEN DEL ANIMAL EN LA MANGA -->
        <div class="flex flex-wrap items-center justify-between gap-2 border-b border-slate-100 pb-3">
          <div class="flex items-center gap-3">
            <span class="text-base sm:text-lg font-mono font-black bg-slate-900 text-white px-3 py-1 rounded-xl">
              Tag: ${tag}
            </span>
            <div>
              <div class="flex items-center gap-2">
                <span class="font-bold text-slate-900 text-sm">${a.nombreAlias || a.nombre || 'Sin Alias'}</span>
                <span class="text-xs text-slate-500">• ${a.raza}</span>
                <span class="text-xs text-slate-500">• ${a.categoria}</span>
              </div>
              <div class="text-[11px] text-slate-500 flex items-center gap-2 mt-0.5">
                <span class="px-2 py-0.2 rounded text-[10px] font-bold ${especie === 'bufalino' ? 'bg-amber-100 text-amber-900' : 'bg-blue-100 text-blue-900'}">
                  ${especie === 'bufalino' ? '🦬 Especie Bufalina' : '🐂 Especie Vacuna'}
                </span>
                <span>Lote: <strong>${a.lote}</strong></span>
                <span>Estado: <strong>${a.estadoReproductivo || 'Vacía'}</strong> ${a.estadoReproductivo === 'Preñada' ? `(${a.diasGestacionActual || 0} d preñez)` : ''}</span>
              </div>
            </div>
          </div>

          <div class="flex items-center gap-2">
            ${this.onExtraerAnimal ? `
              <button id="btn-manga-extraer-animal" class="px-3 py-1.5 bg-amber-600 hover:bg-amber-500 active:scale-95 text-white font-bold text-xs rounded-xl shadow transition flex items-center gap-1 cursor-pointer" title="Extraer animal por venta o muerte">
                <span>🚪</span> Extraer Animal
              </button>
            ` : ''}
            <button id="btn-cerrar-animal-manga" class="text-slate-400 hover:text-slate-600 text-xs font-bold p-1 cursor-pointer">
              ✕ Cancelar
            </button>
          </div>
        </div>

        <!-- INPUTS ESPECÍFICOS DEL MÓDULO -->
        ${inputsModulo}

        <!-- FEEDBACK DE IA EN TIEMPO REAL -->
        <div id="alerta-ia-manga" class="empty:hidden"></div>

        <!-- BOTÓN DE CONFIRMACIÓN -->
        <div class="flex justify-end pt-1">
          <button id="btn-agregar-a-sesion" class="w-full sm:w-auto px-6 py-3.5 sm:py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white font-black text-sm rounded-xl shadow-lg transition flex items-center justify-center gap-2 active:scale-95 cursor-pointer">
            <span>➕</span> Añadir Registro a la Sesión (Enter)
          </button>
        </div>
      </div>
    `;
  }

  renderFormularioIngreso() {
    const cont = this.container.querySelector('#contenedor-formulario-animal');
    if (cont) {
      cont.innerHTML = this.obtenerHtmlFormularioIngreso();
    }
    this.attachEventsFormulario();
  }

  attachEventsFormulario() {
    const a = this.animalSeleccionado;
    if (!a) return;

    // Cálculo dinámico de GDP en vivo mientras escribe peso o cambia fecha
    const inputPeso = this.container.querySelector('#form-nuevo-peso');
    const inputFechaPeso = this.container.querySelector('#form-peso-fecha');
    const gdpIndicador = this.container.querySelector('#live-gdp-indicator');
    const alertaIa = this.container.querySelector('#alerta-ia-manga');

    const recalcularLiveGDP = () => {
      const pNum = parseFloat(inputPeso?.value);
      const fPes = inputFechaPeso?.value || this.fechaJornada || new Date().toISOString().split('T')[0];

      if (!isNaN(pNum) && pNum > 0) {
        const res = calcularGDPEjemplar({ animal: a, pesoActual: pNum, fechaPesaje: fPes });
        if (res && res.gdp !== null) {
          let color = 'text-emerald-700 font-bold';
          if (res.gdp < 300) color = 'text-rose-600 font-black';
          else if (res.gdp < 600) color = 'text-amber-600 font-bold';

          const detalleOrigen = res.origen === 'nacimiento'
            ? `🌱 Desde nacimiento (${res.dias} días de vida, peso base ${res.pesoBase || 0} kg)`
            : `⚖️ En ${res.dias} días contra pesaje anterior de ${res.pesoBase} kg`;

          gdpIndicador.innerHTML = `GDP (${fPes}): <span class="${color}">${res.gdp > 0 ? '+' : ''}${res.gdp} g/día</span> <span class="text-[10px] text-slate-500 block">${detalleOrigen}</span>`;
        } else {
          gdpIndicador.innerHTML = `<span class="text-[10px] text-slate-400">Sin antecedentes para calcular GDP (registre fecha nacimiento o pesaje previo)</span>`;
        }
      } else {
        gdpIndicador.innerHTML = '';
      }

      // Auditar IA
      if (inputPeso && alertaIa) {
        const errs = auditarPesajeInput(a, inputPeso.value, fPes, a.ultimoPesoKg ? [{ peso: a.ultimoPesoKg, fecha: a.fechaUltimoPesaje }] : []);
        if (errs.length > 0) {
          const e = errs[0];
          alertaIa.innerHTML = `
            <div class="p-2 rounded-xl text-xs ${e.tipo === 'error' ? 'bg-rose-100 text-rose-800 border border-rose-300 font-bold' : 'bg-amber-100 text-amber-800 border border-amber-300'}">
              ${e.mensaje}
            </div>
          `;
        } else {
          alertaIa.innerHTML = '';
        }
      }
    };

    if (inputPeso) {
      if (typeof inputPeso.focus === 'function') inputPeso.focus();
      inputPeso.addEventListener('input', recalcularLiveGDP);
    }
    if (inputFechaPeso) {
      inputFechaPeso.addEventListener('change', recalcularLiveGDP);
    }

    // Sincronizar fecha de trabajo desde el formulario hacia la jornada general
    const inputsFechaForm = this.container.querySelectorAll('#form-peso-fecha, #form-palp-fecha, #form-leche-fecha, #form-parto-fecha, #form-destete-fecha, #form-extraer-fecha, #form-srv-fecha');
    inputsFechaForm.forEach(inp => {
      inp.addEventListener('change', (e) => {
        const val = e.target.value;
        if (val) {
          this.fechaJornada = val;
          const inHdr = this.container.querySelector('#input-fecha-jornada-manga');
          if (inHdr && inHdr.value !== val) inHdr.value = val;
        }
      });
    });

    // Toggle de campos según motivo de extracción (Venta vs Muerte/Descarte)
    const selectMotivoExtraer = this.container.querySelector('#form-extraer-motivo');
    const colComprador = this.container.querySelector('#col-extraer-comprador');
    const colValor = this.container.querySelector('#col-extraer-valor');
    const colPeso = this.container.querySelector('#col-extraer-peso');
    const colMuerte = this.container.querySelector('#col-extraer-muerte');
    if (selectMotivoExtraer) {
      const actualizarCamposExtraer = () => {
        const esVenta = selectMotivoExtraer.value === 'Venta';
        if (colComprador) {
          if (!colComprador.style) colComprador.style = {};
          colComprador.style.display = esVenta ? 'block' : 'none';
        }
        if (colValor) {
          if (!colValor.style) colValor.style = {};
          colValor.style.display = esVenta ? 'block' : 'none';
        }
        if (colPeso) {
          if (!colPeso.style) colPeso.style = {};
          colPeso.style.display = esVenta ? 'block' : 'none';
        }
        if (colMuerte) {
          if (colMuerte.classList && typeof colMuerte.classList.toggle === 'function') {
            colMuerte.classList.toggle('hidden', esVenta);
          } else {
            if (!colMuerte.style) colMuerte.style = {};
            colMuerte.style.display = esVenta ? 'none' : 'block';
          }
        }
      };
      selectMotivoExtraer.addEventListener('change', actualizarCamposExtraer);
      actualizarCamposExtraer();
    }

    // Botón de extraer animal directamente desde la manga
    const btnExtraerManga = this.container.querySelector('#btn-manga-extraer-animal');
    if (btnExtraerManga) {
      btnExtraerManga.addEventListener('click', () => {
        if (this.onExtraerAnimal) {
          this.onExtraerAnimal(this.animalSeleccionado);
        }
      });
    }

    // Toggle de días de preñez según diagnóstico
    const diagSelect = this.container.querySelector('#form-diagnostico');
    const boxDias = this.container.querySelector('#box-dias-gestacion');
    if (diagSelect && boxDias) {
      diagSelect.addEventListener('change', () => {
        boxDias.style.display = diagSelect.value === 'Preñada' ? 'block' : 'none';
      });
    }

    // Botón agregar a sesión
    const btnAdd = this.container.querySelector('#btn-agregar-a-sesion');
    if (btnAdd) {
      btnAdd.addEventListener('click', () => this.confirmarRegistroActual());
    }

    const btnCerrar = this.container.querySelector('#btn-cerrar-animal-manga');
    if (btnCerrar) {
      btnCerrar.addEventListener('click', () => {
        this.animalSeleccionado = null;
        this.renderFormularioIngreso();
      });
    }

    // Tecla Enter para confirmar
    const contForm = this.container.querySelector('#contenedor-formulario-animal');
    if (contForm) {
      contForm.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
          e.preventDefault();
          this.confirmarRegistroActual();
        }
      });
    }
  }

  confirmarRegistroActual() {
    const a = this.animalSeleccionado;
    if (!a) return;

    const hoy = new Date().toISOString().split('T')[0];
    const tag = a.identificacionTag || a.numero;

    // Extraer fecha explícita del formulario según el módulo activo (o usa la fecha de la jornada)
    let fechaEvento = this.fechaJornada || hoy;
    if (this.moduloActivo === 'pesajes') {
      fechaEvento = this.container.querySelector('#form-peso-fecha')?.value || fechaEvento;
    } else if (this.moduloActivo === 'palpaciones') {
      fechaEvento = this.container.querySelector('#form-palp-fecha')?.value || fechaEvento;
    } else if (this.moduloActivo === 'leche') {
      fechaEvento = this.container.querySelector('#form-leche-fecha')?.value || fechaEvento;
    } else if (this.moduloActivo === 'partos') {
      fechaEvento = this.container.querySelector('#form-parto-fecha')?.value || fechaEvento;
    } else if (this.moduloActivo === 'destetes') {
      fechaEvento = this.container.querySelector('#form-destete-fecha')?.value || fechaEvento;
    } else if (this.moduloActivo === 'extracciones') {
      fechaEvento = this.container.querySelector('#form-extraer-fecha')?.value || fechaEvento;
    } else if (this.moduloActivo === 'servicios') {
      fechaEvento = this.container.querySelector('#form-srv-fecha')?.value || fechaEvento;
    }

    // Recordar la fecha seleccionada para los siguientes registros de la jornada
    this.fechaJornada = fechaEvento;

    const registro = {
      animalId: a.id,
      tag,
      especie: a.especie || 'bovino',
      nombre: a.nombreAlias || a.nombre,
      modulo: this.moduloActivo,
      fecha: fechaEvento
    };

    if (this.moduloActivo === 'pesajes') {
      const pInput = this.container.querySelector('#form-nuevo-peso');
      const peso = parseFloat(pInput?.value);
      if (isNaN(peso) || peso <= 0) {
        alert('Ingrese un peso válido.');
        return;
      }
      const pPrev = a.ultimoPesoKg || a.pesoActual || 0;
      const gdpRes = calcularGDPEjemplar({ animal: a, pesoActual: peso, fechaPesaje: fechaEvento });

      registro.pesoNuevo = peso;
      registro.pesoAnterior = pPrev;
      registro.gdp = gdpRes ? gdpRes.gdp : null;
      registro.gdpOrigen = gdpRes ? gdpRes.origen : null;
      registro.gdpDias = gdpRes ? gdpRes.dias : null;
      registro.condicionCorporal = this.container.querySelector('#form-condicion')?.value || '3.5';
      registro.observaciones = (this.container.querySelector('#form-peso-notas')?.value || '').trim();
    } else if (this.moduloActivo === 'palpaciones') {
      const resultado = this.container.querySelector('#form-diagnostico')?.value || 'Preñada';
      const diasG = parseInt(this.container.querySelector('#form-dias-preñez')?.value) || 0;
      registro.resultado = resultado;
      registro.diasGestacion = resultado === 'Preñada' ? diasG : 0;
      registro.estructuraOvario = (this.container.querySelector('#form-estructura-ovario')?.value || '').trim();
    } else if (this.moduloActivo === 'leche') {
      const am = parseFloat(this.container.querySelector('#form-leche-am')?.value) || 0;
      const pm = parseFloat(this.container.querySelector('#form-leche-pm')?.value) || 0;
      registro.litrosManana = am;
      registro.litrosTarde = pm;
      registro.totalLitros = parseFloat((am + pm).toFixed(1));
      registro.notasUbre = (this.container.querySelector('#form-leche-notas')?.value || '').trim();
    } else if (this.moduloActivo === 'partos') {
      registro.fechaParto = fechaEvento;
      registro.sexoCria = this.container.querySelector('#form-parto-sexo')?.value || 'hembra';
      registro.pesoCria = parseFloat(this.container.querySelector('#form-parto-peso')?.value) || 32;
      registro.tagCria = this.container.querySelector('#form-parto-tag-cria')?.value || `CRIA-${tag}`;
      registro.tipoParto = this.container.querySelector('#form-parto-tipo')?.value || 'Normal';
    } else if (this.moduloActivo === 'destetes') {
      const pDestete = parseFloat(this.container.querySelector('#form-destete-peso')?.value) || 0;
      const loteDestino = (this.container.querySelector('#form-destete-lote')?.value || 'Lote Levante').trim();
      const obs = (this.container.querySelector('#form-destete-obs')?.value || '').trim();
      registro.fechaDestete = fechaEvento;
      registro.pesoDestete = pDestete;
      registro.loteDestino = loteDestino;
      registro.observaciones = obs;
    } else if (this.moduloActivo === 'extracciones') {
      const motivo = this.container.querySelector('#form-extraer-motivo')?.value || 'Venta';
      const comprador = (this.container.querySelector('#form-extraer-comprador')?.value || '').trim();
      const valor = parseFloat(this.container.querySelector('#form-extraer-valor')?.value) || 0;
      const pesoSalida = parseFloat(this.container.querySelector('#form-extraer-peso')?.value) || parseFloat(a.ultimoPesoKg || a.pesoActual || 0);
      const causa = (this.container.querySelector('#form-extraer-causa')?.value || '').trim();
      const obs = (this.container.querySelector('#form-extraer-obs')?.value || '').trim();

      registro.fechaExtraccion = fechaEvento;
      registro.tipoExtraccion = motivo;
      registro.motivo = motivo;
      registro.comprador = comprador;
      registro.valorVenta = valor;
      registro.pesoVenta = pesoSalida;
      registro.motivoMuerte = causa;
      registro.observaciones = obs;
    } else if (this.moduloActivo === 'servicios') {
      const tipoSrv = this.container.querySelector('#form-srv-tipo')?.value || 'inseminacion_artificial';
      const reprod = (this.container.querySelector('#form-srv-reproductor')?.value || '').trim() || 'Pajilla / Toro General';
      const tec = (this.container.querySelector('#form-srv-tecnico')?.value || '').trim() || 'Inseminador';
      const proto = (this.container.querySelector('#form-srv-protocolo')?.value || '').trim() || 'IATF';

      registro.fechaServicio = fechaEvento;
      registro.tipoServicio = tipoSrv;
      registro.reproductor = reprod;
      registro.tecnico = tec;
      registro.protocolo = proto;
      registro.resultado = 'Pendiente Chequeo';
    }

    // Agregar al inicio de la sesión
    this.registrosSesion.unshift(registro);

    // Limpiar selección y preparar para el siguiente
    this.animalSeleccionado = null;
    this.render();

    // Enfocar input de búsqueda de nuevo
    setTimeout(() => {
      const inTag = this.container.querySelector('#input-tag-manga');
      if (inTag && typeof inTag.focus === 'function') inTag.focus();
    }, 50);
  }

  renderResumenMedicion(r) {
    if (r.modulo === 'pesajes') {
      const txtGdp = r.gdp !== null ? ` • GDP: ${r.gdp > 0 ? '+' : ''}${r.gdp} g/d` : '';
      return `Nuevo Peso: <strong>${r.pesoNuevo} kg</strong> (Previo: ${r.pesoAnterior || 0} kg) • CC: ${r.condicionCorporal}${txtGdp}`;
    } else if (r.modulo === 'palpaciones') {
      return `Diagnóstico: <strong>${r.resultado}</strong> ${r.resultado === 'Preñada' ? `(${r.diasGestacion} días de preñez)` : ''}`;
    } else if (r.modulo === 'destetes') {
      return `Destete: Peso <strong>${r.pesoDestete || 0} kg</strong> • Lote: <strong>${r.loteDestino || 'Levante'}</strong>`;
    } else if (r.modulo === 'extracciones') {
      if (r.tipoExtraccion === 'Venta') {
        return `Extracción: <strong>Venta</strong> a <strong>${r.comprador || 'Comprador'}</strong> • $${(r.valorVenta || 0).toLocaleString('es-CO')} (${r.pesoVenta || 0} kg)`;
      } else {
        return `Extracción: <strong>${r.tipoExtraccion || 'Baja'}</strong> • Causa: <strong>${r.motivoMuerte || 'No especificada'}</strong>`;
      }
    } else if (r.modulo === 'servicios') {
      const nomTipo = r.tipoServicio === 'transferencia_embriones' ? '🔬 TE' : (r.tipoServicio === 'monta_natural' ? '🐂 Monta' : '💉 IA');
      return `Servicio: <strong>${nomTipo}</strong> • Toro/Pajilla: <strong>${r.reproductor}</strong> • Téc: ${r.tecnico} (${r.protocolo})`;
    } else if (r.modulo === 'leche') {
      return `Producción: <strong>${r.totalLitros} Litros</strong> (Mañana: ${r.litrosManana}L, Tarde: ${r.litrosTarde}L)`;
    } else if (r.modulo === 'partos') {
      return `Parto: <strong>Cría ${r.tagCria}</strong> (${r.sexoCria === 'hembra' ? '♀️ Hembra' : '♂️ Macho'}, ${r.pesoCria} kg)`;
    }
    return '';
  }

  renderBadgeMedicion(r) {
    if (r.modulo === 'pesajes') {
      if (r.gdp !== null) {
        let b = 'bg-emerald-100 text-emerald-800';
        if (r.gdp < 300) b = 'bg-rose-100 text-rose-800 font-bold';
        else if (r.gdp < 600) b = 'bg-amber-100 text-amber-800';
        return `<span class="px-2 py-0.5 rounded-full text-xs ${b}">${r.gdp > 0 ? '+' : ''}${r.gdp} g/d</span>`;
      }
      return '<span class="text-slate-400 text-xs">Pesaje</span>';
    } else if (r.modulo === 'palpaciones') {
      return `<span class="px-2 py-0.5 rounded-full text-xs font-bold ${r.resultado === 'Preñada' ? 'bg-emerald-100 text-emerald-800' : 'bg-rose-100 text-rose-800'}">${r.resultado}</span>`;
    } else if (r.modulo === 'destetes') {
      return `<span class="px-2 py-0.5 rounded-full text-xs font-bold bg-amber-100 text-amber-800 border border-amber-300">🌾 Destetado</span>`;
    } else if (r.modulo === 'extracciones') {
      if (r.tipoExtraccion === 'Venta') {
        return `<span class="px-2 py-0.5 rounded-full text-xs font-bold bg-emerald-100 text-emerald-800 border border-emerald-300">💰 Venta</span>`;
      } else {
        return `<span class="px-2 py-0.5 rounded-full text-xs font-bold bg-rose-100 text-rose-800 border border-rose-300">☠️ ${r.tipoExtraccion || 'Baja'}</span>`;
      }
    } else if (r.modulo === 'servicios') {
      return `<span class="px-2 py-0.5 rounded-full text-xs font-bold bg-indigo-100 text-indigo-800 border border-indigo-300">🧬 Servida</span>`;
    } else if (r.modulo === 'leche') {
      return `<span class="px-2 py-0.5 rounded-full text-xs font-black bg-emerald-100 text-emerald-800">${r.totalLitros} L/d</span>`;
    } else if (r.modulo === 'partos') {
      return `<span class="px-2 py-0.5 rounded-full text-xs font-bold bg-purple-100 text-purple-800">Cría Registrada</span>`;
    }
    return '';
  }

  guardarSesionCompleta() {
    if (this.registrosSesion.length === 0) return;
    if (this.onGuardarRegistros) {
      this.onGuardarRegistros({
        modulo: this.moduloActivo,
        registros: this.registrosSesion
      });
      this.registrosSesion = [];
      this.render();
    }
  }

  attachEvents() {
    // Sincronizador de fecha de trabajo (sólo la cabecera superior)
    const inFechaJornada = this.container.querySelector('#input-fecha-jornada-manga');

    const sincronizarFecha = (nuevaFecha) => {
      if (!nuevaFecha) return;
      this.fechaJornada = nuevaFecha;
      if (inFechaJornada && inFechaJornada.value !== nuevaFecha) inFechaJornada.value = nuevaFecha;

      const formDateInputs = this.container.querySelectorAll('#form-peso-fecha, #form-palp-fecha, #form-leche-fecha, #form-parto-fecha, #form-destete-fecha, #form-extraer-fecha, #form-srv-fecha');
      formDateInputs.forEach(inp => {
        if (inp.value !== nuevaFecha) {
          inp.value = nuevaFecha;
          inp.dispatchEvent(new Event('change'));
        }
      });
    };

    if (inFechaJornada) {
      inFechaJornada.addEventListener('change', (e) => sincronizarFecha(e.target.value));
    }

    // Botón para aplicar fecha activa a todos los registros de la sesión actual
    const btnAplicarFechaSesion = this.container.querySelector('#btn-aplicar-fecha-sesion');
    if (btnAplicarFechaSesion) {
      btnAplicarFechaSesion.addEventListener('click', () => {
        if (this.registrosSesion.length === 0) return;
        const fechaActiva = this.fechaJornada || new Date().toISOString().split('T')[0];
        this.registrosSesion.forEach(reg => {
          reg.fecha = fechaActiva;
          if (reg.modulo === 'partos') reg.fechaParto = fechaActiva;
          if (reg.modulo === 'destetes') reg.fechaDestete = fechaActiva;
          if (reg.modulo === 'extracciones') reg.fechaExtraccion = fechaActiva;
          if (reg.modulo === 'servicios') reg.fechaServicio = fechaActiva;
          if (reg.modulo === 'pesajes' && reg.pesoNuevo) {
            const a = this.getAnimales ? this.getAnimales().find(item => item.id === reg.animalId || item.identificacionTag === reg.tag) : null;
            if (a) {
              const gdpRes = calcularGDPEjemplar({ animal: a, pesoActual: reg.pesoNuevo, fechaPesaje: fechaActiva });
              if (gdpRes) {
                reg.gdp = gdpRes.gdp;
                reg.gdpOrigen = gdpRes.origen;
                reg.gdpDias = gdpRes.dias;
              }
            }
          }
        });
        this.render();
        alert(`Se actualizó la fecha de trabajo de todos los ${this.registrosSesion.length} registros a ${fechaActiva}.`);
      });
    }

    // Cambio de módulo
    this.container.querySelectorAll('.btn-grid-mod').forEach((btn) => {
      btn.addEventListener('click', (e) => this.setModulo(e.currentTarget.getAttribute('data-mod')));
    });

    // Búsqueda en manga
    const inTag = this.container.querySelector('#input-tag-manga');
    const btnBuscar = this.container.querySelector('#btn-buscar-manga');

    const dispararBusqueda = () => {
      const val = inTag?.value;
      if (!val) return;
      const encontrado = this.buscarAnimalPorTag(val);
      if (encontrado) {
        if (encontrado._estaEnOtraFinca && this.onTrasladarAFinca) {
          const confirmar = confirm(`El animal "${val}" se encuentra registrado en "${encontrado._fincaNombre || 'otra finca'}".\n\n¿Deseas trasladarlo inmediatamente a esta finca de trabajo?`);
          if (confirmar) {
            this.onTrasladarAFinca(encontrado);
          }
        } else if (encontrado._estaExtraido && this.onReactivarAnimal) {
          const confirmar = confirm(`El animal "${val}" se encuentra actualmente EXTRAÍDO (${encontrado._motivoExtraido || 'Baja'}).\n\n¿Deseas reactivarlo e ingresarlo nuevamente al hato de esta finca?`);
          if (confirmar) {
            this.onReactivarAnimal(encontrado);
          }
        }
        this.seleccionarAnimal(val);
      } else {
        const crear = confirm(`El animal "${val}" no existe en el inventario. ¿Deseas cargarlo para crearlo automáticamente en este lote?`);
        if (crear) {
          this.animalSeleccionado = {
            identificacionTag: val.trim().toUpperCase(),
            especie: 'bovino',
            raza: 'Cruzada',
            sexo: 'hembra',
            categoria: 'Vaca de Ordeño',
            lote: this.loteFiltro !== 'todos' ? this.loteFiltro : 'General',
            ultimoPesoKg: 0,
            estadoReproductivo: 'Vacía'
          };
          this.renderFormularioIngreso();
        }
      }
    };

    if (btnBuscar) btnBuscar.addEventListener('click', dispararBusqueda);
    if (inTag) {
      conectarAutosuggestAnimales({
        inputElement: inTag,
        getAnimales: () => this.getAnimales ? this.getAnimales() : [],
        onSeleccionar: (animal) => {
          this.seleccionarAnimal(animal.identificacionTag);
        },
        onTrasladarAFinca: (animal) => {
          if (this.onTrasladarAFinca) this.onTrasladarAFinca(animal);
        },
        onReactivarAnimal: (animal) => {
          if (this.onReactivarAnimal) this.onReactivarAnimal(animal);
        },
        theme: 'emerald'
      });

      inTag.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
          e.preventDefault();
          dispararBusqueda();
        }
      });
    }

    // Botones de sesión
    const btnSave = this.container.querySelector('#btn-guardar-sesion');
    if (btnSave) btnSave.addEventListener('click', () => this.guardarSesionCompleta());

    const btnClear = this.container.querySelector('#btn-limpiar-sesion');
    if (btnClear) {
      btnClear.addEventListener('click', () => {
        if (confirm('¿Limpiar los registros de la sesión actual no guardados?')) {
          this.registrosSesion = [];
          this.render();
        }
      });
    }

    // Borrar fila de sesión
    this.container.querySelectorAll('button[data-action="delete-sesion-row"]').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const idx = parseInt(e.currentTarget.getAttribute('data-idx'));
        this.registrosSesion.splice(idx, 1);
        this.render();
      });
    });
  }
}


